diffs.replacement:
import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Job, ViewState } from './types';
import { searchAndParseJobs, analyzeJob, generateApplicationKit, enrichJob } from './services/geminiService';
import { initFirebase, subscribeToJobs, addOrUpdateJob, updateJobStatus, deleteJob, saveAnalysis, addManualJob } from './services/firebase';
import { DEFAULT_FIREBASE_CONFIG } from './constants';
import JobCard from './components/JobCard';
import StatsPanel from './components/StatsPanel';
import KanbanBoard from './components/KanbanBoard';
import CVEditor from './components/CVEditor';
import JobDetailModal from './components/JobDetailModal';
import AddLinkModal from './components/AddLinkModal';
import { LayoutGrid, Kanban, FileText, Plus, Search, Command, Sparkles, ArrowDownUp, Layers, Moon, Sun, User, LogOut, ChevronDown } from 'lucide-react';

const App: React.FC = () => {
  // Navigation & Data
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.DASHBOARD);
  const [activeTab, setActiveTab] = useState<'new' | 'saved' | 'archived'>('new');
  const [allJobs, setAllJobs] = useState<Job[]>([]);

  // Theme State
  const [darkMode, setDarkMode] = useState(() => {
    if (typeof window !== 'undefined') {
        return localStorage.getItem('theme') === 'dark' || 
               (!localStorage.getItem('theme') && window.matchMedia('(prefers-color-scheme: dark)').matches);
    }
    return false;
  });

  // Profile Menu State
  const [isProfileMenuOpen, setIsProfileMenuOpen] = useState(false);
  const profileMenuRef = useRef<HTMLDivElement>(null);

  // Auto-Init Firebase
  const [isDbConnected] = useState(() => initFirebase(DEFAULT_FIREBASE_CONFIG));

  // Filter & Sort
  const [cityFilter, setCityFilter] = useState<string>('All');
  const [industryFilter, setIndustryFilter] = useState<string | null>(null);
  const [sortBy, setSortBy] = useState<'date' | 'score'>('date');

  // Status
  const [isFetching, setIsFetching] = useState(false);
  const [analyzingCount, setAnalyzingCount] = useState(0);

  // Modal
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedJob, setSelectedJob] = useState<Job | null>(null);
  const [initialModalTab, setInitialModalTab] = useState<'brief' | 'strategy'>('brief');
  const [isAddLinkOpen, setIsAddLinkOpen] = useState(false);

  // Theme Effect
  useEffect(() => {
      if (darkMode) {
          document.documentElement.classList.add('dark');
          localStorage.setItem('theme', 'dark');
      } else {
          document.documentElement.classList.remove('dark');
          localStorage.setItem('theme', 'light');
      }
  }, [darkMode]);

  // Click Outside Profile Menu
  useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
          if (profileMenuRef.current && !profileMenuRef.current.contains(event.target as Node)) {
              setIsProfileMenuOpen(false);
          }
      };
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (isDbConnected) {
      const unsubscribe = subscribeToJobs((jobs) => {
        const ninetyDaysAgo = Date.now() - (90 * 24 * 60 * 60 * 1000);
        jobs.forEach(job => {
            const scoutTime = job.scoutedAt || 0;
            if (scoutTime > 0 && scoutTime < ninetyDaysAgo && job.status !== 'archived') {
                updateJobStatus(job.id, 'archived');
            }
        });
        setAllJobs(jobs);
      });
      return () => unsubscribe();
    }
  }, [isDbConnected]);

  const fetchJobs = async () => {
    if (!isDbConnected) return;
    setIsFetching(true);
    const query = `("Product Designer" OR "UX Designer" OR "UI Designer") "United Kingdom" -Intern -Trainee -Apprentice`;
    try {
      const foundJobs = await searchAndParseJobs(query);
      const jobsToAnalyze: Job[] = [];
      for (const job of foundJobs) {
        const docId = `${job.title}_${job.company}`.toLowerCase().replace(/[^a-z0-9]/g, '_').substring(0, 100);
        const existing = allJobs.find(j => j.id === docId);
        const jobWithTimestamp = { ...job, scoutedAt: Date.now() };
        await addOrUpdateJob(jobWithTimestamp);
        if (!existing || !existing.analysis) {
           jobsToAnalyze.push({ ...jobWithTimestamp, id: docId });
        }
      }
      if (jobsToAnalyze.length > 0) analyzeNewJobs(jobsToAnalyze);
    } catch (error) { console.error(error); }
    setIsFetching(false);
  };

  const analyzeNewJobs = async (jobs: Job[]) => {
      setAnalyzingCount(prev => prev + jobs.length);
      for (const job of jobs) {
        try {
            const analysis = await analyzeJob(job);
            await saveAnalysis(job.id, analysis);
        } catch (e) {
            console.error(`Analysis failed for job ${job.id}`, e);
        } finally {
            setAnalyzingCount(prev => Math.max(0, prev - 1));
            await new Promise(resolve => setTimeout(resolve, 2000));
        }
      }
      setAnalyzingCount(0);
  };

  const handleOpenDetail = (job: Job, tab: 'brief' | 'strategy' = 'brief') => {
    setSelectedJob(job);
    setInitialModalTab(tab);
    setModalOpen(true);
  };

  const handleUpdateJob = async (updatedJob: Job) => {
      await addOrUpdateJob(updatedJob);
      if (selectedJob && selectedJob.id === updatedJob.id) {
          setSelectedJob(updatedJob);
      }
  };

  const handleReAnalyzeJob = async (job: Job) => {
      try {
          const analysis = await analyzeJob(job);
          await saveAnalysis(job.id, analysis);
          const updatedJob = { ...job, analysis };
          setSelectedJob(updatedJob);
          setAllJobs(prev => prev.map(j => j.id === job.id ? updatedJob : j));
      } catch (e) {
          console.error("Re-analysis failed", e);
      }
  };

  const handleGenerateKit = async (job: Job) => {
    if (!job.analysis) return;
    const content = await generateApplicationKit(job, job.analysis);
    const updatedAnalysis = { ...job.analysis, strategy: content };
    await saveAnalysis(job.id, updatedAnalysis);
  };

  const toggleJobStatus = (jobId: string, currentStatus: Job['status']) => {
    let newStatus: Job['status'] = 'saved';
    if (currentStatus === 'new') newStatus = 'saved';
    else if (currentStatus === 'saved') newStatus = 'new'; 
    else if (currentStatus === 'archived') newStatus = 'new';
    updateJobStatus(jobId, newStatus!);
  };

  const handleKanbanMove = (jobId: string, destination: Job['status']) => {
      updateJobStatus(jobId, destination!);
  };

  const handleDelete = (jobId: string) => {
    const job = allJobs.find(j => j.id === jobId);
    if (!job) return;
    if (job.status === 'archived') {
        if(confirm("Permanently delete?")) deleteJob(jobId);
    } else {
        updateJobStatus(jobId, 'archived');
    }
  };

  const handleAddManualJob = async (data: { url?: string, text?: string, title?: string, company?: string }) => {
      try {
          if (currentView !== ViewState.DASHBOARD && currentView !== ViewState.KANBAN) {
              setCurrentView(ViewState.DASHBOARD);
              setActiveTab('saved');
          }
          const placeholder = await addManualJob(data);
          if (!placeholder) return;

          setAnalyzingCount(prev => prev + 1);
          const enrichedDetails = await enrichJob(data);
          const enrichedJob = { 
              ...placeholder, 
              ...enrichedDetails,
              summary: enrichedDetails.summary || data.text || placeholder.summary
          };
          await addOrUpdateJob(enrichedJob);
          const analysis = await analyzeJob(enrichedJob);
          await saveAnalysis(enrichedJob.id, analysis);
      } catch (e) {
          console.error("Error adding manual job", e);
      } finally {
          setAnalyzingCount(prev => Math.max(0, prev - 1));
      }
  };

  // --- FILTER LOGIC ---
  const jobsInCurrentTab = useMemo(() => {
    return allJobs.filter(j => {
        const status = j.status || 'new';
        if (activeTab === 'new') return status === 'new';
        if (activeTab === 'saved') return ['saved', 'applied', 'interview', 'offer'].includes(status);
        if (activeTab === 'archived') return status === 'archived';
        return false;
    });
  }, [allJobs, activeTab]);

  const filteredJobs = useMemo(() => {
      return jobsInCurrentTab.filter(j => {
        const locMatch = cityFilter === 'All' ? true : (cityFilter === 'Other' ? !['edinburgh', 'glasgow', 'remote', 'london', 'manchester'].some(s => j.location.toLowerCase().includes(s)) : j.location.toLowerCase().includes(cityFilter.toLowerCase()));
        if (!locMatch) return false;

        if (industryFilter) {
            const ind = j.analysis?.industry || 'Tech';
            if (ind !== industryFilter) {
                 const text = (j.company + " " + j.title + " " + (j.summary || "")).toLowerCase();
                 let calculatedIndustry = 'Tech';
                 if (text.match(/bank|finance|wealth|fintech/)) calculatedIndustry = 'Fintech';
                 else if (text.match(/insurance|underwrit/)) calculatedIndustry = 'Insurance';
                 else if (text.match(/gov|public|council|nhs/)) calculatedIndustry = 'Public Sector';
                 else if (text.match(/agency|studio/)) calculatedIndustry = 'Agency';

                 if (calculatedIndustry !== industryFilter) return false;
            }
        }
        return true;
      }).sort((a, b) => {
          if (sortBy === 'score') {
              return (b.analysis?.score || 0) - (a.analysis?.score || 0);
          }
          return (b.scoutedAt || 0) - (a.scoutedAt || 0);
      });
  }, [jobsInCurrentTab, cityFilter, industryFilter, sortBy]);

  const filterOptions = ['All', 'Edinburgh', 'Glasgow', 'Remote', 'London', 'Manchester', 'Other'];

  return (
    <div className="min-h-screen bg-[#F5F5F7] dark:bg-black pb-20 font-sans overflow-x-hidden transition-colors duration-500 relative selection:bg-blue-100 dark:selection:bg-blue-900 selection:text-blue-900 dark:selection:text-blue-100">

        {/* AMBIENT BACKGROUND BLOBS */}
        <div className="fixed inset-0 z-0 pointer-events-none overflow-hidden">
            <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] rounded-full bg-blue-400/20 dark:bg-blue-600/10 blur-[120px] animate-blob mix-blend-multiply dark:mix-blend-screen" />
            <div className="absolute top-[-10%] right-[-10%] w-[50%] h-[50%] rounded-full bg-purple-400/20 dark:bg-purple-600/10 blur-[120px] animate-blob animate-delay-2000 mix-blend-multiply dark:mix-blend-screen" />
            <div className="absolute bottom-[-20%] left-[20%] w-[50%] h-[50%] rounded-full bg-pink-400/20 dark:bg-pink-600/10 blur-[120px] animate-blob animate-delay-4000 mix-blend-multiply dark:mix-blend-screen" />
        </div>

        {/* GLOBAL NAVIGATION BAR */}
        <nav className="fixed top-0 left-0 right-0 h-14 bg-white/70 dark:bg-[#1c1c1e]/70 backdrop-blur-xl z-[40] border-b border-black/5 dark:border-white/10 transition-colors duration-300">
            <div className="max-w-[1024px] mx-auto h-full flex items-center justify-between px-6">
                 <div className="flex items-center gap-6">
                     <span className="font-semibold text-base tracking-tight text-[#1d1d1f] dark:text-white flex items-center gap-2">
                        <div className="bg-black dark:bg-white text-white dark:text-black p-1 rounded-md">
                            <Layers size={14} /> 
                        </div>
                        Career Studio
                     </span>
                     <div className="hidden sm:flex items-center gap-1 text-[#86868b] dark:text-[#98989D] text-[13px] font-medium bg-black/5 dark:bg-white/10 p-1 rounded-full">
                         <button onClick={() => setCurrentView(ViewState.DASHBOARD)} className={`px-4 py-1 rounded-full transition-all ${currentView === ViewState.DASHBOARD ? 'bg-white dark:bg-[#636366] text-black dark:text-white shadow-sm' : 'hover:text-[#1d1d1f] dark:hover:text-white'}`}>Discover</button>
                         <button onClick={() => setCurrentView(ViewState.KANBAN)} className={`px-4 py-1 rounded-full transition-all ${currentView === ViewState.KANBAN ? 'bg-white dark:bg-[#636366] text-black dark:text-white shadow-sm' : 'hover:text-[#1d1d1f] dark:hover:text-white'}`}>Pipeline</button>
                         <button onClick={() => setCurrentView(ViewState.CV_EDITOR)} className={`px-4 py-1 rounded-full transition-all ${currentView === ViewState.CV_EDITOR ? 'bg-white dark:bg-[#636366] text-black dark:text-white shadow-sm' : 'hover:text-[#1d1d1f] dark:hover:text-white'}`}>Resume</button>
                     </div>
                 </div>

                 <div className="flex items-center gap-4">
                     {analyzingCount > 0 && (
                        <span className="flex items-center gap-1.5 text-[#0071e3] dark:text-[#0A84FF] font-medium text-[12px] bg-blue-50 dark:bg-blue-900/30 px-2 py-0.5 rounded-full border border-blue-100 dark:border-blue-800">
                            <Sparkles size={12} className="animate-spin" /> Analyzing...
                        </span>
                     )}

                     {/* Profile Dropdown */}
                     <div className="relative" ref={profileMenuRef}>
                        <button 
                            onClick={() => setIsProfileMenuOpen(!isProfileMenuOpen)}
                            className="w-8 h-8 rounded-full bg-gradient-to-tr from-gray-700 to-gray-500 text-white flex items-center justify-center text-[10px] font-bold shadow-md hover:scale-105 transition-all focus:outline-none"
                        >
                            VP
                        </button>

                        {isProfileMenuOpen && (
                            <div className="absolute top-full right-0 mt-2 w-56 bg-white/90 dark:bg-[#1C1C1E]/90 backdrop-blur-xl rounded-xl shadow-2xl border border-black/5 dark:border-white/10 overflow-hidden animate-in fade-in zoom-in-95 duration-200 origin-top-right z-50">
                                <div className="px-4 py-3 border-b border-[#f5f5f7] dark:border-[#38383A]">
                                    <p className="text-sm font-semibold text-[#1d1d1f] dark:text-white">Vyom Pathroliya</p>
                                    <p className="text-xs text-[#86868b] dark:text-[#98989D]">Senior UX Designer</p>
                                </div>
                                <div className="p-1">
                                    <button 
                                        onClick={() => setDarkMode(!darkMode)}
                                        className="w-full flex items-center justify-between px-3 py-2 text-sm text-[#1d1d1f] dark:text-[#f5f5f7] hover:bg-[#F5F5F7] dark:hover:bg-[#2C2C2E] rounded-lg transition-colors"
                                    >
                                        <div className="flex items-center gap-2">
                                            {darkMode ? <Moon size={16} /> : <Sun size={16} />}
                                            <span>Dark Mode</span>
                                        </div>

                                        {/* Toggle Switch Visual */}
                                        <div className={`w-9 h-5 rounded-full relative transition-colors ${darkMode ? 'bg-[#34C759]' : 'bg-[#E5E5EA]'}`}>
                                            <div className={`absolute top-0.5 left-0.5 w-4 h-4 rounded-full bg-white shadow-sm transition-transform ${darkMode ? 'translate-x-4' : 'translate-x-0'}`}></div>
                                        </div>
                                    </button>

                                    <button className="w-full flex items-center gap-2 px-3 py-2 text-sm text-[#1d1d1f] dark:text-[#f5f5f7] hover:bg-[#F5F5F7] dark:hover:bg-[#2C2C2E] rounded-lg transition-colors opacity-50 cursor-not-allowed">
                                        <User size={16} /> Profile Settings
                                    </button>
                                    <div className="h-px bg-[#f5f5f7] dark:bg-[#38383A] my-1"></div>
                                    <button className="w-full flex items-center gap-2 px-3 py-2 text-sm text-[#FF3B30] hover:bg-[#F5F5F7] dark:hover:bg-[#2C2C2E] rounded-lg transition-colors">
                                        <LogOut size={16} /> Sign Out
                                    </button>
                                </div>
                            </div>
                        )}
                     </div>
                 </div>
            </div>
        </nav>

        {/* HERO SECTION */}
        <div className={`pt-24 pb-10 ${currentView === ViewState.KANBAN ? 'w-full' : 'max-w-[1024px] mx-auto px-6'} relative z-10`}>
            {currentView === ViewState.DASHBOARD && (
                <>
                    <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 mb-12 animate-fade-in-up">
                        <div>
                            <h1 className="text-[48px] md:text-[64px] leading-[1.05] font-semibold text-[#1d1d1f] dark:text-white tracking-tighter mb-4 transition-colors">
                                Masterplan your <br/>
                                <span className="text-transparent bg-clip-text bg-gradient-to-r from-gray-500 to-gray-800 dark:from-gray-400 dark:to-gray-600">next move.</span>
                            </h1>
                            <p className="text-[#1d1d1f] dark:text-[#f5f5f7] text-lg font-medium max-w-lg leading-relaxed transition-colors">
                                <span className="text-[#0071e3] dark:text-[#0A84FF] font-semibold">{allJobs.filter(j => j.status === 'saved').length} opportunities</span> tailored to your experience.
                            </p>
                        </div>

                        <div className="flex gap-3 pb-2">
                             <button 
                                onClick={fetchJobs} 
                                disabled={isFetching}
                                className={`h-11 px-6 rounded-full bg-[#0071e3] hover:bg-[#0077ED] dark:bg-[#0A84FF] dark:hover:bg-[#409CFF] text-white text-[15px] font-medium transition-all flex items-center gap-2 ${isFetching ? 'opacity-70 cursor-not-allowed' : 'hover:scale-105 active:scale-95 shadow-lg shadow-blue-500/25'}`}
                             >
                                <Search size={18} /> {isFetching ? 'Scouting...' : 'Scout Jobs'}
                             </button>
                             <button 
                                onClick={() => setIsAddLinkOpen(true)}
                                className="h-11 w-11 flex items-center justify-center rounded-full bg-white dark:bg-[#38383A] text-[#1d1d1f] dark:text-white transition-all hover:scale-110 active:scale-90 shadow-md hover:shadow-lg"
                             >
                                <Plus size={20} />
                             </button>
                        </div>
                    </div>

                    {/* DASHBOARD GRID LAYOUT */}
                    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

                        {/* LEFT COLUMN: FILTERS & WIDGETS */}
                        <div className="lg:col-span-3 space-y-6 sticky top-[80px] self-start z-10 animate-fade-in-up animate-delay-200">
                            {/* Filter Widget - Glass Panel */}
                            <div className="glass-panel rounded-[24px] p-5 shadow-sm transition-colors">
                                <h3 className="text-[11px] font-bold text-[#86868b] dark:text-[#98989D] uppercase tracking-wider mb-3">Locations</h3>
                                <div className="space-y-1">
                                    {filterOptions.map(city => {
                                        const count = city === 'All' ? jobsInCurrentTab.length : jobsInCurrentTab.filter(j => city === 'Other' ? !['edinburgh', 'glasgow', 'remote', 'london', 'manchester'].some(s => j.location.toLowerCase().includes(s)) : j.location.toLowerCase().includes(city.toLowerCase())).length;
                                        if (count === 0 && city !== 'All') return null;
                                        const isSelected = cityFilter === city;
                                        return (
                                            <button 
                                                key={city} 
                                                onClick={() => setCityFilter(city)} 
                                                className={`w-full flex items-center justify-between px-3 py-2 rounded-lg text-[13px] transition-all duration-300 ${isSelected ? 'bg-white/80 dark:bg-white/10 font-semibold text-[#0071e3] dark:text-[#0A84FF] shadow-sm' : 'text-[#1d1d1f] dark:text-[#f5f5f7] hover:bg-white/50 dark:hover:bg-white/5'}`}
                                            >
                                                <span>{city}</span>
                                                <span className={`text-[11px] px-2 py-0.5 rounded-full ${isSelected ? 'bg-blue-100 dark:bg-blue-900/40 text-blue-700 dark:text-blue-300' : 'text-[#86868b] dark:text-[#98989D] bg-gray-100 dark:bg-gray-800'}`}>{count}</span>
                                            </button>
                                        );
                                    })}
                                </div>

                                <div className="w-full h-px bg-black/5 dark:bg-white/10 my-5"></div>

                                <StatsPanel 
                                    jobs={jobsInCurrentTab} 
                                    selectedIndustry={industryFilter}
                                    onSelectIndustry={setIndustryFilter}
                                />
                            </div>
                        </div>

                        {/* RIGHT COLUMN: CONTENT */}
                        <div className="lg:col-span-9 animate-fade-in-up animate-delay-200">
                            {/* Tabs Pill */}
                            <div className="flex items-center gap-2 mb-6 overflow-x-auto pb-2 scrollbar-hide">
                                {['new', 'saved', 'archived'].map((tab) => {
                                    const isActive = activeTab === tab;
                                    return (
                                        <button 
                                            key={tab}
                                            onClick={() => setActiveTab(tab as any)} 
                                            className={`px-5 py-2 rounded-full text-[13px] font-medium capitalize whitespace-nowrap transition-all duration-300 ${isActive ? 'bg-[#1d1d1f] dark:bg-white text-white dark:text-black shadow-lg shadow-black/10 dark:shadow-white/10 scale-105' : 'bg-white/60 dark:bg-white/5 text-[#1d1d1f] dark:text-[#f5f5f7] border border-transparent hover:bg-white dark:hover:bg-white/10'}`}
                                        >
                                            {tab}
                                        </button>
                                    );
                                })}
                                <div className="ml-auto flex items-center gap-2 bg-white/50 dark:bg-black/20 px-3 py-1.5 rounded-full backdrop-blur-sm">
                                    <span className="text-[11px] text-[#86868b] dark:text-[#98989D] font-medium mr-1">Sort by:</span>
                                    <button 
                                        onClick={() => setSortBy(sortBy === 'date' ? 'score' : 'date')}
                                        className="text-[11px] font-bold text-[#0071e3] dark:text-[#0A84FF] hover:underline flex items-center gap-1"
                                    >
                                        {sortBy === 'date' ? 'Date' : 'Match Score'} <ArrowDownUp size={12}/>
                                    </button>
                                </div>
                            </div>

                            {/* Job List */}
                            <div className="space-y-6">
                                {filteredJobs.length === 0 ? (
                                    <div className="py-24 text-center text-[#86868b] dark:text-[#98989D] glass-panel rounded-3xl mx-auto max-w-md">
                                        <p className="text-lg font-medium">No opportunities found.</p>
                                        <button onClick={() => { setCityFilter('All'); setIndustryFilter(null); }} className="text-[#0071e3] dark:text-[#0A84FF] font-medium mt-2 hover:underline">Clear Filters</button>
                                    </div>
                                ) : (
                                    filteredJobs.map(job => (
                                        <JobCard key={job.id} job={job} onOpenDetail={handleOpenDetail} onToggleStatus={toggleJobStatus} onDelete={handleDelete} />
                                    ))
                                )}
                            </div>
                        </div>
                    </div>
                </>
            )}

            {currentView === ViewState.KANBAN && (
                <div className="h-[calc(100vh-100px)] animate-fade-in-up flex flex-col w-full">
                    <div className="flex items-center justify-between mb-8 w-full max-w-[1024px] mx-auto px-6">
                        <h1 className="text-[40px] font-semibold text-[#1d1d1f] dark:text-white tracking-tight">Pipeline</h1>
                        <button 
                            onClick={() => setIsAddLinkOpen(true)}
                            className="h-10 px-5 rounded-full bg-[#1d1d1f] dark:bg-white hover:bg-black dark:hover:bg-[#E5E5EA] text-white dark:text-black text-sm font-medium transition-all flex items-center gap-2 shadow-lg"
                        >
                            <Plus size={16} /> Add Job
                        </button>
                    </div>
                    <div className="flex-1 min-h-0 w-full">
                        <KanbanBoard 
                            jobs={allJobs} 
                            onGenerateKit={(job) => handleOpenDetail(job, 'strategy')}
                            onToggleStatus={handleKanbanMove}
                            onDelete={handleDelete}
                            onOpenDetail={handleOpenDetail}
                            onOpenAddModal={() => setIsAddLinkOpen(true)}
                        />
                    </div>
                </div>
            )}

            {currentView === ViewState.CV_EDITOR && (
                <div className="h-[calc(100vh-60px)] animate-fade-in-up flex flex-col items-center">
                    <div className="w-full max-w-[1024px] mb-6 px-6">
                        <h1 className="text-[40px] font-semibold text-[#1d1d1f] dark:text-white tracking-tight">Resume</h1>
                    </div>
                    <div className="flex-1 w-full relative">
                        <CVEditor />
                    </div>
                </div>
            )}
        </div>

      <JobDetailModal 
        isOpen={modalOpen} 
        onClose={() => setModalOpen(false)} 
        job={selectedJob} 
        onGenerateKit={handleGenerateKit}
        initialTab={initialModalTab}
        onUpdateJob={handleUpdateJob}
        onReAnalyze={handleReAnalyzeJob}
      />

      <AddLinkModal 
        isOpen={isAddLinkOpen}
        onClose={() => setIsAddLinkOpen(false)}
        onAdd={handleAddManualJob}
      />
    </div>
  );
};

export default App;

import React from 'react';
import { Job } from '../types';
import { Briefcase, MapPin, ExternalLink, Trash2, Bookmark, Archive, Zap } from 'lucide-react';

interface JobCardProps {
  job: Job;
  onOpenDetail: (job: Job, tab?: 'brief' | 'strategy') => void;
  onToggleStatus: (id: string, currentStatus: Job['status']) => void;
  onDelete: (id: string) => void;
  isKanban?: boolean;
}

const JobCard: React.FC<JobCardProps> = ({ job, onOpenDetail, onToggleStatus, onDelete, isKanban }) => {
  const analysis = job.analysis;
  const status = job.status || 'new';
  const isSavedOrBetter = ['saved', 'applied', 'interview', 'offer'].includes(status);

  const getAbsoluteUrl = (url?: string) => {
      if (!url || url === 'Manual Entry') return null;
      return url.startsWith('http') ? url : `https://${url}`;
  };

  const applyUrl = getAbsoluteUrl(job.url) || `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;

  // Tiny Card for Kanban - Ultra Compact
  if (isKanban) {
      return (
        <div 
            className="bg-white/90 dark:bg-[#1C1C1E]/90 backdrop-blur-md rounded-[16px] p-4 cursor-pointer shadow-sm hover:shadow-lg transition-all flex flex-col gap-2 border border-white/20 dark:border-white/5 hover:scale-[1.02] active:scale-[0.98] duration-300"
            onClick={() => onOpenDetail(job)}
        >
            <div className="flex justify-between items-start gap-1">
                <h4 className="font-bold text-[14px] text-[#1d1d1f] dark:text-[#f5f5f7] leading-snug line-clamp-2">
                    {job.title}
                </h4>
            </div>

            <p className="text-[12px] text-[#86868b] dark:text-[#98989D] font-medium truncate">{job.company}</p>

            <div className="flex items-center justify-between mt-2 pt-2 border-t border-black/5 dark:border-white/5">
                 {analysis?.score ? (
                     <span className={`px-2 py-0.5 rounded text-[10px] font-bold ${analysis.score > 70 ? 'bg-[#E6F4EA] dark:bg-[#1e3a29] text-[#137333] dark:text-[#45D469]' : 'bg-[#F5F5F7] dark:bg-[#2C2C2E] text-[#5F6368] dark:text-[#98989D]'}`}>
                        {analysis.score}%
                     </span>
                 ) : (
                    <span className="text-[10px] text-[#d2d2d7] dark:text-[#555]">No Score</span>
                 )}
                 <div className="flex items-center gap-1">
                    {job.seniorityScore === 'Senior' || job.seniorityScore === 'Lead' ? (
                        <div className="w-1.5 h-1.5 rounded-full bg-[#34C759]"></div>
                    ) : null}
                 </div>
            </div>
        </div>
      );
  }

  // Full "Bento" Card for Dashboard
  return (
    <div 
        onClick={() => onOpenDetail(job)}
        className={`apple-card p-8 group cursor-pointer relative overflow-hidden ${status === 'archived' ? 'opacity-60 grayscale' : ''}`}
    >

      {/* Top Right Actions */}
      <div className="absolute top-6 right-6 flex flex-col gap-2 opacity-0 group-hover:opacity-100 transition-all duration-300 translate-x-2 group-hover:translate-x-0 z-10">
         {status !== 'archived' && (
             <button 
                onClick={(e) => { e.stopPropagation(); onToggleStatus(job.id, status); }}
                className={`w-9 h-9 flex items-center justify-center rounded-full transition-all shadow-sm active:scale-90 ${isSavedOrBetter 
                    ? 'bg-[#0071e3] text-white hover:bg-[#0077ED] dark:bg-[#0A84FF]' 
                    : 'bg-white/80 dark:bg-[#2C2C2E]/80 backdrop-blur text-[#86868b] border border-[#d2d2d7] dark:border-[#38383A] hover:border-[#0071e3] hover:text-[#0071e3] dark:hover:border-[#0A84FF] dark:hover:text-[#0A84FF]'}`}
                title={isSavedOrBetter ? "Saved" : "Save Job"}
             >
                 <Bookmark size={16} fill={isSavedOrBetter ? "currentColor" : "none"} />
             </button>
         )}

         <button 
            onClick={(e) => { e.stopPropagation(); onDelete(job.id); }} 
            className="w-9 h-9 flex items-center justify-center rounded-full bg-white/80 dark:bg-[#2C2C2E]/80 backdrop-blur border border-[#d2d2d7] dark:border-[#38383A] hover:bg-[#FF3B30] hover:text-white hover:border-[#FF3B30] text-[#86868b] transition-all shadow-sm active:scale-90"
            title="Archive"
         >
            {status === 'archived' ? <Trash2 size={16} /> : <Archive size={16} />}
         </button>
      </div>

      <div className="flex flex-col sm:flex-row gap-6 items-start">

          {/* Main Content */}
          <div className="flex-1 pr-12">
             <div className="mb-2 flex items-center gap-3">
                 <h3 className="text-[22px] font-semibold text-[#1d1d1f] dark:text-[#f5f5f7] tracking-tight group-hover:text-[#0071e3] dark:group-hover:text-[#0A84FF] transition-colors">
                    {job.title}
                 </h3>
                 {job.isRelatedDiscovery && <span className="bg-[#FFCC00] text-black text-[10px] font-bold px-1.5 py-0.5 rounded shadow-sm">NEW</span>}
             </div>

             <div className="flex items-center gap-4 text-[13px] font-medium text-[#86868b] dark:text-[#98989D] mb-5">
                <span className="flex items-center gap-1.5"><Briefcase size={14}/> {job.company}</span>
                <span className="w-1 h-1 bg-[#d2d2d7] dark:bg-[#38383A] rounded-full"></span>
                <span className="flex items-center gap-1.5"><MapPin size={14}/> {job.location}</span>
                <span className="w-1 h-1 bg-[#d2d2d7] dark:bg-[#38383A] rounded-full"></span>
                <span>{job.postedDate}</span>
             </div>

             {/* Chip Row */}
             <div className="flex flex-wrap items-center gap-2 mb-6">
                {/* Match Badge */}
                {analysis?.score && (
                     <span className={`px-3 py-1 rounded-full text-[12px] font-bold flex items-center gap-1 border border-transparent ${analysis.score > 70 ? 'bg-[#1d1d1f] dark:bg-[#f5f5f7] text-white dark:text-black shadow-md' : 'bg-[#F5F5F7] dark:bg-[#2C2C2E] text-[#1d1d1f] dark:text-[#f5f5f7] border-black/5 dark:border-white/5'}`}>
                        <Zap size={12} fill={analysis.score > 70 ? "currentColor" : "none"} /> {analysis.score}% Match
                     </span>
                )}
                {analysis?.industry && (
                     <span className="px-3 py-1 rounded-full text-[12px] font-semibold bg-blue-50 dark:bg-blue-900/20 text-[#0071e3] dark:text-[#409CFF] border border-blue-100 dark:border-blue-800">{analysis.industry}</span>
                )}
                {analysis?.isHighValue && (
                     <span className="px-3 py-1 rounded-full text-[12px] font-semibold bg-green-50 dark:bg-green-900/20 text-[#34C759] border border-green-100 dark:border-green-800">High Value</span>
                )}
                 {job.seniorityScore && (
                     <span className="px-3 py-1 rounded-full text-[12px] font-semibold bg-gray-50 dark:bg-[#2C2C2E] text-[#1d1d1f] dark:text-[#f5f5f7] border border-gray-100 dark:border-gray-700">{job.seniorityScore}</span>
                )}
             </div>

             {/* Verdict */}
             {analysis && (
                 <p className="text-[15px] text-[#1d1d1f] dark:text-[#f5f5f7] leading-relaxed max-w-2xl mb-6 font-normal line-clamp-2 opacity-90">
                    {analysis.verdict}
                 </p>
             )}

             {/* Call to Actions */}
             <div className="flex items-center gap-4 pt-1">
                 <a 
                    href={applyUrl} 
                    target="_blank" 
                    rel="noopener noreferrer" 
                    onClick={(e) => e.stopPropagation()}
                    className="apple-button px-6 py-2.5 text-[13px] font-medium flex items-center gap-2 shadow-sm hover:shadow-md"
                 >
                     {getAbsoluteUrl(job.url) ? 'Apply Now' : 'Google Search'} <ExternalLink size={14} />
                 </a>
             </div>
          </div>
      </div>
    </div>
  );
};

export default JobCard;

import React, { useState } from 'react';
import { Job } from '../types';
import JobCard from './JobCard';
import { Bookmark, Send, Users, Trophy } from 'lucide-react';

interface KanbanBoardProps {
  jobs: Job[];
  onGenerateKit: (job: Job) => void;
  onToggleStatus: (id: string, status: Job['status']) => void;
  onDelete: (id: string) => void;
  onOpenDetail: (job: Job) => void;
  onOpenAddModal: () => void;
}

const KanbanBoard: React.FC<KanbanBoardProps> = ({ jobs, onGenerateKit, onToggleStatus, onDelete, onOpenDetail, onOpenAddModal }) => {
  const [draggedJobId, setDraggedJobId] = useState<string | null>(null);

  const columns: { id: Job['status'], title: string, icon: React.ReactNode, count: number }[] = [
      { id: 'saved', title: 'Saved', icon: <Bookmark size={14} />, count: jobs.filter(j => j.status === 'saved').length },
      { id: 'applied', title: 'Applied', icon: <Send size={14} />, count: jobs.filter(j => j.status === 'applied').length },
      { id: 'interview', title: 'Interview', icon: <Users size={14} />, count: jobs.filter(j => j.status === 'interview').length },
      { id: 'offer', title: 'Offer', icon: <Trophy size={14} />, count: jobs.filter(j => j.status === 'offer').length },
  ];

  const handleDragStart = (e: React.DragEvent, id: string) => {
      setDraggedJobId(id);
      e.dataTransfer.effectAllowed = "move";
      // Transparent drag image hack
      const img = new Image();
      img.src = 'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7';
      e.dataTransfer.setDragImage(img, 0, 0);
  };

  const handleDragOver = (e: React.DragEvent) => {
      e.preventDefault(); 
      e.dataTransfer.dropEffect = "move";
  };

  const handleDrop = (e: React.DragEvent, status: Job['status']) => {
      e.preventDefault();
      if (draggedJobId) {
          onToggleStatus(draggedJobId, status);
          setDraggedJobId(null);
      }
  };

  return (
    <div className="flex gap-6 overflow-x-auto w-full pb-8 pt-2 items-start h-full scrollbar-hide px-6">
      {/* Centering Wrapper for large screens */}
      <div className="flex gap-6 mx-auto">
        {columns.map(col => {
                const colJobs = jobs.filter(j => j.status === col.id);
                return (
                    <div 
                        key={col.id}
                        className="flex flex-col min-w-[340px] max-w-[340px] bg-white/40 dark:bg-[#1C1C1E]/40 rounded-[20px] p-2 h-full border border-white/50 dark:border-white/5 backdrop-blur-md shadow-sm transition-colors"
                        onDragOver={handleDragOver}
                        onDrop={(e) => handleDrop(e, col.id)}
                    >
                        <div className="flex items-center justify-between p-4 mb-1 shrink-0">
                            <h3 className="font-semibold text-[14px] text-[#1d1d1f] dark:text-[#f5f5f7] flex items-center gap-2 tracking-tight">
                                <span className={`p-1.5 rounded-md ${col.count > 0 ? 'bg-white/80 dark:bg-white/10 text-black dark:text-white shadow-sm' : 'text-gray-400'}`}>
                                    {col.icon}
                                </span> 
                                {col.title}
                            </h3>
                            <span className="text-[11px] font-bold text-[#86868b] dark:text-[#98989D] bg-white/50 dark:bg-[#2C2C2E]/50 px-2 py-0.5 rounded-full">{col.count}</span>
                        </div>

                        <div className="flex-1 space-y-3 overflow-y-auto px-2 pb-4 custom-scrollbar">
                            {colJobs.length === 0 && (
                                <div className="h-32 border-2 border-dashed border-[#d2d2d7]/30 dark:border-[#38383A] rounded-xl flex items-center justify-center m-2">
                                    <span className="text-[12px] text-[#86868b] dark:text-[#98989D] font-medium opacity-50">Drag jobs here</span>
                                </div>
                            )}
                            {colJobs.map(job => (
                                <div
                                    key={job.id}
                                    draggable
                                    onDragStart={(e) => handleDragStart(e, job.id)}
                                    className={`cursor-grab active:cursor-grabbing transition-all duration-200 ${draggedJobId === job.id ? 'opacity-50 scale-95' : 'hover:-translate-y-1'}`}
                                >
                                    <JobCard 
                                        job={job} 
                                        onOpenDetail={onOpenDetail}
                                        onToggleStatus={(id, st) => onToggleStatus(id, st)} 
                                        onDelete={onDelete} 
                                        isKanban={true}
                                    />
                                </div>
                            ))}
                        </div>
                    </div>
                );
        })}
      </div>
    </div>
  );
};

export default KanbanBoard;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Job, ViewState } from './types';
import { searchAndParseJobs, analyzeJob, generateApplicationKit, enrichJob } from './services/geminiService';
import { initFirebase, subscribeToJobs, addOrUpdateJob, updateJobStatus, deleteJob, saveAnalysis, addManualJob } from './services/firebase';
import { DEFAULT_FIREBASE_CONFIG } from './constants';
import JobCard from './components/JobCard';
import StatsPanel from './components/StatsPanel';
import KanbanBoard from './components/KanbanBoard';
import CVEditor from './components/CVEditor';
import JobDetailModal from './components/JobDetailModal';
import AddLinkModal from './components/AddLinkModal';
import { LayoutGrid, Kanban, FileText, Plus, Search, Command, Sparkles, ArrowDownUp, Layers, Moon, Sun, User, LogOut, ChevronDown } from 'lucide-react';

const App: React.FC = () => {
  // Navigation & Data
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.DASHBOARD);
  const [activeTab, setActiveTab] = useState<'new' | 'saved' | 'archived'>('new');
  const [allJobs, setAllJobs] = useState<Job[]>([]);

  // Theme State
  const [darkMode, setDarkMode] = useState(() => {
    if (typeof window !== 'undefined') {
        return localStorage.getItem('theme') === 'dark' || 
               (!localStorage.getItem('theme') && window.matchMedia('(prefers-color-scheme: dark)').matches);
    }
    return false;
  });

  // Profile Menu State
  const [isProfileMenuOpen, setIsProfileMenuOpen] = useState(false);
  const profileMenuRef = useRef<HTMLDivElement>(null);

  // Auto-Init Firebase
  const [isDbConnected] = useState(() => initFirebase(DEFAULT_FIREBASE_CONFIG));

  // Filter & Sort
  const [cityFilter, setCityFilter] = useState<string>('All');
  const [industryFilter, setIndustryFilter] = useState<string | null>(null);
  const [sortBy, setSortBy] = useState<'date' | 'score'>('date');

  // Status
  const [isFetching, setIsFetching] = useState(false);
  const [analyzingCount, setAnalyzingCount] = useState(0);

  // Modal
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedJob, setSelectedJob] = useState<Job | null>(null);
  const [initialModalTab, setInitialModalTab] = useState<'brief' | 'strategy'>('brief');
  const [isAddLinkOpen, setIsAddLinkOpen] = useState(false);

  // Theme Effect
  useEffect(() => {
      if (darkMode) {
          document.documentElement.classList.add('dark');
          localStorage.setItem('theme', 'dark');
      } else {
          document.documentElement.classList.remove('dark');
          localStorage.setItem('theme', 'light');
      }
  }, [darkMode]);

  // Click Outside Profile Menu
  useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
          if (profileMenuRef.current && !profileMenuRef.current.contains(event.target as Node)) {
              setIsProfileMenuOpen(false);
          }
      };
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (isDbConnected) {
      const unsubscribe = subscribeToJobs((jobs) => {
        const ninetyDaysAgo = Date.now() - (90 * 24 * 60 * 60 * 1000);
        jobs.forEach(job => {
            const scoutTime = job.scoutedAt || 0;
            if (scoutTime > 0 && scoutTime < ninetyDaysAgo && job.status !== 'archived') {
                updateJobStatus(job.id, 'archived');
            }
        });
        setAllJobs(jobs);
      });
      return () => unsubscribe();
    }
  }, [isDbConnected]);

  const fetchJobs = async () => {
    if (!isDbConnected) return;
    setIsFetching(true);
    const query = `("Product Designer" OR "UX Designer" OR "UI Designer") "United Kingdom" -Intern -Trainee -Apprentice`;
    try {
      const foundJobs = await searchAndParseJobs(query);
      const jobsToAnalyze: Job[] = [];
      for (const job of foundJobs) {
        const docId = `${job.title}_${job.company}`.toLowerCase().replace(/[^a-z0-9]/g, '_').substring(0, 100);
        const existing = allJobs.find(j => j.id === docId);
        const jobWithTimestamp = { ...job, scoutedAt: Date.now() };
        await addOrUpdateJob(jobWithTimestamp);
        if (!existing || !existing.analysis) {
           jobsToAnalyze.push({ ...jobWithTimestamp, id: docId });
        }
      }
      if (jobsToAnalyze.length > 0) analyzeNewJobs(jobsToAnalyze);
    } catch (error) { console.error(error); }
    setIsFetching(false);
  };

  const analyzeNewJobs = async (jobs: Job[]) => {
      setAnalyzingCount(prev => prev + jobs.length);
      for (const job of jobs) {
        try {
            const analysis = await analyzeJob(job);
            await saveAnalysis(job.id, analysis);
        } catch (e) {
            console.error(`Analysis failed for job ${job.id}`, e);
        } finally {
            setAnalyzingCount(prev => Math.max(0, prev - 1));
            await new Promise(resolve => setTimeout(resolve, 2000));
        }
      }
      setAnalyzingCount(0);
  };

  const handleOpenDetail = (job: Job, tab: 'brief' | 'strategy' = 'brief') => {
    setSelectedJob(job);
    setInitialModalTab(tab);
    setModalOpen(true);
  };

  const handleUpdateJob = async (updatedJob: Job) => {
      await addOrUpdateJob(updatedJob);
      if (selectedJob && selectedJob.id === updatedJob.id) {
          setSelectedJob(updatedJob);
      }
  };

  const handleReAnalyzeJob = async (job: Job) => {
      try {
          const analysis = await analyzeJob(job);
          await saveAnalysis(job.id, analysis);
          const updatedJob = { ...job, analysis };
          setSelectedJob(updatedJob);
          setAllJobs(prev => prev.map(j => j.id === job.id ? updatedJob : j));
      } catch (e) {
          console.error("Re-analysis failed", e);
      }
  };

  const handleGenerateKit = async (job: Job) => {
    if (!job.analysis) return;
    const content = await generateApplicationKit(job, job.analysis);
    const updatedAnalysis = { ...job.analysis, strategy: content };
    await saveAnalysis(job.id, updatedAnalysis);
  };

  const toggleJobStatus = (jobId: string, currentStatus: Job['status']) => {
    let newStatus: Job['status'] = 'saved';
    if (currentStatus === 'new') newStatus = 'saved';
    else if (currentStatus === 'saved') newStatus = 'new'; 
    else if (currentStatus === 'archived') newStatus = 'new';
    updateJobStatus(jobId, newStatus!);
  };

  const handleKanbanMove = (jobId: string, destination: Job['status']) => {
      updateJobStatus(jobId, destination!);
  };

  const handleDelete = (jobId: string) => {
    const job = allJobs.find(j => j.id === jobId);
    if (!job) return;
    if (job.status === 'archived') {
        if(confirm("Permanently delete?")) deleteJob(jobId);
    } else {
        updateJobStatus(jobId, 'archived');
    }
  };

  const handleAddManualJob = async (data: { url?: string, text?: string, title?: string, company?: string }) => {
      try {
          if (currentView !== ViewState.DASHBOARD && currentView !== ViewState.KANBAN) {
              setCurrentView(ViewState.DASHBOARD);
              setActiveTab('saved');
          }
          const placeholder = await addManualJob(data);
          if (!placeholder) return;

          setAnalyzingCount(prev => prev + 1);
          const enrichedDetails = await enrichJob(data);
          const enrichedJob = { 
              ...placeholder, 
              ...enrichedDetails,
              summary: enrichedDetails.summary || data.text || placeholder.summary
          };
          await addOrUpdateJob(enrichedJob);
          const analysis = await analyzeJob(enrichedJob);
          await saveAnalysis(enrichedJob.id, analysis);
      } catch (e) {
          console.error("Error adding manual job", e);
      } finally {
          setAnalyzingCount(prev => Math.max(0, prev - 1));
      }
  };

  // --- FILTER LOGIC ---
  const jobsInCurrentTab = useMemo(() => {
    return allJobs.filter(j => {
        const status = j.status || 'new';
        if (activeTab === 'new') return status === 'new';
        if (activeTab === 'saved') return ['saved', 'applied', 'interview', 'offer'].includes(status);
        if (activeTab === 'archived') return status === 'archived';
        return false;
    });
  }, [allJobs, activeTab]);

  const filteredJobs = useMemo(() => {
      return jobsInCurrentTab.filter(j => {
        const locMatch = cityFilter === 'All' ? true : (cityFilter === 'Other' ? !['edinburgh', 'glasgow', 'remote', 'london', 'manchester'].some(s => j.location.toLowerCase().includes(s)) : j.location.toLowerCase().includes(cityFilter.toLowerCase()));
        if (!locMatch) return false;

        if (industryFilter) {
            const ind = j.analysis?.industry || 'Tech';
            if (ind !== industryFilter) {
                 const text = (j.company + " " + j.title + " " + (j.summary || "")).toLowerCase();
                 let calculatedIndustry = 'Tech';
                 if (text.match(/bank|finance|wealth|fintech/)) calculatedIndustry = 'Fintech';
                 else if (text.match(/insurance|underwrit/)) calculatedIndustry = 'Insurance';
                 else if (text.match(/gov|public|council|nhs/)) calculatedIndustry = 'Public Sector';
                 else if (text.match(/agency|studio/)) calculatedIndustry = 'Agency';

                 if (calculatedIndustry !== industryFilter) return false;
            }
        }
        return true;
      }).sort((a, b) => {
          if (sortBy === 'score') {
              return (b.analysis?.score || 0) - (a.analysis?.score || 0);
          }
          return (b.scoutedAt || 0) - (a.scoutedAt || 0);
      });
  }, [jobsInCurrentTab, cityFilter, industryFilter, sortBy]);

  const filterOptions = ['All', 'Edinburgh', 'Glasgow', 'Remote', 'London', 'Manchester', 'Other'];

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 pb-20 font-sans overflow-x-hidden">

        {/* GLOBAL NAVIGATION BAR */}
        <nav className="fixed top-0 left-0 right-0 h-16 bg-white dark:bg-gray-800 z-[40] border-b border-gray-200 dark:border-gray-700">
            <div className="max-w-[1024px] mx-auto h-full flex items-center justify-between px-6">
                 <div className="flex items-center gap-6">
                     <span className="font-semibold text-base tracking-tight text-gray-900 dark:text-white flex items-center gap-2">
                        <div className="bg-blue-600 text-white p-1 rounded-md">
                            <Layers size={16} /> 
                        </div>
                        Career Studio
                     </span>
                     <div className="hidden sm:flex items-center gap-1 text-sm font-medium">
                         <button onClick={() => setCurrentView(ViewState.DASHBOARD)} className={`px-4 py-1.5 rounded-lg transition-all ${currentView === ViewState.DASHBOARD ? 'bg-gray-100 dark:bg-gray-700 text-gray-900 dark:text-white' : 'text-gray-500 hover:text-gray-900 dark:hover:text-white'}`}>Discover</button>
                         <button onClick={() => setCurrentView(ViewState.KANBAN)} className={`px-4 py-1.5 rounded-lg transition-all ${currentView === ViewState.KANBAN ? 'bg-gray-100 dark:bg-gray-700 text-gray-900 dark:text-white' : 'text-gray-500 hover:text-gray-900 dark:hover:text-white'}`}>Pipeline</button>
                         <button onClick={() => setCurrentView(ViewState.CV_EDITOR)} className={`px-4 py-1.5 rounded-lg transition-all ${currentView === ViewState.CV_EDITOR ? 'bg-gray-100 dark:bg-gray-700 text-gray-900 dark:text-white' : 'text-gray-500 hover:text-gray-900 dark:hover:text-white'}`}>Resume</button>
                     </div>
                 </div>

                 <div className="flex items-center gap-4">
                     {analyzingCount > 0 && (
                        <span className="flex items-center gap-1.5 text-blue-600 dark:text-blue-400 font-medium text-xs bg-blue-50 dark:bg-blue-900/30 px-2 py-0.5 rounded-full border border-blue-100 dark:border-blue-800">
                            <Sparkles size={12} className="animate-spin" /> Analyzing...
                        </span>
                     )}

                     {/* Profile Dropdown */}
                     <div className="relative" ref={profileMenuRef}>
