import React from 'react';
import { Job } from '../types';
import { Briefcase, MapPin, ExternalLink, Trash2, Bookmark, Archive, Zap } from 'lucide-react';

interface JobCardProps {
  job: Job;
  onOpenDetail: (job: Job, tab?: 'brief' | 'strategy') => void;
  onToggleStatus: (id: string, currentStatus: Job['status']) => void;
  onDelete: (id: string) => void;
  isKanban?: boolean;
}

const JobCard: React.FC<JobCardProps> = ({ job, onOpenDetail, onToggleStatus, onDelete, isKanban }) => {
  const analysis = job.analysis;
  const status = job.status || 'new';
  const isSavedOrBetter = ['saved', 'applied', 'interview', 'offer'].includes(status);

  const getAbsoluteUrl = (url?: string) => {
      if (!url || url === 'Manual Entry') return null;
      return url.startsWith('http') ? url : `https://${url}`;
  };

  const applyUrl = getAbsoluteUrl(job.url) || `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;

  // Tiny Card for Kanban
  if (isKanban) {
      return (
        <div 
            className="bg-white dark:bg-gray-800 rounded-lg p-4 cursor-pointer shadow-sm hover:shadow-md transition-shadow flex flex-col gap-2 border border-gray-200 dark:border-gray-700"
            onClick={() => onOpenDetail(job)}
        >
            <div className="flex justify-between items-start gap-1">
                <h4 className="font-bold text-sm text-gray-900 dark:text-gray-100 leading-snug line-clamp-2">
                    {job.title}
                </h4>
            </div>

            <p className="text-xs text-gray-500 dark:text-gray-400 font-medium truncate">{job.company}</p>

            <div className="flex items-center justify-between mt-2 pt-2 border-t border-gray-100 dark:border-gray-700">
                 {analysis?.score ? (
                     <span className={`px-2 py-0.5 rounded text-[10px] font-bold ${analysis.score > 70 ? 'bg-green-50 dark:bg-green-900/20 text-green-700 dark:text-green-400' : 'bg-gray-50 dark:bg-gray-700 text-gray-600 dark:text-gray-400'}`}>
                        {analysis.score}%
                     </span>
                 ) : (
                    <span className="text-[10px] text-gray-400">No Score</span>
                 )}
                 <div className="flex items-center gap-1">
                    {job.seniorityScore === 'Senior' || job.seniorityScore === 'Lead' ? (
                        <div className="w-1.5 h-1.5 rounded-full bg-green-500"></div>
                    ) : null}
                 </div>
            </div>
        </div>
      );
  }

  // Full Card for Dashboard
  return (
    <div 
        onClick={() => onOpenDetail(job)}
        className={`bg-white dark:bg-gray-800 rounded-xl p-6 border border-gray-200 dark:border-gray-700 shadow-sm hover:shadow-md transition-shadow cursor-pointer relative ${status === 'archived' ? 'opacity-60 grayscale' : ''}`}
    >

      {/* Top Right Actions */}
      <div className="absolute top-6 right-6 flex flex-col gap-2 opacity-0 hover:opacity-100 transition-opacity z-10">
         {status !== 'archived' && (
             <button 
                onClick={(e) => { e.stopPropagation(); onToggleStatus(job.id, status); }}
                className={`w-8 h-8 flex items-center justify-center rounded-full transition-colors ${isSavedOrBetter 
                    ? 'bg-blue-600 text-white hover:bg-blue-700' 
                    : 'bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 text-gray-400 hover:text-blue-600 hover:border-blue-600'}`}
                title={isSavedOrBetter ? "Saved" : "Save Job"}
             >
                 <Bookmark size={14} fill={isSavedOrBetter ? "currentColor" : "none"} />
             </button>
         )}

         <button 
            onClick={(e) => { e.stopPropagation(); onDelete(job.id); }} 
            className="w-8 h-8 flex items-center justify-center rounded-full bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 hover:bg-red-50 hover:text-red-600 hover:border-red-600 text-gray-400 transition-colors"
            title="Archive"
         >
            {status === 'archived' ? <Trash2 size={14} /> : <Archive size={14} />}
         </button>
      </div>

      <div className="flex flex-col sm:flex-row gap-6 items-start">

          {/* Main Content */}
          <div className="flex-1 pr-12">
             <div className="mb-2 flex items-center gap-3">
                 <h3 className="text-xl font-bold text-gray-900 dark:text-white leading-tight">
                    {job.title}
                 </h3>
                 {job.isRelatedDiscovery && <span className="bg-amber-100 text-amber-800 text-[10px] font-bold px-1.5 py-0.5 rounded">NEW</span>}
             </div>

             <div className="flex items-center gap-4 text-sm font-medium text-gray-500 dark:text-gray-400 mb-5">
                <span className="flex items-center gap-1.5"><Briefcase size={14}/> {job.company}</span>
                <span className="w-1 h-1 bg-gray-300 dark:bg-gray-600 rounded-full"></span>
                <span className="flex items-center gap-1.5"><MapPin size={14}/> {job.location}</span>
                <span className="w-1 h-1 bg-gray-300 dark:bg-gray-600 rounded-full"></span>
                <span>{job.postedDate}</span>
             </div>

             {/* Chip Row */}
             <div className="flex flex-wrap items-center gap-2 mb-4">
                {/* Match Badge */}
                {analysis?.score && (
                     <span className={`px-2.5 py-0.5 rounded-full text-xs font-bold flex items-center gap-1 ${analysis.score > 70 ? 'bg-gray-900 dark:bg-white text-white dark:text-black' : 'bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300'}`}>
                        <Zap size={12} fill={analysis.score > 70 ? "currentColor" : "none"} /> {analysis.score}% Match
                     </span>
                )}
                {analysis?.industry && (
                     <span className="px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-300 border border-blue-100 dark:border-blue-800">{analysis.industry}</span>
                )}
                {analysis?.isHighValue && (
                     <span className="px-2.5 py-0.5 rounded-full text-xs font-medium bg-green-50 dark:bg-green-900/20 text-green-700 dark:text-green-400 border border-green-100 dark:border-green-800">High Value</span>
                )}
                 {job.seniorityScore && (
                     <span className="px-2.5 py-0.5 rounded-full text-xs font-medium bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300">{job.seniorityScore}</span>
                )}
             </div>

             {/* Verdict */}
             {analysis && (
                 <p className="text-sm text-gray-600 dark:text-gray-300 leading-relaxed max-w-2xl mb-4 line-clamp-2">
                    {analysis.verdict}
                 </p>
             )}

             {/* Call to Actions */}
             <div className="flex items-center gap-4 pt-1">
                 <a 
                    href={applyUrl} 
                    target="_blank" 
                    rel="noopener noreferrer" 
                    onClick={(e) => e.stopPropagation()}
                    className="bg-blue-600 hover:bg-blue-700 text-white px-5 py-2 rounded-lg text-sm font-medium flex items-center gap-2 transition-colors"
                 >
                     {getAbsoluteUrl(job.url) ? 'Apply Now' : 'Google Search'} <ExternalLink size={14} />
                 </a>
             </div>
          </div>
      </div>
    </div>
  );
};

