import JobCard from './components/JobCard';
import StatsPanel from './components/StatsPanel';
import KanbanBoard from './components/KanbanBoard';
import CVEditor from './components/CVEditor';
import JobDetailModal from './components/JobDetailModal';
import AddLinkModal from './components/AddLinkModal';
import { LayoutGrid, Kanban, FileText, Plus, Search, Command, Sparkles, ArrowDownUp, Layers, Moon, Sun, User, LogOut, ChevronDown, MapPin } from 'lucide-react';

const LOCATION_IMAGES: Record<string, string> = {
  'Edinburgh': 'https://images.unsplash.com/photo-1506377295352-e3154d43ea9e?auto=format&fit=crop&w=600&q=80',
  'London': 'https://images.unsplash.com/photo-1513635269975-59663e0ac1ad?auto=format&fit=crop&w=600&q=80',
  'Remote': 'https://images.unsplash.com/photo-1593642632823-8f78536788c6?auto=format&fit=crop&w=600&q=80',
  'Manchester': 'https://images.unsplash.com/photo-1515586838455-8f8f940d6853?auto=format&fit=crop&w=600&q=80',
  'Glasgow': 'https://images.unsplash.com/photo-1563695738-98e986047a06?auto=format&fit=crop&w=600&q=80',
  'Other': 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?auto=format&fit=crop&w=600&q=80'
};

const App: React.FC = () => {
  // Navigation & Data
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.DASHBOARD);
  const [activeTab, setActiveTab] = useState<'new' | 'saved' | 'archived'>('new');
  const [allJobs, setAllJobs] = useState<Job[]>([]);

  // Theme State
  const [darkMode, setDarkMode] = useState(() => {
    if (typeof window !== 'undefined') {
        return localStorage.getItem('theme') === 'dark' || 
               (!localStorage.getItem('theme') && window.matchMedia('(prefers-color-scheme: dark)').matches);
    }
    return false;
  });

  // Profile Menu State
  const [isProfileMenuOpen, setIsProfileMenuOpen] = useState(false);
  const profileMenuRef = useRef<HTMLDivElement>(null);

  // Auto-Init Firebase
  const [isDbConnected] = useState(() => initFirebase(DEFAULT_FIREBASE_CONFIG));

  // Filter & Sort
  const [cityFilter, setCityFilter] = useState<string>('All');
  const [industryFilter, setIndustryFilter] = useState<string | null>(null);
  const [sortBy, setSortBy] = useState<'date' | 'score'>('date');

  // Status
  const [isFetching, setIsFetching] = useState(false);
  const [analyzingCount, setAnalyzingCount] = useState(0);

  // Modal
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedJob, setSelectedJob] = useState<Job | null>(null);
  const [initialModalTab, setInitialModalTab] = useState<'brief' | 'strategy'>('brief');
  const [isAddLinkOpen, setIsAddLinkOpen] = useState(false);

  // Theme Effect
  useEffect(() => {
      if (darkMode) {
          document.documentElement.classList.add('dark');
          localStorage.setItem('theme', 'dark');
      } else {
          document.documentElement.classList.remove('dark');
          localStorage.setItem('theme', 'light');
      }
  }, [darkMode]);

  // Click Outside Profile Menu
  useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
          if (profileMenuRef.current && !profileMenuRef.current.contains(event.target as Node)) {
              setIsProfileMenuOpen(false);
          }
      };
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (isDbConnected) {
      const unsubscribe = subscribeToJobs((jobs) => {
        const ninetyDaysAgo = Date.now() - (90 * 24 * 60 * 60 * 1000);
        jobs.forEach(job => {
            const scoutTime = job.scoutedAt || 0;
            if (scoutTime > 0 && scoutTime < ninetyDaysAgo && job.status !== 'archived') {
                updateJobStatus(job.id, 'archived');
            }
        });
        setAllJobs(jobs);
      });
      return () => unsubscribe();
    }
  }, [isDbConnected]);

  const fetchJobs = async () => {
    if (!isDbConnected) return;
    setIsFetching(true);
    const query = `("Product Designer" OR "UX Designer" OR "UI Designer") "United Kingdom" -Intern -Trainee -Apprentice`;
    try {
      const foundJobs = await searchAndParseJobs(query);
      const jobsToAnalyze: Job[] = [];
      for (const job of foundJobs) {
        const docId = `${job.title}_${job.company}`.toLowerCase().replace(/[^a-z0-9]/g, '_').substring(0, 100);
        const existing = allJobs.find(j => j.id === docId);
        const jobWithTimestamp = { ...job, scoutedAt: Date.now() };
        await addOrUpdateJob(jobWithTimestamp);
        if (!existing || !existing.analysis) {
           jobsToAnalyze.push({ ...jobWithTimestamp, id: docId });
        }
      }
      if (jobsToAnalyze.length > 0) analyzeNewJobs(jobsToAnalyze);
    } catch (error) { console.error(error); }
    setIsFetching(false);
  };

  const analyzeNewJobs = async (jobs: Job[]) => {
      setAnalyzingCount(prev => prev + jobs.length);
      for (const job of jobs) {
        try {
            const analysis = await analyzeJob(job);
            await saveAnalysis(job.id, analysis);
        } catch (e) {
            console.error(`Analysis failed for job ${job.id}`, e);
        } finally {
            setAnalyzingCount(prev => Math.max(0, prev - 1));
            await new Promise(resolve => setTimeout(resolve, 2000));
        }
      }
      setAnalyzingCount(0);
  };

  const handleOpenDetail = (job: Job, tab: 'brief' | 'strategy' = 'brief') => {
    setSelectedJob(job);
    setInitialModalTab(tab);
    setModalOpen(true);
  };

  const handleUpdateJob = async (updatedJob: Job) => {
      await addOrUpdateJob(updatedJob);
      if (selectedJob && selectedJob.id === updatedJob.id) {
          setSelectedJob(updatedJob);
      }
  };

  const handleReAnalyzeJob = async (job: Job) => {
      try {
          const analysis = await analyzeJob(job);
          await saveAnalysis(job.id, analysis);
          const updatedJob = { ...job, analysis };
          setSelectedJob(updatedJob);
          setAllJobs(prev => prev.map(j => j.id === job.id ? updatedJob : j));
      } catch (e) {
          console.error("Re-analysis failed", e);
      }
  };

  const handleGenerateKit = async (job: Job) => {
    if (!job.analysis) return;
    const content = await generateApplicationKit(job, job.analysis);
    const updatedAnalysis = { ...job.analysis, strategy: content };
    await saveAnalysis(job.id, updatedAnalysis);
  };

  const toggleJobStatus = (jobId: string, currentStatus: Job['status']) => {
    let newStatus: Job['status'] = 'saved';
    if (currentStatus === 'new') newStatus = 'saved';
    else if (currentStatus === 'saved') newStatus = 'new'; 
    else if (currentStatus === 'archived') newStatus = 'new';
    updateJobStatus(jobId, newStatus!);
  };

  const handleKanbanMove = (jobId: string, destination: Job['status']) => {
      updateJobStatus(jobId, destination!);
  };

  const handleDelete = (jobId: string) => {
    const job = allJobs.find(j => j.id === jobId);
    if (!job) return;
    if (job.status === 'archived') {
        if(confirm("Permanently delete?")) deleteJob(jobId);
    } else {
        updateJobStatus(jobId, 'archived');
    }
  };

  const handleAddManualJob = async (data: { url?: string, text?: string, title?: string, company?: string }) => {
      try {
          if (currentView !== ViewState.DASHBOARD && currentView !== ViewState.KANBAN) {
              setCurrentView(ViewState.DASHBOARD);
              setActiveTab('saved');
          }
          const placeholder = await addManualJob(data);
          if (!placeholder) return;

          setAnalyzingCount(prev => prev + 1);
          const enrichedDetails = await enrichJob(data);
          const enrichedJob = { 
              ...placeholder, 
              ...enrichedDetails,
              summary: enrichedDetails.summary || data.text || placeholder.summary
          };
          await addOrUpdateJob(enrichedJob);
          const analysis = await analyzeJob(enrichedJob);
          await saveAnalysis(enrichedJob.id, analysis);
      } catch (e) {
          console.error("Error adding manual job", e);
      } finally {
          setAnalyzingCount(prev => Math.max(0, prev - 1));
      }
  };

  // --- FILTER LOGIC ---
  const jobsInCurrentTab = useMemo(() => {
    return allJobs.filter(j => {
        const status = j.status || 'new';
        if (activeTab === 'new') return status === 'new';
        if (activeTab === 'saved') return ['saved', 'applied', 'interview', 'offer'].includes(status);
        if (activeTab === 'archived') return status === 'archived';
        return false;
    });
  }, [allJobs, activeTab]);

  const filteredJobs = useMemo(() => {
      return jobsInCurrentTab.filter(j => {
        const locMatch = cityFilter === 'All' ? true : (cityFilter === 'Other' ? !['edinburgh', 'glasgow', 'remote', 'london', 'manchester'].some(s => j.location.toLowerCase().includes(s)) : j.location.toLowerCase().includes(cityFilter.toLowerCase()));
        if (!locMatch) return false;

        if (industryFilter) {
            const ind = j.analysis?.industry || 'Tech';
            if (ind !== industryFilter) {
                 const text = (j.company + " " + j.title + " " + (j.summary || "")).toLowerCase();
                 let calculatedIndustry = 'Tech';
                 if (text.match(/bank|finance|wealth|fintech/)) calculatedIndustry = 'Fintech';
                 else if (text.match(/insurance|underwrit/)) calculatedIndustry = 'Insurance';
                 else if (text.match(/gov|public|council|nhs/)) calculatedIndustry = 'Public Sector';
                 else if (text.match(/agency|studio/)) calculatedIndustry = 'Agency';

                 if (calculatedIndustry !== industryFilter) return false;
            }
        }
        return true;
      }).sort((a, b) => {
          if (sortBy === 'score') {
              return (b.analysis?.score || 0) - (a.analysis?.score || 0);
          }
          return (b.scoutedAt || 0) - (a.scoutedAt || 0);
      });
  }, [jobsInCurrentTab, cityFilter, industryFilter, sortBy]);

  const filterOptions = ['Edinburgh', 'London', 'Remote', 'Manchester', 'Glasgow', 'Other'];

  return (
    <div className="min-h-screen bg-[#F5F5F7] dark:bg-black pb-20 font-sans overflow-x-hidden transition-colors duration-300">

        {/* GLOBAL NAVIGATION BAR */}
        <nav className="fixed top-0 left-0 right-0 h-14 bg-[#1d1d1f]/80 dark:bg-[#1c1c1e]/80 backdrop-blur-xl z-[40] border-b border-white/5 dark:border-white/10 transition-colors duration-300">
            <div className="max-w-[1024px] mx-auto h-full flex items-center justify-between px-6">
                 <div className="flex items-center gap-6">
                     <span className="font-semibold text-base tracking-tight text-white flex items-center gap-2"><Layers size={18} /> Career Studio</span>
                     <div className="hidden sm:flex items-center gap-6 text-[#d2d2d7]">
                         <button onClick={() => setCurrentView(ViewState.DASHBOARD)} className={`transition-colors hover:text-white ${currentView === ViewState.DASHBOARD ? 'text-white' : ''}`}>Discover</button>
                         <button onClick={() => setCurrentView(ViewState.KANBAN)} className={`transition-colors hover:text-white ${currentView === ViewState.KANBAN ? 'text-white' : ''}`}>Pipeline</button>
                         <button onClick={() => setCurrentView(ViewState.CV_EDITOR)} className={`transition-colors hover:text-white ${currentView === ViewState.CV_EDITOR ? 'text-white' : ''}`}>Resume</button>
                     </div>
                 </div>

                 <div className="flex items-center gap-4">
                     {analyzingCount > 0 && (
                        <span className="flex items-center gap-1.5 text-[#0071e3] dark:text-[#0A84FF] font-medium text-[12px]">
                            <Sparkles size={12} className="animate-spin" /> Analyzing...
                        </span>
                     )}

                     {/* Profile Dropdown */}
                     <div className="relative" ref={profileMenuRef}>
                        <button 
                            onClick={() => setIsProfileMenuOpen(!isProfileMenuOpen)}
                            className="w-8 h-8 rounded-full bg-gray-600 hover:bg-gray-500 text-white flex items-center justify-center text-[10px] font-bold ring-2 ring-white/10 transition-all focus:outline-none"
                        >
                            VP
                        </button>

                        {isProfileMenuOpen && (
                            <div className="absolute top-full right-0 mt-2 w-56 bg-white dark:bg-[#1C1C1E] rounded-xl shadow-xl border border-black/5 dark:border-white/10 overflow-hidden animate-in fade-in zoom-in-95 duration-200 z-50">
                                <div className="px-4 py-3 border-b border-[#f5f5f7] dark:border-[#38383A]">
                                    <p className="text-sm font-semibold text-[#1d1d1f] dark:text-white">Vyom Pathroliya</p>
                                    <p className="text-xs text-[#86868b] dark:text-[#98989D]">Senior UX Designer</p>
                                </div>
                                <div className="p-1">
                                    <button 
                                        onClick={() => setDarkMode(!darkMode)}
                                        className="w-full flex items-center justify-between px-3 py-2 text-sm text-[#1d1d1f] dark:text-[#f5f5f7] hover:bg-[#F5F5F7] dark:hover:bg-[#2C2C2E] rounded-lg transition-colors"
                                    >
                                        <div className="flex items-center gap-2">
                                            {darkMode ? <Moon size={16} /> : <Sun size={16} />}
                                            <span>Dark Mode</span>
                                        </div>

                                        {/* Toggle Switch Visual */}
                                        <div className={`w-9 h-5 rounded-full relative transition-colors ${darkMode ? 'bg-[#34C759]' : 'bg-[#E5E5EA]'}`}>
                                            <div className={`absolute top-0.5 left-0.5 w-4 h-4 rounded-full bg-white shadow-sm transition-transform ${darkMode ? 'translate-x-4' : 'translate-x-0'}`}></div>
                                        </div>
                                    </button>

                                    <button className="w-full flex items-center gap-2 px-3 py-2 text-sm text-[#1d1d1f] dark:text-[#f5f5f7] hover:bg-[#F5F5F7] dark:hover:bg-[#2C2C2E] rounded-lg transition-colors opacity-50 cursor-not-allowed">
                                        <User size={16} /> Profile Settings
                                    </button>
                                    <div className="h-px bg-[#f5f5f7] dark:bg-[#38383A] my-1"></div>
                                    <button className="w-full flex items-center gap-2 px-3 py-2 text-sm text-[#FF3B30] hover:bg-[#F5F5F7] dark:hover:bg-[#2C2C2E] rounded-lg transition-colors">
                                        <LogOut size={16} /> Sign Out
                                    </button>
                                </div>
                            </div>
                        )}
                     </div>
                 </div>
            </div>
        </nav>

        {/* MAIN CONTENT CONTAINER */}
        <div className={`pt-24 pb-10 ${currentView === ViewState.KANBAN ? 'w-full' : 'max-w-[1024px] mx-auto px-6'}`}>
            {currentView === ViewState.DASHBOARD && (
                <>
                    {/* VISUAL HERO SECTION */}
                    <div className="relative rounded-[32px] overflow-hidden bg-white dark:bg-[#1C1C1E] shadow-xl shadow-black/5 dark:shadow-black/20 mb-12 min-h-[400px] flex flex-col md:flex-row group animate-fade-in-up">
                        {/* Text Content */}
                        <div className="flex-1 p-10 md:p-14 flex flex-col justify-center z-10 relative">
                            <h1 className="text-[48px] md:text-[56px] leading-[1.05] font-semibold text-[#1d1d1f] dark:text-white tracking-tight mb-6 transition-colors">
                                Masterplan your <br/>
                                <span className="text-[#86868b] dark:text-[#98989D]">next move.</span>
                            </h1>
                            <p className="text-[#1d1d1f] dark:text-[#f5f5f7] text-lg font-medium max-w-sm leading-relaxed transition-colors mb-8">
                                <span className="text-[#0071e3] dark:text-[#0A84FF] font-semibold">{allJobs.filter(j => j.status === 'saved').length} opportunities</span> curated for your design career.
                            </p>

                             <div className="flex gap-4">
                                 <button 
                                    onClick={fetchJobs} 
                                    disabled={isFetching}
                                    className={`h-12 px-8 rounded-full bg-[#1d1d1f] hover:bg-[#000] dark:bg-white dark:hover:bg-[#f5f5f7] text-white dark:text-black text-[15px] font-semibold transition-all flex items-center gap-2 ${isFetching ? 'opacity-70 cursor-not-allowed' : 'hover:scale-105 active:scale-95 shadow-lg'}`}
                                 >
                                    <Search size={18} /> {isFetching ? 'Scouting...' : 'Scout Jobs'}
                                 </button>
                                 <button 
                                    onClick={() => setIsAddLinkOpen(true)}
                                    className="h-12 w-12 flex items-center justify-center rounded-full bg-[#E8E8ED] hover:bg-[#d2d2d7] dark:bg-[#38383A] dark:hover:bg-[#48484A] text-[#1d1d1f] dark:text-white transition-all hover:scale-105 active:scale-95"
                                 >
                                    <Plus size={20} />
                                 </button>
                            </div>
                        </div>

                        {/* Hero Image */}
                        <div className="md:w-[55%] relative h-64 md:h-auto overflow-hidden">
                            <img 
                                src="https://images.unsplash.com/photo-1497215728101-856f4ea42174?auto=format&fit=crop&w=1200&q=80" 
                                className="absolute inset-0 w-full h-full object-cover transition-transform duration-1000 group-hover:scale-105" 
                                alt="Workspace"
                            />
                            {/* Gradient Overlay for Text Readability if stacked, and smooth transition */}
                            <div className="absolute inset-0 bg-gradient-to-r from-white via-white/40 to-transparent dark:from-[#1C1C1E] dark:via-[#1C1C1E]/40 dark:to-transparent md:bg-gradient-to-r md:from-white md:via-transparent md:to-transparent md:dark:from-[#1C1C1E] md:dark:via-transparent"></div>
                        </div>
                    </div>

                    {/* DASHBOARD GRID LAYOUT */}
                    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

                        {/* LEFT COLUMN: FILTERS & WIDGETS */}
                        <div className="lg:col-span-3 space-y-8 sticky top-[80px] self-start z-10 animate-fade-in-up animate-delay-200">

                            {/* Visual Location Filter */}
                            <div>
                                <div className="flex items-center justify-between mb-4 px-1">
                                    <h3 className="text-[11px] font-bold text-[#86868b] dark:text-[#98989D] uppercase tracking-wider">Locations</h3>
                                    {cityFilter !== 'All' && (
                                        <button onClick={() => setCityFilter('All')} className="text-[10px] font-bold text-[#0071e3] hover:underline">Reset</button>
                                    )}
                                </div>
                                <div className="grid grid-cols-2 gap-3">
                                    {filterOptions.map(city => {
                                        const isSelected = cityFilter === city;
                                        const count = jobsInCurrentTab.filter(j => city === 'Other' ? !['edinburgh', 'glasgow', 'remote', 'london', 'manchester'].some(s => j.location.toLowerCase().includes(s)) : j.location.toLowerCase().includes(city.toLowerCase())).length;

                                        return (
                                            <div 
                                                key={city}
                                                onClick={() => setCityFilter(isSelected ? 'All' : city)}
                                                className={`relative h-24 rounded-2xl overflow-hidden cursor-pointer group border-2 transition-all duration-300 ${isSelected ? 'border-[#0071e3] dark:border-[#0A84FF] shadow-md scale-[1.02]' : 'border-transparent hover:scale-[1.02]'}`}
                                            >
                                                <img 
                                                    src={LOCATION_IMAGES[city] || LOCATION_IMAGES['Other']} 
                                                    className={`absolute inset-0 w-full h-full object-cover transition-all duration-500 ${isSelected ? 'brightness-100 grayscale-0' : 'brightness-75 grayscale group-hover:grayscale-0 group-hover:brightness-100'}`} 
                                                />
                                                <div className="absolute inset-0 bg-black/20 group-hover:bg-black/10 transition-colors"></div>
                                                <div className="absolute bottom-2 left-3 text-white">
                                                    <p className="text-[12px] font-bold leading-none">{city}</p>
                                                    {count > 0 && <span className="text-[10px] font-medium opacity-80">{count} jobs</span>}
                                                </div>
                                                {isSelected && (
                                                    <div className="absolute top-2 right-2 w-2 h-2 rounded-full bg-[#0071e3] shadow-sm"></div>
                                                )}
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>

                            <div className="w-full h-px bg-[#d2d2d7]/50 dark:bg-[#38383A]"></div>

                            {/* Stats Widget */}
                            <div className="bg-white dark:bg-[#1C1C1E] rounded-[24px] p-5 shadow-sm border border-black/5 dark:border-white/10">
                                <StatsPanel 
                                    jobs={jobsInCurrentTab} 
                                    selectedIndustry={industryFilter}
                                    onSelectIndustry={setIndustryFilter}
                                />
                            </div>
                        </div>

                        {/* RIGHT COLUMN: CONTENT */}
                        <div className="lg:col-span-9 animate-fade-in-up animate-delay-200">
                            {/* Tabs Pill */}
                            <div className="flex items-center gap-2 mb-6 overflow-x-auto pb-2 scrollbar-hide">
                                {['new', 'saved', 'archived'].map((tab) => {
                                    const isActive = activeTab === tab;
                                    return (
                                        <button 
                                            key={tab}
                                            onClick={() => setActiveTab(tab as any)} 
                                            className={`px-5 py-2 rounded-full text-[13px] font-medium capitalize whitespace-nowrap transition-all ${isActive ? 'bg-[#1d1d1f] dark:bg-white text-white dark:text-black' : 'bg-white dark:bg-[#1C1C1E] text-[#1d1d1f] dark:text-[#f5f5f7] border border-[#d2d2d7] dark:border-[#38383A] hover:border-[#86868b]'}`}
                                        >
                                            {tab}
                                        </button>
                                    );
                                })}
                                <div className="ml-auto flex items-center gap-2">
                                    <span className="text-[11px] text-[#86868b] dark:text-[#98989D] font-medium mr-1">Sort by:</span>
                                    <button 
                                        onClick={() => setSortBy(sortBy === 'date' ? 'score' : 'date')}
                                        className="text-[11px] font-bold text-[#0071e3] dark:text-[#0A84FF] hover:underline flex items-center gap-1"
                                    >
                                        {sortBy === 'date' ? 'Date' : 'Match Score'} <ArrowDownUp size={12}/>
                                    </button>
                                </div>
                            </div>

                            {/* Job List */}
                            <div className="space-y-6">
                                {filteredJobs.length === 0 ? (
                                    <div className="py-20 text-center text-[#86868b] dark:text-[#98989D]">
                                        <div className="w-16 h-16 bg-[#F5F5F7] dark:bg-[#2C2C2E] rounded-full flex items-center justify-center mx-auto mb-4">
                                            <Search size={24} className="opacity-50" />
                                        </div>
                                        <p className="text-lg font-medium">No opportunities found.</p>
                                        <button onClick={() => { setCityFilter('All'); setIndustryFilter(null); }} className="text-[#0071e3] dark:text-[#0A84FF] font-medium mt-2 hover:underline">Clear Filters</button>
                                    </div>
                                ) : (
                                    filteredJobs.map(job => (
                                        <JobCard key={job.id} job={job} onOpenDetail={handleOpenDetail} onToggleStatus={toggleJobStatus} onDelete={handleDelete} />
                                    ))
                                )}
                            </div>
                        </div>
                    </div>
                </>
            )}

            {currentView === ViewState.KANBAN && (
                <div className="h-[calc(100vh-100px)] animate-fade-in-up flex flex-col w-full">
                    <div className="flex items-center justify-between mb-8 w-full max-w-[1024px] mx-auto px-6">
                        <h1 className="text-[40px] font-semibold text-[#1d1d1f] dark:text-white tracking-tight">Pipeline</h1>
                        <button 
                            onClick={() => setIsAddLinkOpen(true)}
                            className="h-10 px-5 rounded-full bg-[#1d1d1f] dark:bg-white hover:bg-black dark:hover:bg-[#E5E5EA] text-white dark:text-black text-sm font-medium transition-all flex items-center gap-2 shadow-lg"
                        >
                            <Plus size={16} /> Add Job
                        </button>
                    </div>
                    <div className="flex-1 min-h-0 w-full">
                        <KanbanBoard 
                            jobs={allJobs} 
                            onGenerateKit={(job) => handleOpenDetail(job, 'strategy')}
                            onToggleStatus={handleKanbanMove}
                            onDelete={handleDelete}
                            onOpenDetail={handleOpenDetail}
                            onOpenAddModal={() => setIsAddLinkOpen(true)}
                        />
                    </div>
                </div>
            )}

            {currentView === ViewState.CV_EDITOR && (
                <div className="h-[calc(100vh-60px)] animate-fade-in-up flex flex-col items-center">
                    <div className="w-full max-w-[1024px] mb-6 px-6">
                        <h1 className="text-[40px] font-semibold text-[#1d1d1f] dark:text-white tracking-tight">Resume</h1>
                    </div>
                    <div className="flex-1 w-full relative">
                        <CVEditor />
                    </div>
                </div>
            )}
        </div>

      <JobDetailModal 
        isOpen={modalOpen} 
        onClose={() => setModalOpen(false)} 
        job={selectedJob} 
        onGenerateKit={handleGenerateKit}
        initialTab={initialModalTab}
        onUpdateJob={handleUpdateJob}
        onReAnalyze={handleReAnalyzeJob}
      />

      <AddLinkModal 
        isOpen={isAddLinkOpen}
        onClose={() => setIsAddLinkOpen(false)}
        onAdd={handleAddManualJob}
      />
    </div>
  );
};

export default App;

import React from 'react';
import { Job } from '../types';
import { Briefcase, MapPin, ExternalLink, Trash2, Bookmark, Archive, Zap, ArrowRight, TrendingUp } from 'lucide-react';

interface JobCardProps {
  job: Job;
  onOpenDetail: (job: Job, tab?: 'brief' | 'strategy') => void;
  onToggleStatus: (id: string, currentStatus: Job['status']) => void;
  onDelete: (id: string) => void;
  isKanban?: boolean;
}

const JobCard: React.FC<JobCardProps> = ({ job, onOpenDetail, onToggleStatus, onDelete, isKanban }) => {
  const analysis = job.analysis;
  const status = job.status || 'new';
  const isSavedOrBetter = ['saved', 'applied', 'interview', 'offer'].includes(status);

  const getAbsoluteUrl = (url?: string) => {
      if (!url || url === 'Manual Entry') return null;
      return url.startsWith('http') ? url : `https://${url}`;
  };

  const applyUrl = getAbsoluteUrl(job.url) || `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;

  // Generate a consistent color from string
  const getLogoColor = (name: string) => {
      const colors = [
          'bg-blue-500', 'bg-indigo-500', 'bg-purple-500', 'bg-pink-500', 
          'bg-red-500', 'bg-orange-500', 'bg-amber-500', 'bg-green-500', 
          'bg-teal-500', 'bg-cyan-500'
      ];
      let hash = 0;
      for (let i = 0; i < name.length; i++) {
          hash = name.charCodeAt(i) + ((hash << 5) - hash);
      }
      return colors[Math.abs(hash) % colors.length];
  };

  const getInitials = (name: string) => {
      return name
        .split(' ')
        .map(n => n[0])
        .slice(0, 2)
        .join('')
        .toUpperCase();
  };

  // Tiny Card for Kanban - Ultra Compact
  if (isKanban) {
      return (
        <div 
            className="bg-white dark:bg-[#1C1C1E] rounded-[12px] p-4 cursor-pointer shadow-[0_1px_3px_rgba(0,0,0,0.06)] hover:shadow-[0_4px_8px_rgba(0,0,0,0.08)] transition-all flex flex-col gap-2 border border-transparent hover:border-[#0071e3]/30 dark:hover:border-[#0A84FF]/30 dark:border-white/5"
            onClick={() => onOpenDetail(job)}
        >
            <div className="flex justify-between items-start gap-1">
                <h4 className="font-bold text-[14px] text-[#1d1d1f] dark:text-[#f5f5f7] leading-snug line-clamp-2">
                    {job.title}
                </h4>
            </div>

            <div className="flex items-center gap-2">
                 <div className={`w-5 h-5 rounded flex items-center justify-center text-[8px] font-bold text-white shrink-0 ${getLogoColor(job.company)}`}>
                     {getInitials(job.company)}
                 </div>
                 <p className="text-[12px] text-[#86868b] dark:text-[#98989D] font-medium truncate">{job.company}</p>
            </div>

            <div className="flex items-center justify-between mt-2 pt-2 border-t border-black/5 dark:border-white/5">
                 {analysis?.score ? (
                     <span className={`px-2 py-0.5 rounded text-[10px] font-bold ${analysis.score > 70 ? 'bg-[#E6F4EA] dark:bg-[#1e3a29] text-[#137333] dark:text-[#45D469]' : 'bg-[#F5F5F7] dark:bg-[#2C2C2E] text-[#5F6368] dark:text-[#98989D]'}`}>
                        {analysis.score}%
                     </span>
                 ) : (
                    <span className="text-[10px] text-[#d2d2d7] dark:text-[#555]">No Score</span>
                 )}
                 <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: job.seniorityScore === 'Senior' || job.seniorityScore === 'Lead' ? '#34C759' : '#FFCC00' }}></div>
            </div>
        </div>
      );
  }

  // Full "Bento" Card for Dashboard
  return (
    <div 
        onClick={() => onOpenDetail(job)}
        className={`apple-card p-6 md:p-8 group cursor-pointer border border-transparent relative hover:border-[#0071e3]/10 dark:hover:border-[#0A84FF]/20 ${status === 'archived' ? 'opacity-60 grayscale' : ''}`}
    >

      {/* Top Right Actions (No Overlap) */}
      <div className="absolute top-6 right-6 flex flex-col gap-2 opacity-0 group-hover:opacity-100 transition-opacity z-10">
         {status !== 'archived' && (
             <button 
                onClick={(e) => { e.stopPropagation(); onToggleStatus(job.id, status); }}
                className={`w-9 h-9 flex items-center justify-center rounded-full transition-colors shadow-sm ${isSavedOrBetter 
                    ? 'bg-[#0071e3] text-white hover:bg-[#0077ED] dark:bg-[#0A84FF]' 
                    : 'bg-white dark:bg-[#2C2C2E] text-[#86868b] border border-[#d2d2d7] dark:border-[#38383A] hover:border-[#0071e3] hover:text-[#0071e3] dark:hover:border-[#0A84FF] dark:hover:text-[#0A84FF]'}`}
                title={isSavedOrBetter ? "Saved" : "Save Job"}
             >
                 <Bookmark size={16} fill={isSavedOrBetter ? "currentColor" : "none"} />
             </button>
         )}

         <button 
            onClick={(e) => { e.stopPropagation(); onDelete(job.id); }} 
            className="w-9 h-9 flex items-center justify-center rounded-full bg-white dark:bg-[#2C2C2E] border border-[#d2d2d7] dark:border-[#38383A] hover:bg-[#FF3B30] hover:text-white hover:border-[#FF3B30] text-[#86868b] transition-colors shadow-sm"
            title="Archive"
         >
            {status === 'archived' ? <Trash2 size={16} /> : <Archive size={16} />}
         </button>
      </div>

      <div className="flex flex-col sm:flex-row gap-6 items-start">

          {/* Company Avatar */}
          <div className={`hidden sm:flex w-16 h-16 rounded-[20px] items-center justify-center text-xl font-bold text-white shadow-md shrink-0 ${getLogoColor(job.company)}`}>
              {getInitials(job.company)}
          </div>

          {/* Main Content */}
          <div className="flex-1 pr-0 md:pr-12">
             <div className="mb-1 flex items-center gap-3">
                 <h3 className="text-[22px] font-semibold text-[#1d1d1f] dark:text-[#f5f5f7] tracking-tight group-hover:text-[#0071e3] dark:group-hover:text-[#0A84FF] transition-colors leading-tight">
                    {job.title}
                 </h3>
                 {job.isRelatedDiscovery && <span className="bg-[#FFCC00] text-black text-[10px] font-bold px-1.5 py-0.5 rounded">NEW</span>}
             </div>

             <div className="flex items-center gap-4 text-[13px] font-medium text-[#86868b] dark:text-[#98989D] mb-5">
                <span className="flex items-center gap-2">
                    {/* Mobile Avatar */}
                    <span className={`sm:hidden w-5 h-5 rounded flex items-center justify-center text-[9px] font-bold text-white ${getLogoColor(job.company)}`}>{getInitials(job.company)}</span>
                    {job.company}
                </span>
                <span className="w-1 h-1 bg-[#d2d2d7] dark:bg-[#38383A] rounded-full"></span>
                <span className="flex items-center gap-1.5"><MapPin size={14}/> {job.location}</span>
                <span className="w-1 h-1 bg-[#d2d2d7] dark:bg-[#38383A] rounded-full"></span>
                <span>{job.postedDate}</span>
             </div>

             {/* Chip Row */}
             <div className="flex flex-wrap items-center gap-2 mb-6">
                {/* Match Badge Replaces Ring */}
                {analysis?.score && (
                     <span className={`px-3 py-1 rounded-full text-[12px] font-bold flex items-center gap-1 ${analysis.score > 70 ? 'bg-[#1d1d1f] dark:bg-[#f5f5f7] text-white dark:text-black' : 'bg-[#F5F5F7] dark:bg-[#2C2C2E] text-[#1d1d1f] dark:text-[#f5f5f7]'}`}>
                        <Zap size={12} fill={analysis.score > 70 ? "currentColor" : "none"} /> {analysis.score}% Match
                     </span>
                )}
                {analysis?.industry && (
                     <span className="px-3 py-1 rounded-full text-[12px] font-semibold bg-[#E8F2FF] dark:bg-[#122438] text-[#0071e3] dark:text-[#409CFF]">{analysis.industry}</span>
                )}
                {analysis?.isHighValue && (
                     <span className="px-3 py-1 rounded-full text-[12px] font-semibold bg-[#E6F4EA] dark:bg-[#1e3a29] text-[#34C759] flex items-center gap-1"><TrendingUp size={12}/> High Value</span>
                )}
                 {job.seniorityScore && (
                     <span className="px-3 py-1 rounded-full text-[12px] font-semibold bg-[#F5F5F7] dark:bg-[#2C2C2E] text-[#1d1d1f] dark:text-[#f5f5f7]">{job.seniorityScore}</span>
                )}
             </div>

             {/* Verdict - Clean text block */}
             {analysis && (
                 <p className="text-[15px] text-[#1d1d1f] dark:text-[#f5f5f7] leading-relaxed max-w-2xl mb-6 font-normal">
                    {analysis.verdict}
                 </p>
             )}

             {/* Call to Actions - Removed View Strategy Button */}
             <div className="flex items-center gap-4">
                 <a 
                    href={applyUrl} 
                    target="_blank" 
                    rel="noopener noreferrer" 
                    onClick={(e) => e.stopPropagation()}
                    className="apple-button px-6 py-2.5 text-[13px] font-medium flex items-center gap-2 shadow-sm hover:shadow-md"
                 >
                     {getAbsoluteUrl(job.url) ? 'Apply Now' : 'Google Search'} <ExternalLink size={14} />
                 </a>
             </div>
          </div>
      </div>
    </div>
  );
};

export default JobCard;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Job, ViewState } from './types';
import { searchAndParseJobs, analyzeJob, generateApplicationKit, enrichJob } from './services/geminiService';
import { initFirebase, subscribeToJobs, addOrUpdateJob, updateJobStatus, deleteJob, saveAnalysis, addManualJob } from './services/firebase';
import { DEFAULT_FIREBASE_CONFIG } from './constants';
import JobCard from './components/JobCard';
import StatsPanel from './components/StatsPanel';
import KanbanBoard from './components/KanbanBoard';
import CVEditor from './components/CVEditor';
import JobDetailModal from './components/JobDetailModal';
import AddLinkModal from './components/AddLinkModal';
import { LayoutGrid, Kanban, FileText, Plus, Search, Command, Sparkles, ArrowDownUp, Layers, Moon, Sun, User, LogOut, ChevronDown, MapPin, ChevronRight, Briefcase } from 'lucide-react';

const LOCATION_IMAGES: Record<string, string> = {
  'Edinburgh': 'https://images.unsplash.com/photo-1506377295352-e3154d43ea9e?auto=format&fit=crop&w=600&q=80',
  'London': 'https://images.unsplash.com/photo-1513635269975-59663e0ac1ad?auto=format&fit=crop&w=600&q=80',
  'Remote': 'https://images.unsplash.com/photo-1593642632823-8f78536788c6?auto=format&fit=crop&w=600&q=80',
  'Manchester': 'https://images.unsplash.com/photo-1515586838455-8f8f940d6853?auto=format&fit=crop&w=600&q=80',
  'Glasgow': 'https://images.unsplash.com/photo-1563695738-98e986047a06?auto=format&fit=crop&w=600&q=80',
  'Other': 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?auto=format&fit=crop&w=600&q=80'
};

const App: React.FC = () => {
  // Navigation & Data
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.DASHBOARD);
  const [activeTab, setActiveTab] = useState<'new' | 'saved' | 'archived'>('new');
  const [allJobs, setAllJobs] = useState<Job[]>([]);

  // Theme State
  const [darkMode, setDarkMode] = useState(() => {
    if (typeof window !== 'undefined') {
        return localStorage.getItem('theme') === 'dark' || 
               (!localStorage.getItem('theme') && window.matchMedia('(prefers-color-scheme: dark)').matches);
    }
    return false;
  });

  // Profile Menu State
  const [isProfileMenuOpen, setIsProfileMenuOpen] = useState(false);
  const profileMenuRef = useRef<HTMLDivElement>(null);

  // Auto-Init Firebase
  const [isDbConnected] = useState(() => initFirebase(DEFAULT_FIREBASE_CONFIG));

  // Filter & Sort
  const [cityFilter, setCityFilter] = useState<string>('All');
  const [industryFilter, setIndustryFilter] = useState<string | null>(null);
  const [sortBy, setSortBy] = useState<'date' | 'score'>('date');

  // Status
  const [isFetching, setIsFetching] = useState(false);
  const [analyzingCount, setAnalyzingCount] = useState(0);

  // Modal
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedJob, setSelectedJob] = useState<Job | null>(null);
  const [initialModalTab, setInitialModalTab] = useState<'brief' | 'strategy'>('brief');
  const [isAddLinkOpen, setIsAddLinkOpen] = useState(false);

  // Theme Effect
  useEffect(() => {
      if (darkMode) {
          document.documentElement.classList.add('dark');
          localStorage.setItem('theme', 'dark');
      } else {
          document.documentElement.classList.remove('dark');
          localStorage.setItem('theme', 'light');
      }
  }, [darkMode]);

  // Click Outside Profile Menu
  useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
          if (profileMenuRef.current && !profileMenuRef.current.contains(event.target as Node)) {
              setIsProfileMenuOpen(false);
          }
      };
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (isDbConnected) {
      const unsubscribe = subscribeToJobs((jobs) => {
        const ninetyDaysAgo = Date.now() - (90 * 24 * 60 * 60 * 1000);
        jobs.forEach(job => {
            const scoutTime = job.scoutedAt || 0;
            if (scoutTime > 0 && scoutTime < ninetyDaysAgo && job.status !== 'archived') {
                updateJobStatus(job.id, 'archived');
            }
        });
        setAllJobs(jobs);
      });
      return () => unsubscribe();
    }
  }, [isDbConnected]);

  const fetchJobs = async () => {
    if (!isDbConnected) return;
    setIsFetching(true);
    const query = `("Product Designer" OR "UX Designer" OR "UI Designer") "United Kingdom" -Intern -Trainee -Apprentice`;
    try {
      const foundJobs = await searchAndParseJobs(query);
      const jobsToAnalyze: Job[] = [];
      for (const job of foundJobs) {
        const docId = `${job.title}_${job.company}`.toLowerCase().replace(/[^a-z0-9]/g, '_').substring(0, 100);
        const existing = allJobs.find(j => j.id === docId);
        const jobWithTimestamp = { ...job, scoutedAt: Date.now() };
        await addOrUpdateJob(jobWithTimestamp);
        if (!existing || !existing.analysis) {
           jobsToAnalyze.push({ ...jobWithTimestamp, id: docId });
        }
      }
      if (jobsToAnalyze.length > 0) analyzeNewJobs(jobsToAnalyze);
    } catch (error) { console.error(error); }
    setIsFetching(false);
  };

  const analyzeNewJobs = async (jobs: Job[]) => {
      setAnalyzingCount(prev => prev + jobs.length);
      for (const job of jobs) {
        try {
            const analysis = await analyzeJob(job);
            await saveAnalysis(job.id, analysis);
        } catch (e) {
            console.error(`Analysis failed for job ${job.id}`, e);
        } finally {
            setAnalyzingCount(prev => Math.max(0, prev - 1));
            await new Promise(resolve => setTimeout(resolve, 2000));
        }
      }
      setAnalyzingCount(0);
  };

  const handleOpenDetail = (job: Job, tab: 'brief' | 'strategy' = 'brief') => {
    setSelectedJob(job);
    setInitialModalTab(tab);
    setModalOpen(true);
  };

  const handleUpdateJob = async (updatedJob: Job) => {
      await addOrUpdateJob(updatedJob);
      if (selectedJob && selectedJob.id === updatedJob.id) {
          setSelectedJob(updatedJob);
      }
  };

  const handleReAnalyzeJob = async (job: Job) => {
      try {
          const analysis = await analyzeJob(job);
          await saveAnalysis(job.id, analysis);
          const updatedJob = { ...job, analysis };
          setSelectedJob(updatedJob);
          setAllJobs(prev => prev.map(j => j.id === job.id ? updatedJob : j));
      } catch (e) {
          console.error("Re-analysis failed", e);
      }
  };

  const handleGenerateKit = async (job: Job) => {
    if (!job.analysis) return;
    const content = await generateApplicationKit(job, job.analysis);
    const updatedAnalysis = { ...job.analysis, strategy: content };
    await saveAnalysis(job.id, updatedAnalysis);
  };

  const toggleJobStatus = (jobId: string, currentStatus: Job['status']) => {
    let newStatus: Job['status'] = 'saved';
    if (currentStatus === 'new') newStatus = 'saved';
    else if (currentStatus === 'saved') newStatus = 'new'; 
    else if (currentStatus === 'archived') newStatus = 'new';
    updateJobStatus(jobId, newStatus!);
  };

  const handleKanbanMove = (jobId: string, destination: Job['status']) => {
      updateJobStatus(jobId, destination!);
  };

  const handleDelete = (jobId: string) => {
    const job = allJobs.find(j => j.id === jobId);
    if (!job) return;
    if (job.status === 'archived') {
        if(confirm("Permanently delete?")) deleteJob(jobId);
    } else {
        updateJobStatus(jobId, 'archived');
    }
  };

  const handleAddManualJob = async (data: { url?: string, text?: string, title?: string, company?: string }) => {
      try {
          if (currentView !== ViewState.DASHBOARD && currentView !== ViewState.KANBAN) {
              setCurrentView(ViewState.DASHBOARD);
              setActiveTab('saved');
          }
          const placeholder = await addManualJob(data);
          if (!placeholder) return;

          setAnalyzingCount(prev => prev + 1);
          const enrichedDetails = await enrichJob(data);
          const enrichedJob = { 
              ...placeholder, 
              ...enrichedDetails,
              summary: enrichedDetails.summary || data.text || placeholder.summary
          };
          await addOrUpdateJob(enrichedJob);
          const analysis = await analyzeJob(enrichedJob);
          await saveAnalysis(enrichedJob.id, analysis);
      } catch (e) {
          console.error("Error adding manual job", e);
      } finally {
          setAnalyzingCount(prev => Math.max(0, prev - 1));
      }
  };

  // --- FILTER LOGIC ---
  const jobsInCurrentTab = useMemo(() => {
    return allJobs.filter(j => {
        const status = j.status || 'new';
        if (activeTab === 'new') return status === 'new';
        if (activeTab === 'saved') return ['saved', 'applied', 'interview', 'offer'].includes(status);
        if (activeTab === 'archived') return status === 'archived';
        return false;
    });
  }, [allJobs, activeTab]);

  const filteredJobs = useMemo(() => {
      return jobsInCurrentTab.filter(j => {
        const locMatch = cityFilter === 'All' ? true : (cityFilter === 'Other' ? !['edinburgh', 'glasgow', 'remote', 'london', 'manchester'].some(s => j.location.toLowerCase().includes(s)) : j.location.toLowerCase().includes(cityFilter.toLowerCase()));
        if (!locMatch) return false;

        if (industryFilter) {
            const ind = j.analysis?.industry || 'Tech';
            if (ind !== industryFilter) {
                 const text = (j.company + " " + j.title + " " + (j.summary || "")).toLowerCase();
                 let calculatedIndustry = 'Tech';
                 if (text.match(/bank|finance|wealth|fintech/)) calculatedIndustry = 'Fintech';
                 else if (text.match(/insurance|underwrit/)) calculatedIndustry = 'Insurance';
                 else if (text.match(/gov|public|council|nhs/)) calculatedIndustry = 'Public Sector';
                 else if (text.match(/agency|studio/)) calculatedIndustry = 'Agency';

                 if (calculatedIndustry !== industryFilter) return false;
            }
        }
        return true;
      }).sort((a, b) => {
          if (sortBy === 'score') {
              return (b.analysis?.score || 0) - (a.analysis?.score || 0);
          }
          return (b.scoutedAt || 0) - (a.scoutedAt || 0);
      });
  }, [jobsInCurrentTab, cityFilter, industryFilter, sortBy]);

  const filterOptions = ['Edinburgh', 'London', 'Remote', 'Manchester', 'Glasgow', 'Other'];

  return (
    <div className="min-h-screen bg-[#F5F5F7] dark:bg-black pb-20 font-sans overflow-x-hidden transition-colors duration-300">

        {/* GLOBAL NAVIGATION BAR */}
        <nav className="fixed top-0 left-0 right-0 h-14 bg-[#1d1d1f]/80 dark:bg-[#1c1c1e]/80 backdrop-blur-xl z-[40] border-b border-white/5 dark:border-white/10 transition-colors duration-300">
            <div className="max-w-[1024px] mx-auto h-full flex items-center justify-between px-6">
                 <div className="flex items-center gap-6">
                     <span className="font-semibold text-base tracking-tight text-white flex items-center gap-2">
                        <Briefcase size={18} className="text-[#0071e3] dark:text-[#0A84FF]" /> 
                        JobAgent
                     </span>
                     <div className="hidden sm:flex items-center gap-6 text-[#d2d2d7]">
                         <button onClick={() => setCurrentView(ViewState.DASHBOARD)} className={`transition-colors hover:text-white ${currentView === ViewState.DASHBOARD ? 'text-white' : ''}`}>Discover</button>
                         <button onClick={() => setCurrentView(ViewState.KANBAN)} className={`transition-colors hover:text-white ${currentView === ViewState.KANBAN ? 'text-white' : ''}`}>Pipeline</button>
                         <button onClick={() => setCurrentView(ViewState.CV_EDITOR)} className={`transition-colors hover:text-white ${currentView === ViewState.CV_EDITOR ? 'text-white' : ''}`}>Resume</button>
                     </div>
                 </div>

                 <div className="flex items-center gap-4">
                     {analyzingCount > 0 && (
                        <span className="flex items-center gap-1.5 text-[#0071e3] dark:text-[#0A84FF] font-medium text-[12px]">
                            <Sparkles size={12} className="animate-spin" /> Analyzing...
                        </span>
                     )}

                     {/* Profile Dropdown */}
                     <div className="relative" ref={profileMenuRef}>
                        <button 
                            onClick={() => setIsProfileMenuOpen(!isProfileMenuOpen)}
                            className="w-8 h-8 rounded-full bg-gray-600 hover:bg-gray-500 text-white flex items-center justify-center text-[10px] font-bold ring-2 ring-white/10 transition-all focus:outline-none"
                        >
                            VP
                        </button>

                        {isProfileMenuOpen && (
                            <div className="absolute top-full right-0 mt-2 w-56 bg-white dark:bg-[#1C1C1E] rounded-xl shadow-xl border border-black/5 dark:border-white/10 overflow-hidden animate-in fade-in zoom-in-95 duration-200 z-50">
                                <div className="px-4 py-3 border-b border-[#f5f5f7] dark:border-[#38383A]">
                                    <p className="text-sm font-semibold text-[#1d1d1f] dark:text-white">Vyom Pathroliya</p>
                                    <p className="text-xs text-[#86868b] dark:text-[#98989D]">Senior UX Designer</p>
                                </div>
                                <div className="p-1">
                                    <button 
                                        onClick={() => setDarkMode(!darkMode)}
                                        className="w-full flex items-center justify-between px-3 py-2 text-sm text-[#1d1d1f] dark:text-[#f5f5f7] hover:bg-[#F5F5F7] dark:hover:bg-[#2C2C2E] rounded-lg transition-colors"
                                    >
                                        <div className="flex items-center gap-2">
                                            {darkMode ? <Moon size={16} /> : <Sun size={16} />}
                                            <span>Dark Mode</span>
                                        </div>

                                        {/* Toggle Switch Visual */}
                                        <div className={`w-9 h-5 rounded-full relative transition-colors ${darkMode ? 'bg-[#34C759]' : 'bg-[#E5E5EA]'}`}>
                                            <div className={`absolute top-0.5 left-0.5 w-4 h-4 rounded-full bg-white shadow-sm transition-transform ${darkMode ? 'translate-x-4' : 'translate-x-0'}`}></div>
                                        </div>
                                    </button>

                                    <button className="w-full flex items-center gap-2 px-3 py-2 text-sm text-[#1d1d1f] dark:text-[#f5f5f7] hover:bg-[#F5F5F7] dark:hover:bg-[#2C2C2E] rounded-lg transition-colors opacity-50 cursor-not-allowed">
                                        <User size={16} /> Profile Settings
                                    </button>
                                    <div className="h-px bg-[#f5f5f7] dark:bg-[#38383A] my-1"></div>
                                    <button className="w-full flex items-center gap-2 px-3 py-2 text-sm text-[#FF3B30] hover:bg-[#F5F5F7] dark:hover:bg-[#2C2C2E] rounded-lg transition-colors">
                                        <LogOut size={16} /> Sign Out
                                    </button>
                                </div>
                            </div>
                        )}
                     </div>
                 </div>
            </div>
        </nav>

        {/* MAIN CONTENT CONTAINER */}
        <div className={`pt-24 pb-10 ${currentView === ViewState.KANBAN ? 'w-full' : 'max-w-[1024px] mx-auto px-6'}`}>
            {currentView === ViewState.DASHBOARD && (
                <>
                    {/* VISUAL HERO SECTION */}
                    <div className="relative rounded-[32px] overflow-hidden bg-white dark:bg-[#1C1C1E] shadow-xl shadow-black/5 dark:shadow-black/20 mb-12 flex flex-col md:flex-row group animate-fade-in-up border border-transparent dark:border-white/10">
                        {/* Text Content */}
                        <div className="flex-1 p-10 md:p-14 flex flex-col justify-center z-10 relative bg-white dark:bg-[#1C1C1E]">
                            <h1 className="text-[48px] md:text-[56px] leading-[1.05] font-semibold text-[#1d1d1f] dark:text-white tracking-tight mb-6 transition-colors">
                                Stop searching. <br/>
                                <span className="text-[#86868b] dark:text-[#98989D]">Start interviewing.</span>
                            </h1>
                            <p className="text-[#1d1d1f] dark:text-[#f5f5f7] text-lg font-medium max-w-sm leading-relaxed transition-colors mb-8">
                                <span className="text-[#0071e3] dark:text-[#0A84FF] font-semibold">{allJobs.filter(j => j.status === 'saved').length} high-signal roles</span> matched to your experience.
                            </p>

                             <div className="flex gap-4">
                                 <button 
                                    onClick={fetchJobs} 
                                    disabled={isFetching}
                                    className={`h-12 px-8 rounded-full bg-[#0071e3] hover:bg-[#0077ED] text-white text-[15px] font-semibold transition-all flex items-center gap-2 ${isFetching ? 'opacity-70 cursor-not-allowed' : 'hover:scale-105 active:scale-95 shadow-lg shadow-blue-500/20'}`}
                                 >
                                    <Search size={18} /> {isFetching ? 'Scouting...' : 'Scout Jobs'}
                                 </button>
                                 <button 
                                    onClick={() => setIsAddLinkOpen(true)}
                                    className="h-12 w-12 flex items-center justify-center rounded-full bg-[#E8E8ED] hover:bg-[#d2d2d7] dark:bg-[#38383A] dark:hover:bg-[#48484A] text-[#1d1d1f] dark:text-white transition-all hover:scale-105 active:scale-95"
                                 >
                                    <Plus size={20} />
                                 </button>
                            </div>
                        </div>

                        {/* Hero Image */}
                        <div className="md:w-[50%] relative h-64 md:h-auto overflow-hidden">
                            <img 
                                src="https://images.unsplash.com/photo-1522202176988-66273c2fd55f?auto=format&fit=crop&w=1200&q=80" 
                                className="absolute inset-0 w-full h-full object-cover transition-transform duration-1000 group-hover:scale-105 opacity-90" 
                                alt="Workspace"
                            />
                            {/* Subtle fade to left to blend if needed, though split is usually cleaner */}
                            <div className="absolute inset-y-0 left-0 w-24 bg-gradient-to-r from-white dark:from-[#1C1C1E] to-transparent pointer-events-none md:block hidden"></div>
                        </div>
                    </div>

                    {/* DASHBOARD GRID LAYOUT */}
                    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

                        {/* LEFT COLUMN: FILTERS & WIDGETS */}
                        <div className="lg:col-span-3 space-y-6 sticky top-[80px] self-start z-10 animate-fade-in-up animate-delay-200">

