import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Job, ViewState } from './types';
import { searchAndParseJobs, analyzeJob, generateApplicationKit, enrichJob } from './services/geminiService';
import { initFirebase, subscribeToJobs, addOrUpdateJob, updateJobStatus, deleteJob, saveAnalysis, addManualJob } from './services/firebase';
import { DEFAULT_FIREBASE_CONFIG } from './constants';
import JobCard from './components/JobCard';
import StatsPanel from './components/StatsPanel';
import KanbanBoard from './components/KanbanBoard';
import CVEditor from './components/CVEditor';
import JobDetailModal from './components/JobDetailModal';
import AddLinkModal from './components/AddLinkModal';
import { LayoutGrid, Kanban, FileText, Plus, Search, Command, Sparkles, ArrowDownUp, Layers, Moon, Sun, User, LogOut, ChevronDown, Settings, X, Archive, Trash2 } from 'lucide-react';

const App: React.FC = () => {
  // Navigation & Data
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.DASHBOARD);
  const [activeTab, setActiveTab] = useState<'new' | 'saved' | 'archived'>('new');
  const [allJobs, setAllJobs] = useState<Job[]>([]);

  // Search Configuration
  const [searchRole, setSearchRole] = useState('Senior UX Designer');
  const [searchLocation, setSearchLocation] = useState('United Kingdom');
  const [isSearchSettingsOpen, setIsSearchSettingsOpen] = useState(false);
  const searchSettingsRef = useRef<HTMLDivElement>(null);

  // Multi-Select
  const [isSelectMode, setIsSelectMode] = useState(false);
  const [selectedJobIds, setSelectedJobIds] = useState<Set<string>>(new Set());

  // Theme State
  const [darkMode, setDarkMode] = useState(() => {
    if (typeof window !== 'undefined') {
        return localStorage.getItem('theme') === 'dark' || 
               (!localStorage.getItem('theme') && window.matchMedia('(prefers-color-scheme: dark)').matches);
    }
    return false;
  });

  // Profile Menu State
  const [isProfileMenuOpen, setIsProfileMenuOpen] = useState(false);
  const profileMenuRef = useRef<HTMLDivElement>(null);

  // Auto-Init Firebase
  const [isDbConnected] = useState(() => initFirebase(DEFAULT_FIREBASE_CONFIG));

  // Filter & Sort
  const [cityFilter, setCityFilter] = useState<string>('All');
  const [industryFilter, setIndustryFilter] = useState<string | null>(null);
  const [sortBy, setSortBy] = useState<'date' | 'score'>('date');

  // Status
  const [isFetching, setIsFetching] = useState(false);
  const [analyzingCount, setAnalyzingCount] = useState(0);

  // Modal
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedJob, setSelectedJob] = useState<Job | null>(null);
  const [initialModalTab, setInitialModalTab] = useState<'brief' | 'strategy'>('brief');
  const [isAddLinkOpen, setIsAddLinkOpen] = useState(false);

  // Theme Effect
  useEffect(() => {
      if (darkMode) {
          document.documentElement.classList.add('dark');
          localStorage.setItem('theme', 'dark');
      } else {
          document.documentElement.classList.remove('dark');
          localStorage.setItem('theme', 'light');
      }
  }, [darkMode]);

  // Click Outside Profile/Search Menu
  useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
          if (profileMenuRef.current && !profileMenuRef.current.contains(event.target as Node)) {
              setIsProfileMenuOpen(false);
          }
          if (searchSettingsRef.current && !searchSettingsRef.current.contains(event.target as Node)) {
              setIsSearchSettingsOpen(false);
          }
      };
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (isDbConnected) {
      const unsubscribe = subscribeToJobs((jobs) => {
        setAllJobs(jobs);
      });
      return () => unsubscribe();
    }
  }, [isDbConnected]);

  const fetchJobs = async () => {
    if (!isDbConnected) return;
    setIsFetching(true);
    try {
      const foundJobs = await searchAndParseJobs(searchRole, searchLocation);
      const jobsToAnalyze: Job[] = [];
      for (const job of foundJobs) {
        const docId = `${job.title}_${job.company}`.toLowerCase().replace(/[^a-z0-9]/g, '_').substring(0, 100);
        const existing = allJobs.find(j => j.id === docId);
        const jobWithTimestamp = { ...job, scoutedAt: Date.now() };
        await addOrUpdateJob(jobWithTimestamp);
        if (!existing || !existing.analysis) {
           jobsToAnalyze.push({ ...jobWithTimestamp, id: docId });
        }
      }
      if (jobsToAnalyze.length > 0) analyzeNewJobs(jobsToAnalyze);
    } catch (error) { console.error(error); }
    setIsFetching(false);
  };

  const analyzeNewJobs = async (jobs: Job[]) => {
      setAnalyzingCount(prev => prev + jobs.length);
      for (const job of jobs) {
        try {
            const analysis = await analyzeJob(job);
            await saveAnalysis(job.id, analysis);
        } catch (e) {
            console.error(`Analysis failed for job ${job.id}`, e);
        } finally {
            setAnalyzingCount(prev => Math.max(0, prev - 1));
            await new Promise(resolve => setTimeout(resolve, 1500));
        }
      }
      setAnalyzingCount(0);
  };

  const handleOpenDetail = (job: Job, tab: 'brief' | 'strategy' = 'brief') => {
    setSelectedJob(job);
    setInitialModalTab(tab);
    setModalOpen(true);
  };

  const handleUpdateJob = async (updatedJob: Job) => {
      await addOrUpdateJob(updatedJob);
      if (selectedJob && selectedJob.id === updatedJob.id) {
          setSelectedJob(updatedJob);
      }
  };

  const handleReAnalyzeJob = async (job: Job) => {
      try {
          const analysis = await analyzeJob(job);
          await saveAnalysis(job.id, analysis);
          const updatedJob = { ...job, analysis };
          setSelectedJob(updatedJob);
          setAllJobs(prev => prev.map(j => j.id === job.id ? updatedJob : j));
      } catch (e) {
          console.error("Re-analysis failed", e);
      }
  };

  const handleGenerateKit = async (job: Job) => {
    if (!job.analysis) return;
    const content = await generateApplicationKit(job, job.analysis);
    const updatedAnalysis = { ...job.analysis, strategy: content };
    await saveAnalysis(job.id, updatedAnalysis);
  };

  const toggleJobStatus = (jobId: string, currentStatus: Job['status']) => {
    let newStatus: Job['status'] = 'saved';
    if (currentStatus === 'new') newStatus = 'saved';
    else if (currentStatus === 'saved') newStatus = 'new'; 
    else if (currentStatus === 'archived') newStatus = 'new';
    updateJobStatus(jobId, newStatus!);
  };

  const handleDelete = (jobId: string) => {
    const job = allJobs.find(j => j.id === jobId);
    if (!job) return;
    if (job.status === 'archived') {
        if(confirm("Permanently delete?")) deleteJob(jobId);
    } else {
        updateJobStatus(jobId, 'archived');
    }
  };

  const handleBulkArchive = async () => {
      for (const id of selectedJobIds) {
          await updateJobStatus(id, 'archived');
      }
      setSelectedJobIds(new Set());
      setIsSelectMode(false);
  };

  const handleBulkDelete = async () => {
      if (!confirm(`Delete ${selectedJobIds.size} jobs permanently?`)) return;
      for (const id of selectedJobIds) {
          await deleteJob(id);
      }
      setSelectedJobIds(new Set());
      setIsSelectMode(false);
  };

  const toggleJobSelection = (id: string) => {
      const next = new Set(selectedJobIds);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      setSelectedJobIds(next);
  };

  const handleAddManualJob = async (data: { url?: string, text?: string, title?: string, company?: string }) => {
      try {
          if (currentView !== ViewState.DASHBOARD && currentView !== ViewState.KANBAN) {
              setCurrentView(ViewState.DASHBOARD);
              setActiveTab('saved');
          }
          const placeholder = await addManualJob(data);
          if (!placeholder) return;
          setSelectedJob(placeholder);
          setModalOpen(true);
          setInitialModalTab('brief');
          setAnalyzingCount(prev => prev + 1);
          const enrichedDetails = await enrichJob(data);
          const enrichedJob = { ...placeholder, ...enrichedDetails };
          await addOrUpdateJob(enrichedJob);
          setSelectedJob(prev => (prev && prev.id === placeholder.id ? enrichedJob : prev));
          const analysis = await analyzeJob(enrichedJob);
          await saveAnalysis(enrichedJob.id, analysis);
          const analyzedJob = { ...enrichedJob, analysis };
          setSelectedJob(prev => (prev && prev.id === placeholder.id ? analyzedJob : prev));
      } catch (e) {
          console.error("Error adding manual job", e);
      } finally {
          setAnalyzingCount(prev => Math.max(0, prev - 1));
      }
  };

  const jobsInCurrentTab = useMemo(() => {
    return allJobs.filter(j => {
        const status = j.status || 'new';
        if (activeTab === 'new') return status === 'new';
        if (activeTab === 'saved') return ['saved', 'applied', 'assessment', 'interview', 'offer'].includes(status);
        if (activeTab === 'archived') return status === 'archived';
        return false;
    });
  }, [allJobs, activeTab]);

  const filteredJobs = useMemo(() => {
      return jobsInCurrentTab.filter(j => {
        const locMatch = cityFilter === 'All' ? true : (cityFilter === 'Other' ? !['edinburgh', 'glasgow', 'remote', 'london', 'manchester'].some(s => j.location.toLowerCase().includes(s)) : j.location.toLowerCase().includes(cityFilter.toLowerCase()));
        if (!locMatch) return false;
        if (industryFilter) {
            const ind = j.analysis?.industry || 'Tech';
            if (ind !== industryFilter) return false;
        }
        return true;
      }).sort((a, b) => {
          if (sortBy === 'score') return (b.analysis?.score || 0) - (a.analysis?.score || 0);
          return (b.scoutedAt || 0) - (a.scoutedAt || 0);
      });
  }, [jobsInCurrentTab, cityFilter, industryFilter, sortBy]);

  const filterOptions = ['All', 'Edinburgh', 'Glasgow', 'Remote', 'London', 'Manchester', 'Other'];

  return (
    <div className="min-h-screen bg-[#F5F5F7] dark:bg-black pb-20 font-sans overflow-x-hidden transition-colors duration-300">
        <nav className="fixed top-0 left-0 right-0 h-14 bg-[#1d1d1f]/80 dark:bg-[#1c1c1e]/80 backdrop-blur-xl z-[40] border-b border-white/5 dark:border-white/10 transition-colors duration-300">
            <div className="max-w-[1024px] mx-auto h-full flex items-center justify-between px-6">
                 <div className="flex items-center gap-6">
                     <span className="font-semibold text-base tracking-tight text-white flex items-center gap-2"><Layers size={18} /> Career Studio</span>
                     <div className="hidden sm:flex items-center gap-6 text-[#d2d2d7]">
                         <button onClick={() => setCurrentView(ViewState.DASHBOARD)} className={`transition-colors hover:text-white ${currentView === ViewState.DASHBOARD ? 'text-white' : ''}`}>Discover</button>
                         <button onClick={() => setCurrentView(ViewState.KANBAN)} className={`transition-colors hover:text-white ${currentView === ViewState.KANBAN ? 'text-white' : ''}`}>Pipeline</button>
                         <button onClick={() => setCurrentView(ViewState.CV_EDITOR)} className={`transition-colors hover:text-white ${currentView === ViewState.CV_EDITOR ? 'text-white' : ''}`}>Resume</button>
                     </div>
                 </div>
                 <div className="flex items-center gap-4">
                     {analyzingCount > 0 && (
                        <span className="flex items-center gap-1.5 text-[#0071e3] dark:text-[#0A84FF] font-medium text-[12px]"><Sparkles size={12} className="animate-spin" /> Analyzing...</span>
                     )}
                     <div className="relative" ref={profileMenuRef}>
                        <button onClick={() => setIsProfileMenuOpen(!isProfileMenuOpen)} className="w-8 h-8 rounded-full bg-gray-600 hover:bg-gray-500 text-white flex items-center justify-center text-[10px] font-bold ring-2 ring-white/10 transition-all focus:outline-none">VP</button>
                        {isProfileMenuOpen && (
                            <div className="absolute top-full right-0 mt-2 w-56 bg-white dark:bg-[#1C1C1E] rounded-xl shadow-xl border border-black/5 dark:border-white/10 overflow-hidden animate-in fade-in zoom-in-95 duration-200">
                                <div className="px-4 py-3 border-b border-[#f5f5f7] dark:border-[#38383A]"><p className="text-sm font-semibold text-[#1d1d1f] dark:text-white">Vyom Pathroliya</p><p className="text-xs text-[#86868b] dark:text-[#98989D]">Senior UX Designer</p></div>
                                <div className="p-1">
                                    <button onClick={() => setDarkMode(!darkMode)} className="w-full flex items-center justify-between px-3 py-2 text-sm text-[#1d1d1f] dark:text-[#f5f5f7] hover:bg-[#F5F5F7] dark:hover:bg-[#2C2C2E] rounded-lg transition-colors">
                                        <div className="flex items-center gap-2">{darkMode ? <Moon size={16} /> : <Sun size={16} />}<span>Dark Mode</span></div>
                                        <div className={`w-9 h-5 rounded-full relative transition-colors ${darkMode ? 'bg-[#34C759]' : 'bg-[#E5E5EA]'}`}><div className={`absolute top-0.5 left-0.5 w-4 h-4 rounded-full bg-white shadow-sm transition-transform ${darkMode ? 'translate-x-4' : 'translate-x-0'}`}></div></div>
                                    </button>
                                    <button className="w-full flex items-center gap-2 px-3 py-2 text-sm text-[#FF3B30] hover:bg-[#F5F5F7] dark:hover:bg-[#2C2C2E] rounded-lg transition-colors"><LogOut size={16} /> Sign Out</button>
                                </div>
                            </div>
                        )}
                     </div>
                 </div>
            </div>
        </nav>

        <div key={currentView} className="view-enter">
            <div className={`pt-24 pb-10 ${currentView === ViewState.KANBAN ? 'w-full' : 'max-w-[1024px] mx-auto px-6'}`}>
                {currentView === ViewState.DASHBOARD && (
                    <>
                        <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 mb-12 animate-fade-in-up">
                            <div>
                                <h1 className="text-[48px] md:text-[64px] leading-[1.05] font-semibold text-[#1d1d1f] dark:text-white tracking-tight mb-4 transition-colors">Masterplan your <br/><span className="text-[#86868b] dark:text-[#98989D]">next move.</span></h1>
                                <p className="text-[#1d1d1f] dark:text-[#f5f5f7] text-lg font-medium max-w-lg leading-relaxed transition-colors"><span className="text-[#0071e3] dark:text-[#0A84FF] font-semibold">{allJobs.filter(j => j.status === 'saved').length} opportunities</span> tailored to your experience.</p>
                            </div>
                            <div className="flex gap-3 pb-2 items-center">
                                 <div className="relative" ref={searchSettingsRef}>
                                    <button onClick={() => setIsSearchSettingsOpen(!isSearchSettingsOpen)} className="h-10 w-10 flex items-center justify-center rounded-full bg-[#E8E8ED] hover:bg-[#d2d2d7] dark:bg-[#38383A] dark:hover:bg-[#48484A] text-[#1d1d1f] dark:text-white transition-all hover:scale-105 active:scale-95" title="Search Settings"><Settings size={18} /></button>
                                    {isSearchSettingsOpen && (
                                        <div className="absolute bottom-full right-0 mb-3 w-72 bg-white dark:bg-[#1C1C1E] rounded-2xl shadow-2xl border border-black/5 dark:border-white/10 p-6 z-50 animate-in fade-in slide-in-from-bottom-2 duration-200">
                                            <div className="flex items-center justify-between mb-4"><h4 className="text-sm font-bold uppercase tracking-wider text-[#86868b]">Search Preferences</h4><button onClick={() => setIsSearchSettingsOpen(false)}><X size={14} /></button></div>
                                            <div className="space-y-4">
                                                <div><label className="block text-[10px] font-bold text-[#86868b] uppercase mb-1">Target Role</label><input value={searchRole} onChange={e => setSearchRole(e.target.value)} className="w-full px-3 py-2 bg-[#f5f5f7] dark:bg-[#2C2C2E] rounded-lg text-sm border-none outline-none focus:ring-1 focus:ring-[#0071e3]" /></div>
                                                <div><label className="block text-[10px] font-bold text-[#86868b] uppercase mb-1">Location</label><input value={searchLocation} onChange={e => setSearchLocation(e.target.value)} className="w-full px-3 py-2 bg-[#f5f5f7] dark:bg-[#2C2C2E] rounded-lg text-sm border-none outline-none focus:ring-1 focus:ring-[#0071e3]" /></div>
                                            </div>
                                        </div>
                                    )}
                                 </div>
                                 <button onClick={fetchJobs} disabled={isFetching} className={`h-10 px-6 rounded-full bg-[#0071e3] hover:bg-[#0077ED] dark:bg-[#0A84FF] dark:hover:bg-[#409CFF] text-white text-sm font-medium transition-all flex items-center gap-2 ${isFetching ? 'opacity-70 cursor-not-allowed' : 'hover:scale-105 active:scale-95 shadow-lg shadow-blue-500/20'}`}><Search size={16} /> {isFetching ? 'Scouting...' : 'Scout Jobs'}</button>
                                 <button onClick={() => setIsAddLinkOpen(true)} className="h-10 w-10 flex items-center justify-center rounded-full bg-[#E8E8ED] hover:bg-[#d2d2d7] dark:bg-[#38383A] dark:hover:bg-[#48484A] text-[#1d1d1f] dark:text-white transition-all hover:scale-105 active:scale-95"><Plus size={18} /></button>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                            <div className="lg:col-span-3 space-y-8 sticky top-[80px] self-start z-10 pr-2">
                                <div><div className="flex items-center justify-between mb-3 px-2"><h3 className="text-[11px] font-bold text-[#86868b] dark:text-[#98989D] uppercase tracking-wider">Locations</h3>{cityFilter !== 'All' && <button onClick={() => setCityFilter('All')} className="text-[10px] font-bold text-[#0071e3] dark:text-[#0A84FF] hover:underline">Reset</button>}</div>
                                <div className="space-y-1">{filterOptions.map(city => {
                                    const count = city === 'All' ? jobsInCurrentTab.length : jobsInCurrentTab.filter(j => city === 'Other' ? !['edinburgh', 'glasgow', 'remote', 'london', 'manchester'].some(s => j.location.toLowerCase().includes(s)) : j.location.toLowerCase().includes(city.toLowerCase())).length;
                                    if (count === 0 && city !== 'All') return null;
                                    return (<button key={city} onClick={() => setCityFilter(city)} className={`w-full flex items-center justify-between px-3 py-2 rounded-lg text-[13px] transition-all ${cityFilter === city ? 'bg-[#E8E8ED] dark:bg-[#1C1C1E] font-semibold text-[#1d1d1f] dark:text-white' : 'text-[#636366] dark:text-[#98989D] hover:bg-[#E8E8ED]/50 dark:hover:bg-[#1C1C1E]/50'}`}><span>{city}</span><span className={`text-[11px] ${cityFilter === city ? 'text-[#1d1d1f] opacity-100' : 'text-[#86868b] opacity-70'}`}>{count}</span></button>);
                                })}</div></div>
                                <div className="w-full h-px bg-[#d2d2d7]/50 dark:bg-[#38383A]"></div>
                                <div className="px-2"><StatsPanel jobs={jobsInCurrentTab} selectedIndustry={industryFilter} onSelectIndustry={setIndustryFilter}/></div>
                            </div>
                            <div className="lg:col-span-9">
                                <div className="flex items-center justify-between mb-6">
                                    <div className="flex items-center gap-4">
                                        <div className="bg-[#E8E8ED] dark:bg-[#1C1C1E] p-1 rounded-lg inline-flex items-center h-10 border border-transparent dark:border-white/10">{['new', 'saved', 'archived'].map((tab) => (<button key={tab} onClick={() => { setActiveTab(tab as any); setIsSelectMode(false); setSelectedJobIds(new Set()); }} className={`px-6 h-full rounded-md text-[13px] font-semibold capitalize transition-all flex items-center justify-center ${activeTab === tab ? 'bg-white dark:bg-[#3A3A3C] text-black dark:text-white shadow-sm' : 'text-[#636366] dark:text-[#8E8E93] hover:text-black dark:hover:text-white'}`}>{tab}</button>))}</div>
                                        {jobsInCurrentTab.length > 0 && (
                                            <button onClick={() => { setIsSelectMode(!isSelectMode); setSelectedJobIds(new Set()); }} className={`text-[12px] font-bold px-3 py-1 rounded-full transition-colors ${isSelectMode ? 'bg-[#0071e3] text-white' : 'text-[#86868b] hover:text-[#1d1d1f]'}`}>{isSelectMode ? 'Cancel Selection' : 'Select'}</button>
                                        )}
                                    </div>
                                    <div className="flex items-center gap-2"><span className="text-[11px] text-[#86868b] font-medium mr-1">Sort by:</span><button onClick={() => setSortBy(sortBy === 'date' ? 'score' : 'date')} className="text-[11px] font-bold text-[#0071e3] hover:underline flex items-center gap-1">{sortBy === 'date' ? 'Date' : 'Match Score'} <ArrowDownUp size={12}/></button></div>
                                </div>
                                {isSelectMode && selectedJobIds.size > 0 && (
                                    <div className="mb-6 p-4 bg-white dark:bg-[#1C1C1E] rounded-2xl border border-[#0071e3] flex items-center justify-between animate-in slide-in-from-top-4 duration-300">
                                        <span className="text-sm font-semibold">{selectedJobIds.size} jobs selected</span>
                                        <div className="flex items-center gap-3">
                                            <button onClick={handleBulkArchive} className="flex items-center gap-2 px-4 py-2 bg-[#f5f5f7] dark:bg-[#2C2C2E] rounded-full text-xs font-bold hover:bg-[#e8e8ed] transition-colors"><Archive size={14}/> Archive</button>
                                            <button onClick={handleBulkDelete} className="flex items-center gap-2 px-4 py-2 bg-[#FF3B30]/10 text-[#FF3B30] rounded-full text-xs font-bold hover:bg-[#FF3B30]/20 transition-colors"><Trash2 size={14}/> Delete Permanent</button>
                                        </div>
                                    </div>
                                )}
                                <div className="space-y-6">{filteredJobs.length === 0 ? (<div className="py-20 text-center text-[#86868b]"><p className="text-lg font-medium">No opportunities found.</p></div>) : (filteredJobs.map(job => (<JobCard key={job.id} job={job} onOpenDetail={handleOpenDetail} onToggleStatus={toggleJobStatus} onDelete={handleDelete} isSelectMode={isSelectMode} isSelected={selectedJobIds.has(job.id)} onSelect={toggleJobSelection} />)))}</div>
                            </div>
                        </div>
                    </>
                )}
                {currentView === ViewState.KANBAN && (<div className="h-[calc(100vh-100px)] animate-fade-in-up flex flex-col w-full"><div className="flex items-center justify-between mb-8 w-full max-w-[1024px] mx-auto px-6"><h1 className="text-[40px] font-semibold text-[#1d1d1f] dark:text-white tracking-tight">Pipeline</h1><button onClick={() => setIsAddLinkOpen(true)} className="h-10 px-5 rounded-full bg-[#1d1d1f] dark:bg-white hover:bg-black dark:hover:bg-[#E5E5EA] text-white dark:text-black text-sm font-medium transition-all flex items-center gap-2 shadow-lg"><Plus size={16} /> Add Job</button></div><div className="flex-1 min-h-0 w-full"><KanbanBoard jobs={allJobs} onGenerateKit={(job) => handleOpenDetail(job, 'strategy')} onToggleStatus={updateJobStatus} onDelete={handleDelete} onOpenDetail={handleOpenDetail} onOpenAddModal={() => setIsAddLinkOpen(true)}/></div></div>)}
                {currentView === ViewState.CV_EDITOR && (<div className="h-[calc(100vh-60px)] animate-fade-in-up flex flex-col items-center"><div className="w-full max-w-[1024px] mb-6 px-6"><h1 className="text-[40px] font-semibold text-[#1d1d1f] dark:text-white tracking-tight">Resume</h1></div><div className="flex-1 w-full relative"><CVEditor /></div></div>)}
            </div>
        </div>

      <JobDetailModal isOpen={modalOpen} onClose={() => setModalOpen(false)} job={selectedJob} onGenerateKit={handleGenerateKit} initialTab={initialModalTab} onUpdateJob={handleUpdateJob} onReAnalyze={handleReAnalyzeJob}/>
      <AddLinkModal isOpen={isAddLinkOpen} onClose={() => setIsAddLinkOpen(false)} onAdd={handleAddManualJob} existingJobs={allJobs}/>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Job, ViewState } from './types';
import { searchAndParseJobs, analyzeJob, generateApplicationKit, enrichJob } from './services/geminiService';
import { initFirebase, subscribeToJobs, addOrUpdateJob, updateJobStatus, deleteJob, saveAnalysis, addManualJob } from './services/firebase';
import { DEFAULT_FIREBASE_CONFIG } from './constants';
import JobCard from './components/JobCard';
import StatsPanel from './components/StatsPanel';
import KanbanBoard from './components/KanbanBoard';
import CVEditor from './components/CVEditor';
import JobDetailModal from './components/JobDetailModal';
import AddLinkModal from './components/AddLinkModal';
import { LayoutGrid, Kanban, FileText, Plus, Search, Command, Sparkles, ArrowDownUp, Layers, Moon, Sun, User, LogOut, ChevronDown, Settings, X, Archive, Trash2 } from 'lucide-react';

const App: React.FC = () => {
  // Navigation & Data
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.DASHBOARD);
  const [activeTab, setActiveTab] = useState<'new' | 'saved' | 'archived'>('new');
  const [allJobs, setAllJobs] = useState<Job[]>([]);
  const [targetJobId, setTargetJobId] = useState<string | null>(null);

  // Search Configuration
  const [searchRole, setSearchRole] = useState('Senior UX Designer');
  const [searchLocation, setSearchLocation] = useState('United Kingdom');
  const [isSearchSettingsOpen, setIsSearchSettingsOpen] = useState(false);
  const searchSettingsRef = useRef<HTMLDivElement>(null);

  // Multi-Select
  const [isSelectMode, setIsSelectMode] = useState(false);
  const [selectedJobIds, setSelectedJobIds] = useState<Set<string>>(new Set());

  // Theme State
  const [darkMode, setDarkMode] = useState(() => {
    if (typeof window !== 'undefined') {
        return localStorage.getItem('theme') === 'dark' || 
               (!localStorage.getItem('theme') && window.matchMedia('(prefers-color-scheme: dark)').matches);
    }
    return false;
  });

  // Profile Menu State
  const [isProfileMenuOpen, setIsProfileMenuOpen] = useState(false);
  const profileMenuRef = useRef<HTMLDivElement>(null);

  // Auto-Init Firebase
  const [isDbConnected] = useState(() => initFirebase(DEFAULT_FIREBASE_CONFIG));

  // Filter & Sort
  const [cityFilter, setCityFilter] = useState<string>('All');
  const [industryFilter, setIndustryFilter] = useState<string | null>(null);
  const [sortBy, setSortBy] = useState<'date' | 'score'>('date');

  // Status
  const [isFetching, setIsFetching] = useState(false);
  const [analyzingCount, setAnalyzingCount] = useState(0);

  // Modal
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedJob, setSelectedJob] = useState<Job | null>(null);
  const [initialModalTab, setInitialModalTab] = useState<'brief' | 'strategy'>('brief');
  const [isAddLinkOpen, setIsAddLinkOpen] = useState(false);

  // Theme Effect
  useEffect(() => {
      if (darkMode) {
          document.documentElement.classList.add('dark');
          localStorage.setItem('theme', 'dark');
      } else {
          document.documentElement.classList.remove('dark');
          localStorage.setItem('theme', 'light');
      }
  }, [darkMode]);

  // Click Outside Profile/Search Menu
  useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
          if (profileMenuRef.current && !profileMenuRef.current.contains(event.target as Node)) {
              setIsProfileMenuOpen(false);
          }
          if (searchSettingsRef.current && !searchSettingsRef.current.contains(event.target as Node)) {
              setIsSearchSettingsOpen(false);
          }
      };
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (isDbConnected) {
      const unsubscribe = subscribeToJobs((jobs) => {
        setAllJobs(jobs);
      });
      return () => unsubscribe();
    }
  }, [isDbConnected]);

  const fetchJobs = async () => {
    if (!isDbConnected) return;
    setIsFetching(true);
    try {
      const foundJobs = await searchAndParseJobs(searchRole, searchLocation);
      const jobsToAnalyze: Job[] = [];
      for (const job of foundJobs) {
        const docId = `${job.title}_${job.company}`.toLowerCase().replace(/[^a-z0-9]/g, '_').substring(0, 100);
        const existing = allJobs.find(j => j.id === docId);
        const jobWithTimestamp = { ...job, scoutedAt: Date.now() };
        await addOrUpdateJob(jobWithTimestamp);
        if (!existing || !existing.analysis) {
           jobsToAnalyze.push({ ...jobWithTimestamp, id: docId });
        }
      }
      if (jobsToAnalyze.length > 0) analyzeNewJobs(jobsToAnalyze);
    } catch (error) { console.error(error); }
    setIsFetching(false);
  };

  const analyzeNewJobs = async (jobs: Job[]) => {
      setAnalyzingCount(prev => prev + jobs.length);
      for (const job of jobs) {
        try {
            const analysis = await analyzeJob(job);
            await saveAnalysis(job.id, analysis);
        } catch (e) {
            console.error(`Analysis failed for job ${job.id}`, e);
        } finally {
            setAnalyzingCount(prev => Math.max(0, prev - 1));
            await new Promise(resolve => setTimeout(resolve, 1500));
        }
      }
      setAnalyzingCount(0);
  };

  const handleOpenDetail = (job: Job, tab: 'brief' | 'strategy' = 'brief') => {
    setSelectedJob(job);
    setInitialModalTab(tab);
    setModalOpen(true);
  };

  const handleUpdateJob = async (updatedJob: Job) => {
      await addOrUpdateJob(updatedJob);
      if (selectedJob && selectedJob.id === updatedJob.id) {
          setSelectedJob(updatedJob);
      }
  };

  const handleReAnalyzeJob = async (job: Job) => {
      try {
          const analysis = await analyzeJob(job);
          await saveAnalysis(job.id, analysis);
          const updatedJob = { ...job, analysis };
          setSelectedJob(updatedJob);
          setAllJobs(prev => prev.map(j => j.id === job.id ? updatedJob : j));
      } catch (e) {
          console.error("Re-analysis failed", e);
      }
  };

  const handleGenerateKit = async (job: Job) => {
    if (!job.analysis) return;
    const content = await generateApplicationKit(job, job.analysis);
    const updatedAnalysis = { ...job.analysis, strategy: content };
    await saveAnalysis(job.id, updatedAnalysis);
  };

  const toggleJobStatus = (jobId: string, currentStatus: Job['status']) => {
    let newStatus: Job['status'] = 'saved';
    if (currentStatus === 'new') newStatus = 'saved';
    else if (currentStatus === 'saved') newStatus = 'new'; 
    else if (currentStatus === 'archived') newStatus = 'new';
    updateJobStatus(jobId, newStatus!);
  };

  const handleDelete = (jobId: string) => {
    const job = allJobs.find(j => j.id === jobId);
    if (!job) return;
    if (job.status === 'archived') {
        if(confirm("Permanently delete?")) deleteJob(jobId);
    } else {
        updateJobStatus(jobId, 'archived');
    }
  };

  const handleBulkArchive = async () => {
      for (const id of selectedJobIds) {
          await updateJobStatus(id, 'archived');
      }
      setSelectedJobIds(new Set());
      setIsSelectMode(false);
  };

  const handleBulkDelete = async () => {
      if (!confirm(`Delete ${selectedJobIds.size} jobs permanently?`)) return;
      for (const id of selectedJobIds) {
          await deleteJob(id);
      }
      setSelectedJobIds(new Set());
      setIsSelectMode(false);
  };

  const toggleJobSelection = (id: string) => {
      const next = new Set(selectedJobIds);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      setSelectedJobIds(next);
  };

  const handleAddManualJob = async (data: { url?: string, text?: string, title?: string, company?: string }) => {
      try {
          if (currentView !== ViewState.DASHBOARD && currentView !== ViewState.KANBAN) {
              setCurrentView(ViewState.DASHBOARD);
              setActiveTab('saved');
          }
          const placeholder = await addManualJob(data);
          if (!placeholder) return;
          setSelectedJob(placeholder);
          setModalOpen(true);
          setInitialModalTab('brief');
          setAnalyzingCount(prev => prev + 1);
          const enrichedDetails = await enrichJob(data);
          const enrichedJob = { ...placeholder, ...enrichedDetails };
          await addOrUpdateJob(enrichedJob);
          setSelectedJob(prev => (prev && prev.id === placeholder.id ? enrichedJob : prev));
          const analysis = await analyzeJob(enrichedJob);
          await saveAnalysis(enrichedJob.id, analysis);
          const analyzedJob = { ...enrichedJob, analysis };
          setSelectedJob(prev => (prev && prev.id === placeholder.id ? analyzedJob : prev));
      } catch (e) {
          console.error("Error adding manual job", e);
      } finally {
          setAnalyzingCount(prev => Math.max(0, prev - 1));
      }
  };

  const handleTailorResume = (jobId: string) => {
    setTargetJobId(jobId);
    setModalOpen(false);
    setCurrentView(ViewState.CV_EDITOR);
  };

  const jobsInCurrentTab = useMemo(() => {
    return allJobs.filter(j => {
        const status = j.status || 'new';
        if (activeTab === 'new') return status === 'new';
        if (activeTab === 'saved') return ['saved', 'applied', 'assessment', 'interview', 'offer'].includes(status);
        if (activeTab === 'archived') return status === 'archived';
        return false;
    });
  }, [allJobs, activeTab]);

  const filteredJobs = useMemo(() => {
      return jobsInCurrentTab.filter(j => {
        const locMatch = cityFilter === 'All' ? true : (cityFilter === 'Other' ? !['edinburgh', 'glasgow', 'remote', 'london', 'manchester'].some(s => j.location.toLowerCase().includes(s)) : j.location.toLowerCase().includes(cityFilter.toLowerCase()));
        if (!locMatch) return false;
        if (industryFilter) {
            const ind = j.analysis?.industry || 'Tech';
            if (ind !== industryFilter) return false;
        }
        return true;
      }).sort((a, b) => {
          if (sortBy === 'score') return (b.analysis?.score || 0) - (a.analysis?.score || 0);
          return (b.scoutedAt || 0) - (a.scoutedAt || 0);
      });
  }, [jobsInCurrentTab, cityFilter, industryFilter, sortBy]);

  const filterOptions = ['All', 'Edinburgh', 'Glasgow', 'Remote', 'London', 'Manchester', 'Other'];

  const targetJobForEditor = useMemo(() => {
      if (!targetJobId) return null;
      return allJobs.find(j => j.id === targetJobId) || null;
  }, [targetJobId, allJobs]);

  return (
    <div className="min-h-screen bg-[#F5F5F7] dark:bg-black pb-20 font-sans overflow-x-hidden transition-colors duration-300">
        <nav className="fixed top-0 left-0 right-0 h-14 bg-[#1d1d1f]/80 dark:bg-[#1c1c1e]/80 backdrop-blur-xl z-[40] border-b border-white/5 dark:border-white/10 transition-colors duration-300">
            <div className="max-w-[1024px] mx-auto h-full flex items-center justify-between px-6">
                 <div className="flex items-center gap-6">
                     <span className="font-semibold text-base tracking-tight text-white flex items-center gap-2"><Layers size={18} /> Career Studio</span>
                     <div className="hidden sm:flex items-center gap-6 text-[#d2d2d7]">
                         <button onClick={() => { setCurrentView(ViewState.DASHBOARD); setTargetJobId(null); }} className={`transition-colors hover:text-white ${currentView === ViewState.DASHBOARD ? 'text-white' : ''}`}>Discover</button>
                         <button onClick={() => { setCurrentView(ViewState.KANBAN); setTargetJobId(null); }} className={`transition-colors hover:text-white ${currentView === ViewState.KANBAN ? 'text-white' : ''}`}>Pipeline</button>
                         <button onClick={() => setCurrentView(ViewState.CV_EDITOR)} className={`transition-colors hover:text-white ${currentView === ViewState.CV_EDITOR ? 'text-white' : ''}`}>Resume</button>
                     </div>
                 </div>
                 <div className="flex items-center gap-4">
                     {analyzingCount > 0 && (
                        <span className="flex items-center gap-1.5 text-[#0071e3] dark:text-[#0A84FF] font-medium text-[12px]"><Sparkles size={12} className="animate-spin" /> Analyzing...</span>
                     )}
                     <div className="relative" ref={profileMenuRef}>
                        <button onClick={() => setIsProfileMenuOpen(!isProfileMenuOpen)} className="w-8 h-8 rounded-full bg-gray-600 hover:bg-gray-500 text-white flex items-center justify-center text-[10px] font-bold ring-2 ring-white/10 transition-all focus:outline-none">VP</button>
                        {isProfileMenuOpen && (
                            <div className="absolute top-full right-0 mt-2 w-56 bg-white dark:bg-[#1C1C1E] rounded-xl shadow-xl border border-black/5 dark:border-white/10 overflow-hidden animate-in fade-in zoom-in-95 duration-200">
                                <div className="px-4 py-3 border-b border-[#f5f5f7] dark:border-[#38383A]"><p className="text-sm font-semibold text-[#1d1d1f] dark:text-white">Vyom Pathroliya</p><p className="text-xs text-[#86868b] dark:text-[#98989D]">Senior UX Designer</p></div>
                                <div className="p-1">
                                    <button onClick={() => setDarkMode(!darkMode)} className="w-full flex items-center justify-between px-3 py-2 text-sm text-[#1d1d1f] dark:text-[#f5f5f7] hover:bg-[#F5F5F7] dark:hover:bg-[#2C2C2E] rounded-lg transition-colors">
                                        <div className="flex items-center gap-2">{darkMode ? <Moon size={16} /> : <Sun size={16} />}<span>Dark Mode</span></div>
                                        <div className={`w-9 h-5 rounded-full relative transition-colors ${darkMode ? 'bg-[#34C759]' : 'bg-[#E5E5EA]'}`}><div className={`absolute top-0.5 left-0.5 w-4 h-4 rounded-full bg-white shadow-sm transition-transform ${darkMode ? 'translate-x-4' : 'translate-x-0'}`}></div></div>
                                    </button>
                                    <button className="w-full flex items-center gap-2 px-3 py-2 text-sm text-[#FF3B30] hover:bg-[#F5F5F7] dark:hover:bg-[#2C2C2E] rounded-lg transition-colors"><LogOut size={16} /> Sign Out</button>
                                </div>
                            </div>
                        )}
                     </div>
                 </div>
            </div>
        </nav>

        <div key={currentView} className="view-enter">
            <div className={`pt-24 pb-10 ${currentView === ViewState.KANBAN ? 'w-full' : 'max-w-[1024px] mx-auto px-6'}`}>
                {currentView === ViewState.DASHBOARD && (
                    <>
                        <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 mb-12 animate-fade-in-up">
                            <div>
                                <h1 className="text-[48px] md:text-[64px] leading-[1.05] font-semibold text-[#1d1d1f] dark:text-white tracking-tight mb-4 transition-colors">Masterplan your <br/><span className="text-[#86868b] dark:text-[#98989D]">next move.</span></h1>
                                <p className="text-[#1d1d1f] dark:text-[#f5f5f7] text-lg font-medium max-w-lg leading-relaxed transition-colors"><span className="text-[#0071e3] dark:text-[#0A84FF] font-semibold">{allJobs.filter(j => j.status === 'saved').length} opportunities</span> tailored to your experience.</p>
                            </div>
                            <div className="flex gap-3 pb-2 items-center">
                                 <div className="relative" ref={searchSettingsRef}>
                                    <button onClick={() => setIsSearchSettingsOpen(!isSearchSettingsOpen)} className="h-10 w-10 flex items-center justify-center rounded-full bg-[#E8E8ED] hover:bg-[#d2d2d7] dark:bg-[#38383A] dark:hover:bg-[#48484A] text-[#1d1d1f] dark:text-white transition-all hover:scale-105 active:scale-95" title="Search Settings"><Settings size={18} /></button>
                                    {isSearchSettingsOpen && (
                                        <div className="absolute bottom-full right-0 mb-3 w-72 bg-white dark:bg-[#1C1C1E] rounded-2xl shadow-2xl border border-black/5 dark:border-white/10 p-6 z-50 animate-in fade-in slide-in-from-bottom-2 duration-200">
                                            <div className="flex items-center justify-between mb-4"><h4 className="text-sm font-bold uppercase tracking-wider text-[#86868b]">Search Preferences</h4><button onClick={() => setIsSearchSettingsOpen(false)}><X size={14} /></button></div>
                                            <div className="space-y-4">
                                                <div><label className="block text-[10px] font-bold text-[#86868b] uppercase mb-1">Target Role</label><input value={searchRole} onChange={e => setSearchRole(e.target.value)} className="w-full px-3 py-2 bg-[#f5f5f7] dark:bg-[#2C2C2E] rounded-lg text-sm border-none outline-none focus:ring-1 focus:ring-[#0071e3]" /></div>
                                                <div><label className="block text-[10px] font-bold text-[#86868b] uppercase mb-1">Location</label><input value={searchLocation} onChange={e => setSearchLocation(e.target.value)} className="w-full px-3 py-2 bg-[#f5f5f7] dark:bg-[#2C2C2E] rounded-lg text-sm border-none outline-none focus:ring-1 focus:ring-[#0071e3]" /></div>
                                            </div>
                                        </div>
                                    )}
                                 </div>
                                 <button onClick={fetchJobs} disabled={isFetching} className={`h-10 px-6 rounded-full bg-[#0071e3] hover:bg-[#0077ED] dark:bg-[#0A84FF] dark:hover:bg-[#409CFF] text-white text-sm font-medium transition-all flex items-center gap-2 ${isFetching ? 'opacity-70 cursor-not-allowed' : 'hover:scale-105 active:scale-95 shadow-lg shadow-blue-500/20'}`}><Search size={16} /> {isFetching ? 'Scouting...' : 'Scout Jobs'}</button>
                                 <button onClick={() => setIsAddLinkOpen(true)} className="h-10 w-10 flex items-center justify-center rounded-full bg-[#E8E8ED] hover:bg-[#d2d2d7] dark:bg-[#38383A] dark:hover:bg-[#48484A] text-[#1d1d1f] dark:text-white transition-all hover:scale-105 active:scale-95"><Plus size={18} /></button>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                            <div className="lg:col-span-3 space-y-8 sticky top-[80px] self-start z-10 pr-2">
                                <div><div className="flex items-center justify-between mb-3 px-2"><h3 className="text-[11px] font-bold text-[#86868b] dark:text-[#98989D] uppercase tracking-wider">Locations</h3>{cityFilter !== 'All' && <button onClick={() => setCityFilter('All')} className="text-[10px] font-bold text-[#0071e3] dark:text-[#0A84FF] hover:underline">Reset</button>}</div>
                                <div className="space-y-1">{filterOptions.map(city => {
                                    const count = city === 'All' ? jobsInCurrentTab.length : jobsInCurrentTab.filter(j => city === 'Other' ? !['edinburgh', 'glasgow', 'remote', 'london', 'manchester'].some(s => j.location.toLowerCase().includes(s)) : j.location.toLowerCase().includes(city.toLowerCase())).length;
                                    if (count === 0 && city !== 'All') return null;
                                    return (<button key={city} onClick={() => setCityFilter(city)} className={`w-full flex items-center justify-between px-3 py-2 rounded-lg text-[13px] transition-all ${cityFilter === city ? 'bg-[#E8E8ED] dark:bg-[#1C1C1E] font-semibold text-[#1d1d1f] dark:text-white' : 'text-[#636366] dark:text-[#98989D] hover:bg-[#E8E8ED]/50 dark:hover:bg-[#1C1C1E]/50'}`}><span>{city}</span><span className={`text-[11px] ${cityFilter === city ? 'text-[#1d1d1f] opacity-100' : 'text-[#86868b] opacity-70'}`}>{count}</span></button>);
                                })}</div></div>
                                <div className="w-full h-px bg-[#d2d2d7]/50 dark:bg-[#38383A]"></div>
                                <div className="px-2"><StatsPanel jobs={jobsInCurrentTab} selectedIndustry={industryFilter} onSelectIndustry={setIndustryFilter}/></div>
                            </div>
                            <div className="lg:col-span-9">
                                <div className="flex items-center justify-between mb-6">
                                    <div className="flex items-center gap-4">
                                        <div className="bg-[#E8E8ED] dark:bg-[#1C1C1E] p-1 rounded-lg inline-flex items-center h-10 border border-transparent dark:border-white/10">{['new', 'saved', 'archived'].map((tab) => (<button key={tab} onClick={() => { setActiveTab(tab as any); setIsSelectMode(false); setSelectedJobIds(new Set()); }} className={`px-6 h-full rounded-md text-[13px] font-semibold capitalize transition-all flex items-center justify-center ${activeTab === tab ? 'bg-white dark:bg-[#3A3A3C] text-black dark:text-white shadow-sm' : 'text-[#636366] dark:text-[#8E8E93] hover:text-black dark:hover:text-white'}`}>{tab}</button>))}</div>
                                        {jobsInCurrentTab.length > 0 && (
                                            <button onClick={() => { setIsSelectMode(!isSelectMode); setSelectedJobIds(new Set()); }} className={`text-[12px] font-bold px-3 py-1 rounded-full transition-colors ${isSelectMode ? 'bg-[#0071e3] text-white' : 'text-[#86868b] hover:text-[#1d1d1f]'}`}>{isSelectMode ? 'Cancel Selection' : 'Select'}</button>
                                        )}
                                    </div>
                                    <div className="flex items-center gap-2"><span className="text-[11px] text-[#86868b] font-medium mr-1">Sort by:</span><button onClick={() => setSortBy(sortBy === 'date' ? 'score' : 'date')} className="text-[11px] font-bold text-[#0071e3] hover:underline flex items-center gap-1">{sortBy === 'date' ? 'Date' : 'Match Score'} <ArrowDownUp size={12}/></button></div>
                                </div>
                                {isSelectMode && selectedJobIds.size > 0 && (
                                    <div className="mb-6 p-4 bg-white dark:bg-[#1C1C1E] rounded-2xl border border-[#0071e3] flex items-center justify-between animate-in slide-in-from-top-4 duration-300">
                                        <span className="text-sm font-semibold">{selectedJobIds.size} jobs selected</span>
                                        <div className="flex items-center gap-3">
                                            <button onClick={handleBulkArchive} className="flex items-center gap-2 px-4 py-2 bg-[#f5f5f7] dark:bg-[#2C2C2E] rounded-full text-xs font-bold hover:bg-[#e8e8ed] transition-colors"><Archive size={14}/> Archive</button>
                                            <button onClick={handleBulkDelete} className="flex items-center gap-2 px-4 py-2 bg-[#FF3B30]/10 text-[#FF3B30] rounded-full text-xs font-bold hover:bg-[#FF3B30]/20 transition-colors"><Trash2 size={14}/> Delete Permanent</button>
                                        </div>
                                    </div>
                                )}
                                <div className="space-y-6">{filteredJobs.length === 0 ? (<div className="py-20 text-center text-[#86868b]"><p className="text-lg font-medium">No opportunities found.</p></div>) : (filteredJobs.map(job => (<JobCard key={job.id} job={job} onOpenDetail={handleOpenDetail} onToggleStatus={toggleJobStatus} onDelete={handleDelete} isSelectMode={isSelectMode} isSelected={selectedJobIds.has(job.id)} onSelect={toggleJobSelection} />)))}</div>
                            </div>
                        </div>
                    </>
                )}
                {currentView === ViewState.KANBAN && (<div className="h-[calc(100vh-100px)] animate-fade-in-up flex flex-col w-full"><div className="flex items-center justify-between mb-8 w-full max-w-[1024px] mx-auto px-6"><h1 className="text-[40px] font-semibold text-[#1d1d1f] dark:text-white tracking-tight">Pipeline</h1><button onClick={() => setIsAddLinkOpen(true)} className="h-10 px-5 rounded-full bg-[#1d1d1f] dark:bg-white hover:bg-black dark:hover:bg-[#E5E5EA] text-white dark:text-black text-sm font-medium transition-all flex items-center gap-2 shadow-lg"><Plus size={16} /> Add Job</button></div><div className="flex-1 min-h-0 w-full"><KanbanBoard jobs={allJobs} onGenerateKit={(job) => handleOpenDetail(job, 'strategy')} onToggleStatus={updateJobStatus} onDelete={handleDelete} onOpenDetail={handleOpenDetail} onOpenAddModal={() => setIsAddLinkOpen(true)}/></div></div>)}
                {currentView === ViewState.CV_EDITOR && (<div className="h-[calc(100vh-60px)] animate-fade-in-up flex flex-col items-center"><div className="w-full max-w-[1024px] mb-6 px-6"><h1 className="text-[40px] font-semibold text-[#1d1d1f] dark:text-white tracking-tight">{targetJobForEditor ? 'War Room' : 'Resume'}</h1></div><div className="flex-1 w-full relative"><CVEditor targetJob={targetJobForEditor} /></div></div>)}
            </div>
        </div>

      <JobDetailModal isOpen={modalOpen} onClose={() => setModalOpen(false)} job={selectedJob} onGenerateKit={handleGenerateKit} initialTab={initialModalTab} onUpdateJob={handleUpdateJob} onReAnalyze={handleReAnalyzeJob} onTailorResume={handleTailorResume}/>
      <AddLinkModal isOpen={isAddLinkOpen} onClose={() => setIsAddLinkOpen(false)} onAdd={handleAddManualJob} existingJobs={allJobs}/>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Bold, Italic, Underline, AlignLeft, AlignCenter, AlignRight, RotateCcw, RotateCw, List, Save, BookOpen, Trash, Sparkles, CheckCircle2, ChevronRight, Layout } from 'lucide-react';
import { saveCV, getCV } from '../services/firebase';
import { Job } from '../types';

interface CVEditorProps {
    targetJob?: Job | null;
}

const CVEditor: React.FC<CVEditorProps> = ({ targetJob }) => {
  const editorRef = useRef<HTMLDivElement>(null);
  const [lastSaved, setLastSaved] = useState<string>('');
  const [showDoc, setShowDoc] = useState(false);
  const [foundKeywords, setFoundKeywords] = useState<Set<string>>(new Set());

  // Keyword detection logic
  const keywords = useMemo(() => {
    return targetJob?.analysis?.matchedKeywords || [];
  }, [targetJob]);

  const scanKeywords = useCallback(() => {
    if (!editorRef.current || keywords.length === 0) return;
    const text = editorRef.current.innerText.toLowerCase();
    const found = new Set<string>();
    keywords.forEach(kw => {
        if (text.includes(kw.toLowerCase())) {
            found.add(kw);
        }
    });
    setFoundKeywords(found);
  }, [keywords]);

  useEffect(() => {
    const loadContent = async () => {
        const content = await getCV();
        if (content && editorRef.current) {
            editorRef.current.innerHTML = content;
            setLastSaved('Loaded from Cloud');
            scanKeywords();
        } else if (editorRef.current && !editorRef.current.innerHTML.trim()) {
            editorRef.current.innerHTML = `
            <h1 style="font-size: 2em; font-weight: bold; margin-bottom: 0.5em; color: #1d1d1f;">Senior UX Designer</h1>
            <p><strong>Summary</strong></p>
            <p>Strategic and human-centered Senior UX Designer with 7+ years of experience transforming complex financial and insurance problems into intuitive digital solutions.</p>
            <br>
            <p><strong>Experience</strong></p>
            <p><strong>Lead Product Designer | Intact Insurance</strong></p>
            <ul>
                <li>Spearheaded the redesign of the claims portal, reducing processing time by 30%.</li>
                <li>Mentored junior designers and established the 'Trove' design system.</li>
            </ul>
            `;
            scanKeywords();
        }
    };
    loadContent();
  }, [scanKeywords]);

  const saveContent = useCallback(async () => {
    if (editorRef.current) {
        const html = editorRef.current.innerHTML;
        await saveCV(html);
        const now = new Date();
        setLastSaved(now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
        scanKeywords();
    }
  }, [scanKeywords]);

  useEffect(() => {
      const handleInput = () => {
          const timeoutId = setTimeout(() => {
              saveContent();
          }, 1000);
          return () => clearTimeout(timeoutId);
      };
      const el = editorRef.current;
      const rawInputHandler = () => handleInput();
      el?.addEventListener('input', rawInputHandler);
      return () => el?.removeEventListener('input', rawInputHandler);
  }, [saveContent]);

  const execCmd = (command: string, value: string | undefined = undefined) => {
    document.execCommand(command, false, value);
    if (editorRef.current) editorRef.current.focus();
    saveContent();
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'z') {
      e.preventDefault();
      if (e.shiftKey) document.execCommand('redo');
      else document.execCommand('undo');
      saveContent();
    }
  };

  return (
    <div className={`flex h-[calc(100vh-140px)] gap-6 mx-auto relative px-6 pb-6 transition-all duration-500 ease-out ${showDoc || targetJob ? 'w-full max-w-none' : 'max-w-[1400px]'}`}>

        {/* WAR ROOM SIDEBAR (Suggestion 2 & 1) */}
        {targetJob && (
            <div className="w-[380px] shrink-0 flex flex-col gap-6 animate-in slide-in-from-left-8 duration-500">
                {/* Job Brief Card */}
                <div className="bg-white dark:bg-[#1C1C1E] rounded-3xl p-6 shadow-sm border border-black/5 dark:border-white/10 flex flex-col gap-4">
                    <div className="flex items-center gap-2 text-[10px] font-bold text-[#0071e3] uppercase tracking-wider">
                        <Sparkles size={12} /> Live Strategy
                    </div>
                    <div>
                        <h3 className="text-lg font-bold leading-tight">{targetJob.title}</h3>
                        <p className="text-sm text-[#86868b]">{targetJob.company}</p>
                    </div>
                    <div className="prose prose-sm dark:prose-invert line-clamp-[8] text-xs leading-relaxed opacity-80">
                        {targetJob.analysis?.strategy || targetJob.summary}
                    </div>
                </div>

                {/* Keyword Gap Highlighter (Suggestion 1) */}
                <div className="bg-white dark:bg-[#1C1C1E] rounded-3xl p-6 shadow-sm border border-black/5 dark:border-white/10 flex flex-col flex-1 overflow-hidden">
                    <div className="flex items-center justify-between mb-4">
                        <h4 className="text-[11px] font-bold uppercase tracking-wider text-[#86868b]">Keyword Gap</h4>
                        <span className="text-[10px] font-bold px-2 py-0.5 bg-[#f5f5f7] dark:bg-[#2C2C2E] rounded-full">
                            {foundKeywords.size}/{keywords.length}
                        </span>
                    </div>
                    <div className="flex-1 overflow-y-auto custom-scrollbar space-y-2">
                        {keywords.length > 0 ? keywords.map(kw => {
                            const isFound = foundKeywords.has(kw);
                            return (
                                <div key={kw} className={`flex items-center justify-between p-3 rounded-xl border transition-all ${isFound ? 'bg-[#E6F4EA] border-[#137333]/20 text-[#137333]' : 'bg-[#f5f5f7] border-transparent text-[#86868b] opacity-60'}`}>
                                    <span className="text-[12px] font-semibold">{kw}</span>
                                    {isFound ? <CheckCircle2 size={14} /> : <div className="w-1.5 h-1.5 rounded-full bg-[#86868b]" />}
                                </div>
                            );
                        }) : (
                            <p className="text-xs text-center text-[#86868b] py-8">No specific keywords extracted for this analysis.</p>
                        )}
                    </div>
                </div>
            </div>
        )}

        {/* EDITOR AREA */}
        <div className="flex-1 flex flex-col bg-white dark:bg-[#1C1C1E] rounded-[32px] shadow-sm overflow-hidden border border-black/5 dark:border-white/10 transition-all duration-300">
            <div className="h-16 border-b border-[#f5f5f7] dark:border-[#38383A] flex items-center px-6 justify-between bg-white/80 dark:bg-[#1C1C1E]/80 backdrop-blur-md z-10 sticky top-0 transition-colors">
                <div className="flex items-center gap-1" role="toolbar" aria-label="Formatting Controls">
                    <button onClick={() => execCmd('undo')} className="p-2.5 hover:bg-[#f5f5f7] dark:hover:bg-[#2C2C2E] rounded-xl text-[#86868b] dark:text-[#98989D] hover:text-[#1d1d1f] dark:hover:text-white transition-colors" title="Undo"><RotateCcw size={18} /></button>
                    <button onClick={() => execCmd('redo')} className="p-2.5 hover:bg-[#f5f5f7] dark:hover:bg-[#2C2C2E] rounded-xl text-[#86868b] dark:text-[#98989D] hover:text-[#1d1d1f] dark:hover:text-white transition-colors" title="Redo"><RotateCw size={18} /></button>
                    <div className="w-px h-6 bg-[#e8e8ed] dark:bg-[#38383A] mx-2"></div>
                    <button onClick={() => execCmd('bold')} className="p-2.5 hover:bg-[#f5f5f7] dark:hover:bg-[#2C2C2E] rounded-xl text-[#86868b] dark:text-[#98989D] hover:text-[#1d1d1f] dark:hover:text-white font-bold" title="Bold"><Bold size={18} /></button>
                    <button onClick={() => execCmd('italic')} className="p-2.5 hover:bg-[#f5f5f7] dark:hover:bg-[#2C2C2E] rounded-xl text-[#86868b] dark:text-[#98989D] hover:text-[#1d1d1f] dark:hover:text-white italic" title="Italic"><Italic size={18} /></button>
                    <button onClick={() => execCmd('underline')} className="p-2.5 hover:bg-[#f5f5f7] dark:hover:bg-[#2C2C2E] rounded-xl text-[#86868b] dark:text-[#98989D] hover:text-[#1d1d1f] dark:hover:text-white underline" title="Underline"><Underline size={18} /></button>
                    <div className="w-px h-6 bg-[#e8e8ed] dark:bg-[#38383A] mx-2"></div>
                    <button onClick={() => execCmd('insertUnorderedList')} className="p-2.5 hover:bg-[#f5f5f7] dark:hover:bg-[#2C2C2E] rounded-xl text-[#86868b] dark:text-[#98989D] hover:text-[#1d1d1f] dark:hover:text-white" title="List"><List size={18} /></button>
                    <div className="w-px h-6 bg-[#e8e8ed] dark:bg-[#38383A] mx-2"></div>
                    <button onClick={() => execCmd('removeFormat')} className="p-2.5 hover:bg-[#FF3B30]/10 rounded-xl text-[#86868b] dark:text-[#98989D] hover:text-[#FF3B30] transition-colors" title="Clear Formatting"><Trash size={18} /></button>
                </div>
                <div className="flex items-center gap-3">
                    <button onClick={() => setShowDoc(!showDoc)} className={`h-10 px-5 rounded-full transition-all border flex items-center gap-2 text-[13px] font-semibold ${showDoc ? 'bg-[#1d1d1f] dark:bg-white text-white dark:text-black border-transparent shadow-md' : 'bg-white dark:bg-[#2C2C2E] text-[#86868b] dark:text-[#98989D] border-[#e8e8ed] dark:border-[#38383A] hover:border-[#86868b] dark:hover:border-[#98989D] hover:text-[#1d1d1f] dark:hover:text-white'}`} title="Reference Document">
                        <BookOpen size={16} /> {showDoc ? 'Hide Ref' : 'Show Ref'}
                    </button>
                     <div className="text-[11px] font-medium text-[#86868b] dark:text-[#98989D] bg-[#f5f5f7] dark:bg-[#2C2C2E] px-4 py-2 rounded-full border border-black/5 dark:border-white/5">
                        {lastSaved ? `Saved ${lastSaved}` : 'Unsaved'}
                    </div>
                </div>
            </div>
            <div className="flex-1 overflow-y-auto bg-[#F5F5F7] dark:bg-[#000000] flex relative custom-scrollbar transition-colors">
                {showDoc && (
                    <div className="w-1/2 h-full border-r border-[#e8e8ed] dark:border-[#38383A] bg-white dark:bg-[#1C1C1E] hidden lg:block animate-in slide-in-from-left-4 duration-500 ease-out">
                        <iframe src="https://docs.google.com/document/d/1RcERxf9--nMGdxXTHAt4q35yynk39Aqk31AqSuG02G4/preview" className="w-full h-full border-none" title="Reference CV"></iframe>
                    </div>
                )}
                <div className={`flex-1 flex justify-center p-8 transition-all duration-500 ${showDoc || targetJob ? 'bg-[#f0f0f2] dark:bg-[#121212]' : ''}`}>
                     <div ref={editorRef} contentEditable onKeyDown={handleKeyDown} role="textbox" aria-multiline="true" className={`w-full h-max bg-white shadow-[0_2px_15px_-3px_rgba(0,0,0,0.07),0_10px_20px_-2px_rgba(0,0,0,0.04)] dark:shadow-[0_2px_15px_-3px_rgba(0,0,0,0.5)] border border-[#e8e8ed] p-[72px] outline-none text-[#1d1d1f] font-sans text-lg leading-[1.6] transition-all rounded-sm mb-16 ${showDoc || targetJob ? 'max-w-full' : 'max-w-[850px]'}`}/>
                </div>
            </div>
        </div>
    </div>
  );
};

export default CVEditor;

import React, { useEffect, useState, useRef } from 'react';
import { X, ExternalLink, Briefcase, Zap, FileText, Sparkles, Edit2, Save, ChevronDown, RotateCw, TrendingUp, AlertTriangle, Loader2, Paperclip, Image as ImageIcon, Trash2, ChevronUp, Link as LinkIcon, Info } from 'lucide-react';
import { Job, Attachment } from '../types';

interface JobDetailModalProps {
  isOpen: boolean;
  onClose: () => void;
  job: Job | null;
  onGenerateKit: (job: Job) => void;
  initialTab?: 'brief' | 'strategy';
  onUpdateJob?: (job: Job) => void;
  onReAnalyze?: (job: Job) => Promise<void>;
  onTailorResume?: (id: string) => void;
}

const JobDetailModal: React.FC<JobDetailModalProps> = ({ isOpen, onClose, job, onGenerateKit, initialTab = 'brief', onUpdateJob, onReAnalyze, onTailorResume }) => {
  const [activeTab, setActiveTab] = useState<'brief' | 'strategy'>(initialTab);
  const [isGeneratingKit, setIsGeneratingKit] = useState(false);

  // Description State
  const [isEditingSummary, setIsEditingSummary] = useState(false);
  const [editedSummary, setEditedSummary] = useState('');
  const [isDescriptionExpanded, setIsDescriptionExpanded] = useState(false);

  // Title Editing
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [editedTitle, setEditedTitle] = useState('');

  // Company Editing
  const [isEditingCompany, setIsEditingCompany] = useState(false);
  const [editedCompany, setEditedCompany] = useState('');

  // Location Editing
  const [isEditingLocation, setIsEditingLocation] = useState(false);
  const [editedLocation, setEditedLocation] = useState('');

  // Posted Date Editing
  const [isEditingPostedDate, setIsEditingPostedDate] = useState(false);
  const [editedPostedDate, setEditedPostedDate] = useState('');

  // URL Editing
  const [isEditingUrl, setIsEditingUrl] = useState(false);
  const [editedUrl, setEditedUrl] = useState('');

  // Notes & Attachments
  const notesRef = useRef<HTMLDivElement>(null);
  const [isEditingNotes, setIsEditingNotes] = useState(false); 
  const fileInputRef = useRef<HTMLInputElement>(null);
  const lastJobIdRef = useRef<string>('');

  // Image Resizing State
  const [selectedImg, setSelectedImg] = useState<HTMLImageElement | null>(null);

  // Re-Analyze State
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  // Tooltip State
  const [showScoreReasoning, setShowScoreReasoning] = useState(false);

  useEffect(() => {
    setActiveTab(initialTab);
  }, [initialTab, isOpen, job]);

  // Sync local state with job prop
  useEffect(() => {
    if (job) {
        if (!isEditingSummary) setEditedSummary(job.summary || '');
        if (!isEditingTitle) setEditedTitle(job.title || '');
        if (!isEditingCompany) setEditedCompany(job.company || '');
        if (!isEditingLocation) setEditedLocation(job.location || '');
        if (!isEditingPostedDate) setEditedPostedDate(job.postedDate || '');
        if (!isEditingUrl) setEditedUrl(job.url === 'Manual Entry' ? '' : (job.url || ''));

        // Sync Notes to ContentEditable (Manual Sync to prevent cursor jumps)
        if (notesRef.current) {
            const isDifferentJob = lastJobIdRef.current !== job.id;

            // If it's a new job, always load the notes
            if (isDifferentJob) {
                notesRef.current.innerHTML = job.notes || '';
                lastJobIdRef.current = job.id;
                setSelectedImg(null); // Reset selection
            } 
            else {
                const isActive = document.activeElement === notesRef.current;
                if (!isActive && job.notes !== notesRef.current.innerHTML) {
                    notesRef.current.innerHTML = job.notes || '';
                }
            }
        }
    }
  }, [job, isEditingSummary, isEditingTitle, isEditingCompany, isEditingLocation, isEditingPostedDate, isEditingUrl]);

  // Auto-save Summary Debounce
  useEffect(() => {
      const timer = setTimeout(() => {
          if (isEditingSummary && onUpdateJob && job && editedSummary !== job.summary) {
              onUpdateJob({ ...job, summary: editedSummary });
          }
      }, 1000); 
      return () => clearTimeout(timer);
  }, [editedSummary, isEditingSummary, job, onUpdateJob]);

  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
      setIsDescriptionExpanded(false);
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => { document.body.style.overflow = 'unset'; };
  }, [isOpen, job?.id]);

  if (!isOpen || !job) return null;

  const analysis = job.analysis;
  const attachments = job.attachments || [];

  const getAbsoluteUrl = (url?: string) => {
      if (!url || url === 'Manual Entry') return null;
      return url.startsWith('http') ? url : `https://${url}`;
  };

  const applyUrl = getAbsoluteUrl(job.url) || `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;

  // --- Handlers ---

  const handleSaveDescription = () => {
      if (onUpdateJob) {
          onUpdateJob({ ...job, summary: editedSummary });
          setIsEditingSummary(false);
      }
  };

  const handleSaveTitle = () => {
      if (onUpdateJob && editedTitle.trim() !== job.title) {
          onUpdateJob({ ...job, title: editedTitle });
      }
      setIsEditingTitle(false);
  };

  const handleSaveCompany = () => {
      if (onUpdateJob && editedCompany.trim() !== job.company) {
          onUpdateJob({ ...job, company: editedCompany });
      }
      setIsEditingCompany(false);
  };

  const handleSaveLocation = () => {
      if (onUpdateJob && editedLocation.trim() !== job.location) {
          onUpdateJob({ ...job, location: editedLocation });
      }
      setIsEditingLocation(false);
  };

  const handleSavePostedDate = () => {
      if (onUpdateJob && editedPostedDate.trim() !== job.postedDate) {
          onUpdateJob({ ...job, postedDate: editedPostedDate });
      }
      setIsEditingPostedDate(false);
  };

  const handleSaveUrl = () => {
      if (onUpdateJob && editedUrl.trim() !== job.url) {
          const finalUrl = editedUrl.trim() || 'Manual Entry';
          onUpdateJob({ ...job, url: finalUrl });
      }
      setIsEditingUrl(false);
  };

  const handleStatusChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
      if (onUpdateJob) {
          onUpdateJob({ ...job, status: e.target.value as Job['status'] });
      }
  };

  const handleReAnalyzeClick = async () => {
      if (onReAnalyze) {
          setIsAnalyzing(true);
          await onReAnalyze(job);
          setIsAnalyzing(false);
      }
  };

  const handleGenerateKitClick = async () => {
      setIsGeneratingKit(true);
      await onGenerateKit(job);
      setIsGeneratingKit(false);
  };

  // --- Rich Text Notes Handlers ---

  const handleNotesUpdate = () => {
      if (notesRef.current && onUpdateJob) {
          const newNotes = notesRef.current.innerHTML;
          if (newNotes !== job.notes) {
              onUpdateJob({ ...job, notes: newNotes });
          }
      }
  };

  const handleNotesBlur = () => {
      setIsEditingNotes(false);
      handleNotesUpdate();
  };

  const compressImage = (file: File): Promise<string> => {
      return new Promise((resolve, reject) => {
          const reader = new FileReader();
          reader.onload = (event) => {
              const img = new Image();
              img.onload = () => {
                  const canvas = document.createElement('canvas');
                  const MAX_WIDTH = 800; 
                  let width = img.width;
                  let height = img.height;
                  if (width > MAX_WIDTH) {
                      height = height * (MAX_WIDTH / width);
                      width = MAX_WIDTH;
                  }
                  canvas.width = width;
                  canvas.height = height;
                  const ctx = canvas.getContext('2d');
                  if (ctx) {
                      ctx.drawImage(img, 0, 0, width, height);
                      resolve(canvas.toDataURL('image/jpeg', 0.7));
                  } else {
                      reject(new Error('Canvas context failed'));
                  }
              };
              img.src = event.target?.result as string;
          };
          reader.readAsDataURL(file);
      });
  };

  const handleNotesPaste = async (e: React.ClipboardEvent) => {
    const items = e.clipboardData.items;
    for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1) {
            e.preventDefault();
            const blob = items[i].getAsFile();
            if (blob) {
                try {
                    const compressedDataUrl = await compressImage(blob);
                    const imgHtml = `<img src="${compressedDataUrl}" style="max-width: 100%; width: auto; border-radius: 8px; margin: 10px 0; display: block; cursor: pointer;" />`;
                    document.execCommand('insertHTML', false, imgHtml);
                    handleNotesUpdate();
                } catch (err) {
                    console.error("Image compression failed", err);
                }
            }
            return;
        }
    }
    const pastedText = e.clipboardData.getData('text');
    const selection = window.getSelection();
    if (selection && !selection.isCollapsed) {
        const isUrl = /^(http|https):\/\/[^ "]+$/.test(pastedText);
        if (isUrl) {
            e.preventDefault();
            document.execCommand('createLink', false, pastedText);
            handleNotesUpdate();
            return;
        }
    }
  };

  const handleEditorClick = (e: React.MouseEvent) => {
      const target = e.target as HTMLElement;
      if (target.tagName === 'IMG') {
          setSelectedImg(target as HTMLImageElement);
      } else {
          const isToolbar = (e.target as HTMLElement).closest('.image-resize-toolbar');
          if (!isToolbar) {
            setSelectedImg(null);
          }
      }
      setIsEditingNotes(true);
  };

  const resizeImage = (percentage: string) => {
      if (selectedImg) {
          selectedImg.style.width = percentage;
          selectedImg.style.height = 'auto'; 
          handleNotesUpdate();
      }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files.length > 0) {
          const file = e.target.files[0];
          const reader = new FileReader();
          reader.onload = (event) => {
              const newAttachment: Attachment = {
                  id: Date.now().toString(),
                  name: file.name,
                  type: file.type,
                  size: file.size,
                  data: event.target?.result as string
              };
              if (onUpdateJob) {
                  onUpdateJob({ ...job, attachments: [...(job.attachments || []), newAttachment] });
              }
          };
          reader.readAsDataURL(file);
      }
      if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleDeleteAttachment = (id: string) => {
      if (onUpdateJob) {
          onUpdateJob({ ...job, attachments: (job.attachments || []).filter(a => a.id !== id) });
      }
  };

  const isValidAttribute = (attr?: string) => {
      if (!attr) return false;
      const lower = attr.toLowerCase();
      return lower !== 'unspecified' && lower !== 'unknown' && lower !== 'n/a' && attr.trim() !== '';
  };

  return (
    <div 
        className="fixed inset-0 z-[100] flex items-center justify-center p-4 sm:p-6 transition-all duration-300"
        role="dialog"
        aria-modal="true"
    >
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose}></div>

      <div className="relative bg-white dark:bg-[#1C1C1E] w-full max-w-5xl h-[90vh] flex flex-col shadow-2xl rounded-[32px] overflow-hidden animate-in fade-in zoom-in-95 duration-200 border border-transparent dark:border-white/10 transition-colors">

        <div className="flex items-start justify-between px-8 py-8 shrink-0 bg-white dark:bg-[#1C1C1E] z-10 transition-colors">
           <div className="flex-1 mr-8">
                {isEditingTitle ? (
                    <input 
                    type="text" 
                    value={editedTitle}
                    onChange={(e) => setEditedTitle(e.target.value)}
                    onBlur={handleSaveTitle}
                    onKeyDown={(e) => e.key === 'Enter' && handleSaveTitle()}
                    className="text-3xl font-semibold text-[#1d1d1f] dark:text-white w-full outline-none bg-transparent p-0 border-b border-[#0071e3] dark:border-[#0A84FF]"
                    autoFocus
                    />
                ) : (
                    <h2 
                    onClick={() => setIsEditingTitle(true)}
                    className="text-3xl font-semibold text-[#1d1d1f] dark:text-white leading-tight cursor-pointer hover:text-[#0071e3] dark:hover:text-[#0A84FF] transition-colors"
                    >
                    {job.title}
                    </h2>
                )}

                <div className="mt-2 flex items-center gap-2 text-lg text-[#86868b] dark:text-[#98989D] font-medium">
                    {isEditingCompany ? (
                        <input 
                            type="text" 
                            value={editedCompany}
                            onChange={(e) => setEditedCompany(e.target.value)}
                            onBlur={handleSaveCompany}
                            className="border-b border-[#0071e3] dark:border-[#0A84FF] outline-none bg-transparent w-40 text-[#1d1d1f] dark:text-white"
                        />
                    ) : (
                        <span onClick={() => setIsEditingCompany(true)} className="hover:text-[#0071e3] dark:hover:text-[#0A84FF] cursor-pointer transition-colors">{job.company}</span>
                    )}
                    <span>•</span>
                    <span>{job.location}</span>
                </div>
           </div>

           <button 
                onClick={onClose} 
                className="w-10 h-10 flex items-center justify-center bg-[#f5f5f7] dark:bg-[#2C2C2E] hover:bg-[#e8e8ed] dark:hover:bg-[#38383A] rounded-full text-[#1d1d1f] dark:text-white transition-colors"
           >
             <X size={20} />
           </button>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar px-8 pb-12">
            <div className="flex flex-col md:flex-row gap-12">

                <div className="flex-1 order-2 md:order-1 min-w-0">

                    <div className="flex items-center gap-1 mb-8 bg-[#f5f5f7] dark:bg-[#2C2C2E] p-1 rounded-full w-fit">
                        <button 
                            onClick={() => setActiveTab('brief')} 
                            className={`px-5 py-2 rounded-full text-[13px] font-semibold transition-all ${activeTab === 'brief' ? 'bg-white dark:bg-[#1C1C1E] text-black dark:text-white shadow-sm' : 'text-[#86868b] dark:text-[#98989D] hover:text-[#1d1d1f] dark:hover:text-white'}`}
                        >
                            Overview
                        </button>
                        <button 
                            onClick={() => {
                                setActiveTab('strategy');
                                if (!analysis?.strategy) handleGenerateKitClick();
                            }} 
                            className={`px-5 py-2 rounded-full text-[13px] font-semibold transition-all ${activeTab === 'strategy' ? 'bg-white dark:bg-[#1C1C1E] text-black dark:text-white shadow-sm' : 'text-[#86868b] dark:text-[#98989D] hover:text-[#1d1d1f] dark:hover:text-white'}`}
                        >
                            Strategy Kit
                        </button>
                    </div>

                    {activeTab === 'brief' ? (
                        <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
                            <div className="mb-8 flex flex-wrap gap-2">
                                {analysis && analysis.isHighValue && (
                                     <span className="px-3 py-1 rounded-full text-[12px] font-semibold bg-[#E6F4EA] dark:bg-[#1e3a29] text-[#137333] dark:text-[#45D469]">High Value</span>
                                )}
                                {isValidAttribute(analysis?.industry) && (
                                    <span className="px-3 py-1 rounded-full text-[12px] font-semibold bg-[#E8F2FF] dark:bg-[#122438] text-[#0071e3] dark:text-[#409CFF]">{analysis?.industry}</span>
                                )}
                                {isValidAttribute(job.seniorityScore) && (
                                    <span className="px-3 py-1 bg-[#f5f5f7] dark:bg-[#2C2C2E] text-[#1d1d1f] dark:text-[#f5f5f7] rounded-full text-[12px] font-semibold">{job.seniorityScore}</span>
                                )}
                            </div>

                            {analysis ? (
                                <div className="mb-8">
                                    <h4 className="text-[11px] font-bold text-[#86868b] dark:text-[#98989D] uppercase tracking-wider mb-2">AI Analysis</h4>
                                    <p className="text-[18px] text-[#1d1d1f] dark:text-[#f5f5f7] font-medium leading-relaxed">{analysis.verdict}</p>
                                </div>
                            ) : (
                                <div className="mb-8 p-6 bg-gradient-to-r from-blue-50/50 to-indigo-50/50 dark:from-blue-900/10 dark:to-indigo-900/10 rounded-2xl border border-blue-100 dark:border-blue-900/30">
                                    <div className="flex items-center gap-3 mb-3">
                                         <Loader2 className="text-[#0071e3] dark:text-[#0A84FF] animate-spin" size={20} />
                                         <span className="text-sm font-semibold text-[#0071e3] dark:text-[#0A84FF] animate-pulse">Analysing Opportunity...</span>
                                    </div>
                                    <div className="space-y-3 opacity-60">
                                        <div className="h-4 bg-[#0071e3]/10 dark:bg-[#0A84FF]/20 rounded w-3/4 animate-pulse"></div>
                                        <div className="h-4 bg-[#0071e3]/10 dark:bg-[#0A84FF]/20 rounded w-1/2 animate-pulse"></div>
                                    </div>
                                </div>
                            )}

                            <div className="mb-10">
                                <div className="flex items-center justify-between mb-3">
                                    <h4 className="text-[11px] font-bold text-[#86868b] dark:text-[#98989D] uppercase tracking-wider">Job Description</h4>
                                    {!isEditingSummary ? (
                                        <button onClick={() => setIsEditingSummary(true)} className="text-[11px] font-bold text-[#0071e3] dark:text-[#0A84FF] hover:underline">Edit</button>
                                    ) : (
                                        <span className="text-[10px] text-[#86868b] dark:text-[#98989D] font-medium flex items-center gap-1">
                                            <Save size={10} /> Auto-saving...
                                        </span>
                                    )}
                                </div>

                                {isEditingSummary ? (
                                    <div className="relative">
                                        <textarea 
                                            value={editedSummary}
                                            onChange={(e) => setEditedSummary(e.target.value)}
                                            className="w-full h-[400px] p-4 border border-[#0071e3] dark:border-[#0A84FF] rounded-xl text-[15px] leading-relaxed focus:outline-none bg-white dark:bg-[#2C2C2E] dark:text-[#f5f5f7] font-sans resize-y"
                                            autoFocus
                                        />
                                        <button 
                                            onClick={handleSaveDescription} 
                                            className="absolute bottom-4 right-4 bg-[#0071e3] text-white px-4 py-1.5 rounded-full text-xs font-semibold hover:scale-105 transition-transform shadow-md"
                                        >
                                            Done
                                        </button>
                                    </div>
                                ) : (
                                    <div className="relative">
                                        <div className={`text-[#424245] dark:text-[#B0B0B5] text-[15px] leading-relaxed whitespace-pre-wrap ${!isDescriptionExpanded ? 'line-clamp-custom' : ''}`}>
                                            {job.summary || <span className="text-gray-400 italic">No description available.</span>}
                                        </div>
                                        {(job.summary && job.summary.length > 300) && (
                                            <button 
                                                onClick={() => setIsDescriptionExpanded(!isDescriptionExpanded)}
                                                className="mt-2 text-[12px] font-bold text-[#0071e3] dark:text-[#0A84FF] flex items-center gap-1 hover:underline"
                                            >
                                                {isDescriptionExpanded ? (
                                                    <>Show Less <ChevronUp size={12} /></>
                                                ) : (
                                                    <>Read More <ChevronDown size={12} /></>
                                                )}
                                            </button>
                                        )}
                                        <style>{`
                                            .line-clamp-custom {
                                                display: -webkit-box;
                                                -webkit-line-clamp: 10;
                                                -webkit-box-orient: vertical;
                                                overflow: hidden;
                                            }
                                        `}</style>
                                    </div>
                                )}
                            </div>

                            <div className="mb-10">
                                <div className="flex items-center justify-between mb-3">
                                     <h4 className="text-[11px] font-bold text-[#86868b] dark:text-[#98989D] uppercase tracking-wider">Attachments</h4>
                                     <button 
                                        onClick={() => fileInputRef.current?.click()}
                                        className="text-[11px] font-bold text-[#0071e3] dark:text-[#0A84FF] flex items-center gap-1 hover:underline"
                                     >
                                        <Paperclip size={12} /> Add File
                                     </button>
                                     <input 
                                        type="file" 
                                        multiple
                                        ref={fileInputRef}
                                        className="hidden"
                                        onChange={handleFileUpload}
                                     />
                                </div>
                                {attachments.length > 0 ? (
                                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                                        {attachments.map((file) => (
                                            <div key={file.id} className="flex items-center gap-3 p-3 rounded-xl bg-[#f5f5f7] dark:bg-[#2C2C2E] border border-transparent hover:border-[#d2d2d7] dark:hover:border-[#38383A] transition-colors group">
                                                <div className="w-10 h-10 rounded-lg bg-white dark:bg-black/20 flex items-center justify-center text-[#86868b] dark:text-[#98989D]">
                                                    {file.type.includes('image') ? <ImageIcon size={20} /> : <FileText size={20} />}
                                                </div>
                                                <div className="flex-1 min-w-0">
                                                    <p className="text-[13px] font-semibold text-[#1d1d1f] dark:text-white truncate">{file.name}</p>
