    if (!db) return "";
    try {
        const docRef = doc(db, "user_data", "cv_main");
        const snapshot = await getDoc(docRef);
        if (snapshot.exists()) {
            return snapshot.data().content || "";
        }
    } catch (e) {
        console.error("Error fetching CV:", e);
    }
    return "";
