const CVEditor: React.FC<CVEditorProps> = ({ targetJob }) => {
  const editorRef = useRef<HTMLDivElement>(null);
  const [lastSaved, setLastSaved] = useState<string>('');
  const [showDoc, setShowDoc] = useState(false);
  const [foundKeywords, setFoundKeywords] = useState<Set<string>>(new Set());
  const [activeSidebarTab, setActiveSidebarTab] = useState<'strategy' | 'keywords' | 'snippets' | 'interview'>('strategy');

  // Suggestion 4: Interview Prep State
  const [currentFlashcard, setCurrentFlashcard] = useState(0);

  const keywords = useMemo(() => targetJob?.analysis?.matchedKeywords || [], [targetJob]);

  const scanKeywords = useCallback(() => {
    if (!editorRef.current || keywords.length === 0) return;
    const text = editorRef.current.innerText.toLowerCase();
    const found = new Set<string>();
    keywords.forEach(kw => {
        if (text.toLowerCase().includes(kw.toLowerCase())) found.add(kw);
    });
    setFoundKeywords(found);
  }, [keywords]);

  useEffect(() => {
    const loadContent = async () => {
        let content = "";
        if (targetJob) {
            // Suggestion 6: Versioning. Load job-specific CV or fallback to main
            content = targetJob.tailoredCv || await getCV();
        } else {
            content = await getCV();
        }

        if (editorRef.current) {
            if (content) {
                editorRef.current.innerHTML = content;
                setLastSaved(targetJob ? 'Tailored Version' : 'Main CV');
            } else if (!editorRef.current.innerHTML.trim()) {
                editorRef.current.innerHTML = `
                <h1 style="font-size: 2em; font-weight: bold; margin-bottom: 0.5em; color: #1d1d1f;">Senior UX Designer</h1>
                <p><strong>Summary</strong></p>
                <p>Strategic and human-centered Senior UX Designer with 7+ years of experience transforming complex financial and insurance problems into intuitive digital solutions.</p>
                `;
            }
            scanKeywords();
        }
    };
    loadContent();
  }, [targetJob?.id, scanKeywords]);

  const saveContent = useCallback(async () => {
    if (!editorRef.current) return;
    const html = editorRef.current.innerHTML;
    if (targetJob) {
        await saveJobCV(targetJob.id, html);
    } else {
        await saveCV(html);
    }
    const now = new Date();
    setLastSaved(now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
    scanKeywords();
  }, [targetJob, scanKeywords]);

  useEffect(() => {
      const handleInput = () => {
          const timeoutId = setTimeout(() => saveContent(), 1000);
          return () => clearTimeout(timeoutId);
      };
      const el = editorRef.current;
      el?.addEventListener('input', handleInput);
      return () => el?.removeEventListener('input', handleInput);
  }, [saveContent]);

  const execCmd = (command: string, value: string | undefined = undefined) => {
    document.execCommand(command, false, value);
    if (editorRef.current) editorRef.current.focus();
    saveContent();
  };

  const insertSnippet = (content: string) => {
      if (editorRef.current) {
          editorRef.current.focus();
          document.execCommand('insertHTML', false, `<p>${content}</p>`);
          saveContent();
      }
  };

  const interviewQuestions = useMemo(() => {
      if (!targetJob?.analysis?.strategy) return ["Tell us about your experience with accessibility.", "How do you handle stakeholder pushback?", "Walk us through your design system process."];
      // Simple extraction of questions from strategy text if possible
      return targetJob.analysis.strategy.match(/\?.*$/gm) || ["Tell us about your work on design systems.", "How did you scale Trove?", "What's your approach to WCAG 2.1 compliance?"];
  }, [targetJob]);

  return (
    <div className={`flex h-[calc(100vh-140px)] gap-6 mx-auto relative px-6 pb-6 transition-all duration-500 ease-out ${showDoc || targetJob ? 'w-full max-w-none' : 'max-w-[1400px]'}`}>

        {/* WAR ROOM SIDEBAR (Suggestions 1, 2, 3, 4) */}
        {targetJob && (
            <div className="w-[400px] shrink-0 flex flex-col gap-4 animate-in slide-in-from-left-8 duration-500">
                {/* Header Controls */}
                <div className="flex bg-[#f5f5f7] dark:bg-[#2C2C2E] p-1 rounded-2xl w-full">
                    <button onClick={() => setActiveSidebarTab('strategy')} className={`flex-1 flex items-center justify-center py-2 rounded-xl transition-all ${activeSidebarTab === 'strategy' ? 'bg-white dark:bg-[#1C1C1E] shadow-sm' : 'opacity-60'}`}><Sparkles size={16} /></button>
                    <button onClick={() => setActiveSidebarTab('keywords')} className={`flex-1 flex items-center justify-center py-2 rounded-xl transition-all ${activeSidebarTab === 'keywords' ? 'bg-white dark:bg-[#1C1C1E] shadow-sm' : 'opacity-60'}`}><Layout size={16} /></button>
                    <button onClick={() => setActiveSidebarTab('snippets')} className={`flex-1 flex items-center justify-center py-2 rounded-xl transition-all ${activeSidebarTab === 'snippets' ? 'bg-white dark:bg-[#1C1C1E] shadow-sm' : 'opacity-60'}`}><Book size={16} /></button>
                    <button onClick={() => setActiveSidebarTab('interview')} className={`flex-1 flex items-center justify-center py-2 rounded-xl transition-all ${activeSidebarTab === 'interview' ? 'bg-white dark:bg-[#1C1C1E] shadow-sm' : 'opacity-60'}`}><MessageCircle size={16} /></button>
                </div>

                <div className="flex-1 overflow-hidden bg-white dark:bg-[#1C1C1E] rounded-[32px] border border-black/5 dark:border-white/10 flex flex-col">
                    <div className="p-6 overflow-y-auto custom-scrollbar flex-1">

                        {activeSidebarTab === 'strategy' && (
                            <div className="animate-in fade-in slide-in-from-bottom-2">
                                <h3 className="text-lg font-bold mb-4 flex items-center gap-2">Strategy Kit</h3>
                                <div className="prose prose-sm dark:prose-invert whitespace-pre-wrap opacity-90 leading-relaxed text-[13px]">
                                    {targetJob.analysis?.strategy || "No strategy generated yet."}
                                </div>
                            </div>
                        )}

                        {activeSidebarTab === 'keywords' && (
                            <div className="animate-in fade-in slide-in-from-bottom-2">
                                <div className="flex items-center justify-between mb-4">
                                    <h3 className="text-lg font-bold">Keyword Gap</h3>
                                    <span className="text-xs font-bold px-2 py-1 bg-[#f5f5f7] dark:bg-[#2C2C2E] rounded-full">{foundKeywords.size}/{keywords.length}</span>
                                </div>
                                <div className="space-y-2">
                                    {keywords.map(kw => {
                                        const isFound = foundKeywords.has(kw);
                                        return (
                                            <div key={kw} className={`group p-3 rounded-2xl border transition-all flex items-center justify-between ${isFound ? 'bg-[#E6F4EA] border-[#137333]/10 text-[#137333]' : 'bg-[#f5f5f7] dark:bg-[#2C2C2E] border-transparent opacity-60'}`}>
                                                <span className="text-sm font-semibold">{kw}</span>
                                                {isFound ? <CheckCircle2 size={16} /> : <Wand2 size={14} className="opacity-0 group-hover:opacity-100 cursor-help" title="AI Suggestion coming soon" />}
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>
                        )}

                        {activeSidebarTab === 'snippets' && (
                            <div className="animate-in fade-in slide-in-from-bottom-2">
                                <h3 className="text-lg font-bold mb-4">Achievement Library</h3>
                                <div className="space-y-4">
                                    {USER_PROFILE.caseStudies.map((cs, i) => (
                                        <div key={i} onClick={() => insertSnippet(`${cs.title}: ${cs.description}`)} className="p-4 rounded-2xl bg-[#f5f5f7] dark:bg-[#2C2C2E] hover:border-[#0071e3] border border-transparent cursor-pointer transition-all group">
                                            <p className="text-[10px] font-bold uppercase tracking-wider text-[#86868b] mb-1">{cs.title}</p>
                                            <p className="text-sm leading-snug group-hover:text-[#0071e3]">{cs.description}</p>
                                        </div>
                                    ))}
                                    {USER_PROFILE.awards.map((award, i) => (
                                        <div key={`a-${i}`} onClick={() => insertSnippet(`Awarded: ${award}`)} className="p-4 rounded-2xl bg-[#f5f5f7] dark:bg-[#2C2C2E] hover:border-[#0071e3] border border-transparent cursor-pointer transition-all group">
                                            <p className="text-sm font-bold group-hover:text-[#0071e3]">{award}</p>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}

                        {activeSidebarTab === 'interview' && (
                            <div className="animate-in fade-in slide-in-from-bottom-2 flex flex-col h-full">
                                <h3 className="text-lg font-bold mb-6">Prep Mode</h3>
                                <div className="flex-1 flex flex-col items-center justify-center">
                                    <div className="w-full aspect-video bg-gradient-to-br from-[#0071e3] to-[#5856d6] rounded-3xl p-8 text-white flex flex-col shadow-xl">
                                        <HelpCircle className="opacity-40 mb-auto" size={24} />
                                        <p className="text-xl font-semibold leading-tight text-center px-4">
                                            {interviewQuestions[currentFlashcard]}
                                        </p>
                                        <div className="mt-auto flex justify-center gap-2">
                                            <div className="w-1.5 h-1.5 rounded-full bg-white/20"></div>
                                            <div className="w-1.5 h-1.5 rounded-full bg-white"></div>
                                            <div className="w-1.5 h-1.5 rounded-full bg-white/20"></div>
                                        </div>
                                    </div>
                                    <button 
                                        onClick={() => setCurrentFlashcard((currentFlashcard + 1) % interviewQuestions.length)}
                                        className="mt-8 flex items-center gap-2 text-sm font-bold text-[#0071e3]"
                                    >
                                        Next Question <ChevronRight size={16} />
                                    </button>
                                </div>
                            </div>
                        )}

                    </div>
                    <div className="p-4 bg-[#f5f5f7] dark:bg-[#2C2C2E] border-t border-black/5 flex items-center gap-2">
                        <div className="w-8 h-8 rounded-full bg-gray-500 text-white flex items-center justify-center text-[10px] font-bold">VP</div>
                        <div className="text-[11px] font-medium leading-tight">
                            <p className="text-black dark:text-white">Vyom's Studio</p>
                            <p className="text-[#86868b] uppercase tracking-wider">Production Mode</p>
                        </div>
                    </div>
                </div>
            </div>
        )}

        {/* EDITOR AREA */}
        <div className="flex-1 flex flex-col bg-white dark:bg-[#1C1C1E] rounded-[32px] shadow-sm overflow-hidden border border-black/5 dark:border-white/10 transition-all duration-300">
            <div className="h-16 border-b border-[#f5f5f7] dark:border-[#38383A] flex items-center px-6 justify-between bg-white/80 dark:bg-[#1C1C1E]/80 backdrop-blur-md z-10 sticky top-0 transition-colors">
                <div className="flex items-center gap-1">
                    <button onClick={() => execCmd('undo')} className="p-2.5 hover:bg-[#f5f5f7] dark:hover:bg-[#2C2C2E] rounded-xl text-[#86868b]"><RotateCcw size={18} /></button>
                    <button onClick={() => execCmd('redo')} className="p-2.5 hover:bg-[#f5f5f7] dark:hover:bg-[#2C2C2E] rounded-xl text-[#86868b]"><RotateCw size={18} /></button>
                    <div className="w-px h-6 bg-[#e8e8ed] dark:bg-[#38383A] mx-2"></div>
                    <button onClick={() => execCmd('bold')} className="p-2.5 hover:bg-[#f5f5f7] dark:hover:bg-[#2C2C2E] rounded-xl text-[#86868b] font-bold">B</button>
                    <button onClick={() => execCmd('italic')} className="p-2.5 hover:bg-[#f5f5f7] dark:hover:bg-[#2C2C2E] rounded-xl text-[#86868b] italic">I</button>
                    <button onClick={() => execCmd('insertUnorderedList')} className="p-2.5 hover:bg-[#f5f5f7] dark:hover:bg-[#2C2C2E] rounded-xl text-[#86868b]"><List size={18} /></button>
                    <div className="w-px h-6 bg-[#e8e8ed] dark:bg-[#38383A] mx-2"></div>
                    <button onClick={() => execCmd('removeFormat')} className="p-2.5 hover:bg-[#FF3B30]/10 rounded-xl text-[#FF3B30]"><Trash size={18} /></button>
                </div>
                <div className="flex items-center gap-3">
                    <button onClick={() => setShowDoc(!showDoc)} className={`h-10 px-5 rounded-full transition-all border flex items-center gap-2 text-[13px] font-semibold ${showDoc ? 'bg-[#1d1d1f] dark:bg-white text-white dark:text-black shadow-md' : 'text-[#86868b]'}`}>
                        <BookOpen size={16} /> {showDoc ? 'Hide Ref' : 'Show Ref'}
                    </button>
                    <div className="text-[11px] font-medium text-[#86868b] bg-[#f5f5f7] dark:bg-[#2C2C2E] px-4 py-2 rounded-full border border-black/5">
                        {lastSaved}
                    </div>
                </div>
            </div>
            <div className="flex-1 overflow-y-auto bg-[#F5F5F7] dark:bg-[#000000] flex relative custom-scrollbar">
                {showDoc && (
                    <div className="w-1/2 h-full border-r border-[#e8e8ed] dark:border-[#38383A] bg-white dark:bg-[#1C1C1E] hidden lg:block animate-in slide-in-from-left-4 duration-500 ease-out">
                        <iframe src="https://docs.google.com/document/d/1RcERxf9--nMGdxXTHAt4q35yynk39Aqk31AqSuG02G4/preview" className="w-full h-full border-none" title="Reference CV"></iframe>
                    </div>
                )}
                <div className={`flex-1 flex justify-center p-8 transition-all duration-500 ${showDoc || targetJob ? 'bg-[#f0f0f2] dark:bg-[#121212]' : ''}`}>
                     <div ref={editorRef} contentEditable role="textbox" aria-multiline="true" className={`w-full h-max bg-white shadow-xl border border-[#e8e8ed] p-[72px] outline-none text-[#1d1d1f] font-sans text-lg leading-[1.6] transition-all rounded-sm mb-16 ${showDoc || targetJob ? 'max-w-full' : 'max-w-[850px]'}`}/>
                </div>
            </div>
        </div>
    </div>
  );
};

export default CVEditor;

import React from 'react';
import { Job } from '../types';
import { Briefcase, MapPin, ExternalLink, Trash2, Bookmark, Archive, Zap, ArrowRight, TrendingUp, CheckCircle2 } from 'lucide-react';

interface JobCardProps {
  job: Job;
  onOpenDetail: (job: Job, tab?: 'brief' | 'strategy') => void;
  onToggleStatus: (id: string, currentStatus: Job['status']) => void;
  onDelete: (id: string) => void;
  isKanban?: boolean;
  isSelected?: boolean;
  onSelect?: (id: string) => void;
  isSelectMode?: boolean;
}

const JobCard: React.FC<JobCardProps> = ({ job, onOpenDetail, onToggleStatus, onDelete, isKanban, isSelected, onSelect, isSelectMode }) => {
  const analysis = job.analysis;
  const status = job.status || 'new';
  const isSavedOrBetter = ['saved', 'applied', 'assessment', 'interview', 'offer'].includes(status);

  const getAbsoluteUrl = (url?: string) => {
      if (!url || url === 'Manual Entry') return null;
      return url.startsWith('http') ? url : `https://${url}`;
  };

  const applyUrl = getAbsoluteUrl(job.url) || `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;

  // Tiny Card for Kanban - Ultra Compact
  if (isKanban) {
      return (
        <div 
            className="bg-white dark:bg-[#1C1C1E] rounded-xl p-4 cursor-pointer shadow-[0_1px_3px_rgba(0,0,0,0.06)] hover:shadow-[0_4px_8px_rgba(0,0,0,0.08)] transition-all flex flex-col gap-2 border border-transparent hover:border-[#0071e3]/30 dark:hover:border-[#0A84FF]/30 dark:border-white/5"
            onClick={() => onOpenDetail(job)}
        >
            <div className="flex justify-between items-start gap-1">
                <h4 className="font-bold text-[15px] text-[#1d1d1f] dark:text-[#f5f5f7] leading-snug line-clamp-2">
                    {job.title}
                </h4>
            </div>

            <p className="text-[13px] text-[#86868b] dark:text-[#98989D] font-medium truncate">{job.company}</p>

            <div className="flex items-center justify-between mt-2">
                 {analysis?.score ? (
                     <div className="flex items-center gap-2">
                        <span className={`px-2 py-0.5 rounded text-[11px] font-bold ${analysis.score > 70 ? 'bg-[#E6F4EA] dark:bg-[#1e3a29] text-[#137333] dark:text-[#45D469]' : 'bg-[#F5F5F7] dark:bg-[#2C2C2E] text-[#5F6368] dark:text-[#98989D]'}`}>
                            {analysis.score}%
                        </span>
                        {/* Suggestion 5: Seniority Alignment Dot */}
                        <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: job.seniorityScore === 'Senior' || job.seniorityScore === 'Lead' ? '#34C759' : '#FFCC00' }}></div>
                     </div>
                 ) : (
                    <span className="text-[10px] text-[#d2d2d7] dark:text-[#555]">No Score</span>
                 )}
            </div>
        </div>
      );
  }

  // Full "Bento" Card for Dashboard
  return (
    <div 
        onClick={() => isSelectMode ? onSelect?.(job.id) : onOpenDetail(job)}
        className={`apple-card p-8 group cursor-pointer border relative transition-all duration-300 ${isSelected ? 'ring-2 ring-[#0071e3] border-[#0071e3] scale-[1.02]' : 'border-transparent hover:border-[#0071e3]/10 dark:hover:border-[#0A84FF]/20'} ${status === 'archived' ? 'opacity-60 grayscale' : ''}`}
    >

      {/* Top Right Actions / Selection Checkbox */}
      <div className="absolute top-6 right-6 flex flex-col gap-2 transition-opacity z-10">
         {isSelectMode ? (
             <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${isSelected ? 'bg-[#0071e3] border-[#0071e3] text-white' : 'border-[#d2d2d7] dark:border-[#38383A] bg-white dark:bg-[#2C2C2E]'}`}>
                {isSelected && <CheckCircle2 size={16} />}
             </div>
         ) : (
             <div className="opacity-0 group-hover:opacity-100 flex flex-col gap-2 transition-opacity">
                {status !== 'archived' && (
                    <button 
                        onClick={(e) => { e.stopPropagation(); onToggleStatus(job.id, status); }}
                        className={`w-9 h-9 flex items-center justify-center rounded-full transition-colors shadow-sm ${isSavedOrBetter 
                            ? 'bg-[#0071e3] text-white hover:bg-[#0077ED] dark:bg-[#0A84FF]' 
                            : 'bg-white dark:bg-[#2C2C2E] text-[#86868b] border border-[#d2d2d7] dark:border-[#38383A] hover:border-[#0071e3] hover:text-[#0071e3] dark:hover:border-[#0A84FF] dark:hover:text-[#0A84FF]'}`}
                        title={isSavedOrBetter ? "Saved" : "Save Job"}
                    >
                        <Bookmark size={16} fill={isSavedOrBetter ? "currentColor" : "none"} />
                    </button>
                )}

                <button 
                    onClick={(e) => { e.stopPropagation(); onDelete(job.id); }} 
                    className="w-9 h-9 flex items-center justify-center rounded-full bg-white dark:bg-[#2C2C2E] border border-[#d2d2d7] dark:border-[#38383A] hover:bg-[#FF3B30] hover:text-white hover:border-[#FF3B30] text-[#86868b] transition-colors shadow-sm"
                    title="Archive"
                >
                    {status === 'archived' ? <Trash2 size={16} /> : <Archive size={16} />}
                </button>
             </div>
         )}
      </div>

      <div className="flex flex-col sm:flex-row gap-6 items-start">

          <div className="flex-1 pr-12">
             <div className="mb-2 flex flex-wrap items-center gap-2">
                 <h3 className="text-[22px] font-semibold text-[#1d1d1f] dark:text-[#f5f5f7] tracking-tight group-hover:text-[#0071e3] dark:group-hover:text-[#0A84FF] transition-colors">
                    {job.title}
                 </h3>
                 {job.isRelatedDiscovery && <span className="bg-[#FFCC00] text-black text-[10px] font-bold px-1.5 py-0.5 rounded">NEW</span>}
                 {analysis?.isHighValue && <span className="bg-[#E6F4EA] text-[#137333] text-[10px] font-bold px-1.5 py-0.5 rounded flex items-center gap-0.5"><Zap size={10} fill="currentColor"/> HIGH VALUE</span>}
                 {analysis?.industry && analysis.industry !== 'Tech & Product' && <span className="bg-[#E8F2FF] text-[#0071e3] text-[10px] font-bold px-1.5 py-0.5 rounded uppercase">{analysis.industry} MATCH</span>}
             </div>

             <div className="flex items-center gap-4 text-[13px] font-medium text-[#86868b] dark:text-[#98989D] mb-5">
                <span className="flex items-center gap-1.5"><Briefcase size={14}/> {job.company}</span>
                <span className="w-1 h-1 bg-[#d2d2d7] dark:bg-[#38383A] rounded-full"></span>
                <span className="flex items-center gap-1.5"><MapPin size={14}/> {job.location}</span>
                <span className="w-1 h-1 bg-[#d2d2d7] dark:bg-[#38383A] rounded-full"></span>
                <span>{job.postedDate}</span>
             </div>

             <div className="flex flex-wrap items-center gap-2 mb-6">
                {analysis?.score && (
                     <div className="flex items-center gap-2">
                        <span className={`px-3 py-1 rounded-full text-[12px] font-bold flex items-center gap-1 ${analysis.score > 70 ? 'bg-[#E6F4EA] dark:bg-[#1e3a29] text-[#137333] dark:text-[#45D469]' : 'bg-[#F5F5F7] dark:bg-[#2C2C2E] text-[#5F6368] dark:text-[#98989D]'}`}>
                            <TrendingUp size={12} /> {analysis.score}% Match
                        </span>
                        {/* Suggestion 5: Seniority Alignment Gauge (Dot) */}
                        <div className="w-2.5 h-2.5 rounded-full shadow-sm" style={{ backgroundColor: job.seniorityScore === 'Senior' || job.seniorityScore === 'Lead' ? '#34C759' : '#FFCC00' }}></div>
                     </div>
                )}
                {job.seniorityScore && (
                     <span className="px-3 py-1 bg-[#F5F5F7] dark:bg-[#2C2C2E] text-[#1d1d1f] dark:text-[#f5f5f7] rounded-full text-[12px] font-semibold">{job.seniorityScore}</span>
                )}
             </div>

             <p className="text-[14px] leading-relaxed text-[#424245] dark:text-[#B0B0B5] line-clamp-2 mb-6">
                {analysis?.verdict || job.summary}
             </p>

             {!isSelectMode && (
                <div className="flex items-center gap-4">
                    <button 
                        onClick={(e) => { e.stopPropagation(); onOpenDetail(job, 'strategy'); }}
                        className="flex items-center gap-2 text-[14px] font-semibold text-[#0071e3] dark:text-[#0A84FF] hover:underline"
                    >
                        Apply Strategy <ArrowRight size={16} />
                    </button>
                    <a 
                        href={applyUrl} 
                        target="_blank" 
                        rel="noreferrer" 
                        onClick={(e) => e.stopPropagation()}
                        className="flex items-center gap-1 text-[13px] font-medium text-[#86868b] dark:text-[#98989D] hover:text-[#1d1d1f] dark:hover:text-white transition-colors"
                    >
                        View Source <ExternalLink size={14} />
                    </a>
                </div>
             )}
          </div>
      </div>
    </div>
  );
};

export default JobCard;

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
// Added Layout to the lucide-react imports
import { Bold, Italic, Underline, RotateCcw, RotateCw, List, BookOpen, Trash, Sparkles, CheckCircle2, Copy, Book, MessageCircle, HelpCircle, ChevronRight, Wand2, Layout } from 'lucide-react';
import { saveCV, getCV, saveJobCV } from '../services/firebase';
import { Job, UserProfile } from '../types';
import { USER_PROFILE } from '../constants';

interface CVEditorProps {
    targetJob?: Job | null;
}

const CVEditor: React.FC<CVEditorProps> = ({ targetJob }) => {
  const editorRef = useRef<HTMLDivElement>(null);
  const [lastSaved, setLastSaved] = useState<string>('');
  const [showDoc, setShowDoc] = useState(false);
  const [foundKeywords, setFoundKeywords] = useState<Set<string>>(new Set());
  const [activeSidebarTab, setActiveSidebarTab] = useState<'strategy' | 'keywords' | 'snippets' | 'interview'>('strategy');

  // Suggestion 4: Interview Prep State
  const [currentFlashcard, setCurrentFlashcard] = useState(0);

  const keywords = useMemo(() => targetJob?.analysis?.matchedKeywords || [], [targetJob]);

  const scanKeywords = useCallback(() => {
    if (!editorRef.current || keywords.length === 0) return;
    const text = editorRef.current.innerText.toLowerCase();
    const found = new Set<string>();
    keywords.forEach(kw => {
        if (text.toLowerCase().includes(kw.toLowerCase())) found.add(kw);
    });
    setFoundKeywords(found);
  }, [keywords]);

  useEffect(() => {
    const loadContent = async () => {
        let content = "";
        if (targetJob) {
            // Suggestion 6: Versioning. Load job-specific CV or fallback to main
            content = targetJob.tailoredCv || await getCV();
        } else {
            content = await getCV();
        }

        if (editorRef.current) {
            if (content) {
                editorRef.current.innerHTML = content;
                setLastSaved(targetJob ? 'Tailored Version' : 'Main CV');
            } else if (!editorRef.current.innerHTML.trim()) {
                editorRef.current.innerHTML = `
                <h1 style="font-size: 2em; font-weight: bold; margin-bottom: 0.5em; color: #1d1d1f;">Senior UX Designer</h1>
                <p><strong>Summary</strong></p>
                <p>Strategic and human-centered Senior UX Designer with 7+ years of experience transforming complex financial and insurance problems into intuitive digital solutions.</p>
                `;
            }
            scanKeywords();
        }
