import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Bold, Italic, Underline, RotateCcw, RotateCw, List, BookOpen, Trash, Sparkles, CheckCircle2, Copy, Book, MessageCircle, HelpCircle, ChevronRight, Wand2, Layout, Maximize2, Minimize2, ChevronLeft } from 'lucide-react';
import { saveCV, getCV, saveJobCV } from '../services/firebase';
import { Job } from '../types';
import { USER_PROFILE } from '../constants';

interface CVEditorProps {
    targetJob?: Job | null;
}

const CVEditor: React.FC<CVEditorProps> = ({ targetJob }) => {
  const editorRef = useRef<HTMLDivElement>(null);
  const [lastSaved, setLastSaved] = useState<string>('');
  const [showDoc, setShowDoc] = useState(false);
  const [isZenMode, setIsZenMode] = useState(false);
  const [foundKeywords, setFoundKeywords] = useState<Set<string>>(new Set());
  const [activeSidebarTab, setActiveSidebarTab] = useState<'strategy' | 'keywords' | 'snippets' | 'interview'>('strategy');
  const [currentFlashcard, setCurrentFlashcard] = useState(0);

  const keywords = useMemo(() => targetJob?.analysis?.matchedKeywords || [], [targetJob]);

  const scanKeywords = useCallback(() => {
    if (!editorRef.current || keywords.length === 0) return;
    const text = editorRef.current.innerText.toLowerCase();
    const found = new Set<string>();
    keywords.forEach(kw => {
        if (text.toLowerCase().includes(kw.toLowerCase())) found.add(kw);
    });
    setFoundKeywords(found);
  }, [keywords]);

  useEffect(() => {
    const loadContent = async () => {
        let content = "";
        if (targetJob) {
            content = targetJob.tailoredCv || await getCV();
        } else {
            content = await getCV();
        }

        if (editorRef.current) {
            editorRef.current.innerHTML = content || `
                <h1 style="font-size: 2em; font-weight: bold; margin-bottom: 0.5em; color: #1d1d1f;">Senior UX Designer</h1>
                <p><strong>Summary</strong></p>
                <p>Strategic and human-centered Senior UX Designer with 7+ years of experience transforming complex financial and insurance problems into intuitive digital solutions.</p>
            `;
            setLastSaved(targetJob ? 'Job-Specific Workspace' : 'Main CV');
            scanKeywords();
        }
    };
    loadContent();
  }, [targetJob?.id, scanKeywords]);

  const saveContent = useCallback(async () => {
    if (!editorRef.current) return;
    const html = editorRef.current.innerHTML;
    if (targetJob) {
        await saveJobCV(targetJob.id, html);
    } else {
        await saveCV(html);
    }
    const now = new Date();
    setLastSaved(now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
    scanKeywords();
  }, [targetJob, scanKeywords]);

  useEffect(() => {
      const handleInput = () => {
          const timeoutId = setTimeout(() => saveContent(), 1000);
          return () => clearTimeout(timeoutId);
      };
      const el = editorRef.current;
      el?.addEventListener('input', handleInput);
      return () => el?.removeEventListener('input', handleInput);
  }, [saveContent]);

  const execCmd = (command: string, value: string | undefined = undefined) => {
    document.execCommand(command, false, value);
    if (editorRef.current) editorRef.current.focus();
    saveContent();
  };

  const insertSnippet = (content: string) => {
      if (editorRef.current) {
          editorRef.current.focus();
          document.execCommand('insertHTML', false, `<p>${content}</p>`);
          saveContent();
      }
  };

  const keywordProgress = keywords.length > 0 ? (foundKeywords.size / keywords.length) * 100 : 0;

  const interviewQuestions = useMemo(() => {
      if (!targetJob?.analysis?.strategy) return ["How do you approach Design Systems?", "Describe your accessibility workflow.", "How do you handle stakeholder pushback?"];
      return targetJob.analysis.strategy.match(/\?.*$/gm) || ["Walk us through your Trove case study.", "How did you optimize compliance workflows at Intact?", "What is your UX philosophy?"];
  }, [targetJob]);

  return (
    <div className={`flex h-[calc(100vh-140px)] gap-6 mx-auto relative px-6 pb-6 transition-all duration-500 ease-out ${isZenMode ? 'w-full max-w-none' : 'max-w-none w-full'}`}>

        {/* WAR ROOM SIDEBAR */}
        {targetJob && !isZenMode && (
            <div className="w-[420px] shrink-0 flex flex-col gap-4 animate-in slide-in-from-left-12 duration-500">
                <div className="flex bg-apple-bg dark:bg-white/5 p-1 rounded-2xl w-full">
                    <button onClick={() => setActiveSidebarTab('strategy')} className={`flex-1 flex items-center justify-center py-2.5 rounded-xl transition-all ${activeSidebarTab === 'strategy' ? 'bg-white dark:bg-apple-card-dark shadow-sm' : 'opacity-40 hover:opacity-100'}`} title="Strategy"><Sparkles size={18} /></button>
                    <button onClick={() => setActiveSidebarTab('keywords')} className={`flex-1 flex items-center justify-center py-2.5 rounded-xl transition-all ${activeSidebarTab === 'keywords' ? 'bg-white dark:bg-apple-card-dark shadow-sm' : 'opacity-40 hover:opacity-100'}`} title="Keywords"><Layout size={18} /></button>
                    <button onClick={() => setActiveSidebarTab('snippets')} className={`flex-1 flex items-center justify-center py-2.5 rounded-xl transition-all ${activeSidebarTab === 'snippets' ? 'bg-white dark:bg-apple-card-dark shadow-sm' : 'opacity-40 hover:opacity-100'}`} title="Snippets"><Book size={18} /></button>
                    <button onClick={() => setActiveSidebarTab('interview')} className={`flex-1 flex items-center justify-center py-2.5 rounded-xl transition-all ${activeSidebarTab === 'interview' ? 'bg-white dark:bg-apple-card-dark shadow-sm' : 'opacity-40 hover:opacity-100'}`} title="Interview Prep"><MessageCircle size={18} /></button>
                </div>

                <div className="flex-1 overflow-hidden bg-white dark:bg-apple-card-dark rounded-[32px] border border-apple-border dark:border-apple-border-dark flex flex-col shadow-sm">
                    <div className="p-6 overflow-y-auto custom-scrollbar flex-1">

                        {activeSidebarTab === 'strategy' && (
                            <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
                                <h3 className="text-xl font-bold mb-4">Live Strategy</h3>
                                <div className="prose prose-sm dark:prose-invert text-[13px] leading-relaxed whitespace-pre-wrap opacity-80">
                                    {targetJob.analysis?.strategy || "Generating custom strategy..."}
                                </div>
                            </div>
                        )}

                        {activeSidebarTab === 'keywords' && (
                            <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
                                <div className="flex items-center justify-between mb-2">
                                    <h3 className="text-xl font-bold">Keyword Gap</h3>
                                    <span className="text-xs font-bold text-apple-blue">{foundKeywords.size}/{keywords.length} Found</span>
                                </div>
                                <div className="w-full h-1.5 bg-gray-100 dark:bg-white/5 rounded-full mb-6 overflow-hidden">
                                    <div className="h-full bg-apple-blue transition-all duration-1000" style={{ width: `${keywordProgress}%` }}></div>
                                </div>
                                <div className="space-y-2">
                                    {keywords.map(kw => {
                                        const isFound = foundKeywords.has(kw);
                                        return (
                                            <div key={kw} className={`group p-3.5 rounded-2xl border transition-all flex items-center justify-between ${isFound ? 'bg-emerald-50 dark:bg-emerald-900/10 border-emerald-500/10 text-emerald-700' : 'bg-apple-bg dark:bg-white/5 border-transparent opacity-50'}`}>
                                                <span className="text-sm font-semibold">{kw}</span>
                                                {isFound ? <CheckCircle2 size={16} /> : <Wand2 size={14} className="opacity-0 group-hover:opacity-40" />}
                                            </div>
                                        );
                                    })}
                                </div>
                                {keywordProgress === 100 && (
                                    <div className="mt-8 p-4 bg-emerald-500 text-white rounded-2xl text-center animate-bounce">
                                        <p className="text-sm font-bold">🎯 Optimized for ATS!</p>
                                    </div>
                                )}
                            </div>
                        )}

                        {activeSidebarTab === 'snippets' && (
                            <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
                                <h3 className="text-xl font-bold mb-4">Proven Wins</h3>
                                <p className="text-xs text-apple-gray mb-6">Click to insert tailored achievements from your profile.</p>
                                <div className="space-y-3">
                                    {USER_PROFILE.caseStudies.map((cs, i) => (
                                        <div key={i} onClick={() => insertSnippet(`${cs.title}: ${cs.description}`)} className="p-4 rounded-2xl bg-apple-bg dark:bg-white/5 hover:border-apple-blue border border-transparent cursor-pointer transition-all group">
                                            <p className="text-[10px] font-bold uppercase tracking-wider text-apple-blue mb-1">{cs.title}</p>
                                            <p className="text-sm leading-snug group-hover:text-apple-text">{cs.description}</p>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}

                        {activeSidebarTab === 'interview' && (
                            <div className="animate-in fade-in slide-in-from-bottom-2 duration-300 flex flex-col h-full">
                                <h3 className="text-xl font-bold mb-6">Prep Mode</h3>
                                <div className="flex-1 flex flex-col items-center justify-center p-4">
                                    <div className="w-full aspect-[4/3] bg-gradient-to-br from-apple-blue to-[#5856d6] rounded-3xl p-8 text-white flex flex-col shadow-2xl relative overflow-hidden group">
                                        <div className="absolute top-4 right-4 text-white/20 font-bold italic text-4xl select-none group-hover:scale-110 transition-transform">?</div>
                                        <HelpCircle className="opacity-40 mb-auto" size={24} />
                                        <p className="text-lg font-bold leading-tight text-center px-4 mb-4">
                                            {interviewQuestions[currentFlashcard]}
                                        </p>
                                        <div className="mt-auto flex justify-center gap-1.5">
                                            {interviewQuestions.map((_, i) => (
                                                <div key={i} className={`w-1.5 h-1.5 rounded-full transition-all ${currentFlashcard === i ? 'bg-white scale-125' : 'bg-white/20'}`}></div>
                                            ))}
                                        </div>
                                    </div>
                                    <button 
                                        onClick={() => setCurrentFlashcard((currentFlashcard + 1) % interviewQuestions.length)}
                                        className="mt-10 flex items-center gap-2 text-sm font-bold text-apple-blue hover:scale-105 active:scale-95 transition-all"
                                    >
                                        Next Question <ChevronRight size={18} />
                                    </button>
                                </div>
                            </div>
                        )}

                    </div>
                    <div className="p-4 bg-apple-bg dark:bg-white/5 border-t border-apple-border dark:border-white/5 flex items-center justify-between">
                        <div className="flex items-center gap-2">
                             <div className="w-8 h-8 rounded-full bg-apple-blue text-white flex items-center justify-center text-[10px] font-bold">VP</div>
                             <div className="text-[11px] font-bold">
                                <p className="text-apple-text dark:text-white">Vyom Pathroliya</p>
                                <p className="text-apple-gray uppercase tracking-widest text-[8px]">Design Production</p>
                             </div>
                        </div>
                    </div>
                </div>
            </div>
        )}

        {/* EDITOR AREA */}
        <div className="flex-1 flex flex-col bg-white dark:bg-apple-card-dark rounded-[32px] shadow-sm overflow-hidden border border-apple-border dark:border-apple-border-dark">
            <div className="h-16 border-b border-apple-border dark:border-white/5 flex items-center px-6 justify-between bg-white/80 dark:bg-apple-card-dark/80 backdrop-blur-xl z-20 sticky top-0">
                <div className="flex items-center gap-1">
                    {targetJob && (
                        <button onClick={() => setIsZenMode(!isZenMode)} className="p-2.5 hover:bg-apple-bg dark:hover:bg-white/5 rounded-xl text-apple-gray transition-all mr-2" title={isZenMode ? "Exit Zen Mode" : "Zen Mode"}>
                            {isZenMode ? <Minimize2 size={18} /> : <Maximize2 size={18} />}
                        </button>
                    )}
                    <button onClick={() => execCmd('undo')} className="p-2.5 hover:bg-apple-bg dark:hover:bg-white/5 rounded-xl text-apple-gray"><RotateCcw size={18} /></button>
                    <button onClick={() => execCmd('redo')} className="p-2.5 hover:bg-apple-bg dark:hover:bg-white/5 rounded-xl text-apple-gray"><RotateCw size={18} /></button>
                    <div className="w-px h-6 bg-apple-border dark:bg-white/10 mx-2"></div>
                    <button onClick={() => execCmd('bold')} className="p-2.5 hover:bg-apple-bg dark:hover:bg-white/5 rounded-xl text-apple-gray font-bold">B</button>
                    <button onClick={() => execCmd('italic')} className="p-2.5 hover:bg-apple-bg dark:hover:bg-white/5 rounded-xl text-apple-gray italic">I</button>
                    <button onClick={() => execCmd('insertUnorderedList')} className="p-2.5 hover:bg-apple-bg dark:hover:bg-white/5 rounded-xl text-apple-gray"><List size={18} /></button>
                    <div className="w-px h-6 bg-apple-border dark:bg-white/10 mx-2"></div>
                    <button onClick={() => execCmd('removeFormat')} className="p-2.5 hover:bg-red-50 dark:hover:bg-red-900/10 rounded-xl text-red-500"><Trash size={18} /></button>
                </div>
                <div className="flex items-center gap-3">
                    <button onClick={() => setShowDoc(!showDoc)} className={`h-10 px-5 rounded-full transition-all border flex items-center gap-2 text-[13px] font-semibold ${showDoc ? 'bg-apple-text text-white shadow-md' : 'text-apple-gray'}`}>
                        <BookOpen size={16} /> Reference
                    </button>
                    <div className="text-[11px] font-bold text-apple-gray bg-apple-bg dark:bg-white/5 px-4 py-2 rounded-full border border-apple-border dark:border-white/5">
                        {lastSaved}
                    </div>
                </div>
            </div>
            <div className="flex-1 overflow-y-auto bg-apple-bg dark:bg-black flex relative custom-scrollbar">
                {showDoc && (
                    <div className="w-1/2 h-full border-r border-apple-border dark:border-white/5 bg-white dark:bg-apple-card-dark hidden lg:block animate-in slide-in-from-left-4 duration-500 ease-out z-10">
                        <iframe src="https://docs.google.com/document/d/1RcERxf9--nMGdxXTHAt4q35yynk39Aqk31AqSuG02G4/preview" className="w-full h-full border-none" title="Reference CV"></iframe>
                    </div>
                )}
                <div className={`flex-1 flex justify-center p-8 transition-all duration-500 ${showDoc || targetJob ? 'bg-gray-100 dark:bg-[#121212]' : ''}`}>
                     <div ref={editorRef} contentEditable role="textbox" aria-multiline="true" className={`w-full h-max bg-white dark:bg-white shadow-2xl p-[72px] outline-none text-apple-text font-sans text-lg leading-[1.6] transition-all rounded-sm mb-24 ${isZenMode ? 'max-w-[1000px]' : (showDoc || targetJob ? 'max-w-full' : 'max-w-[850px]')}`}/>
                </div>
            </div>
        </div>
    </div>
  );
};

export default CVEditor;

import React, { useEffect, useState, useRef } from 'react';
import { X, ExternalLink, Briefcase, Zap, FileText, Sparkles, Edit2, Save, ChevronDown, RotateCw, TrendingUp, AlertTriangle, Loader2, Paperclip, Image as ImageIcon, Trash2, ChevronUp, Link as LinkIcon, Info } from 'lucide-react';
import { Job, Attachment } from '../types';

interface JobDetailModalProps {
  isOpen: boolean;
  onClose: () => void;
  job: Job | null;
  onGenerateKit: (job: Job) => void;
  initialTab?: 'brief' | 'strategy';
  onUpdateJob?: (job: Job) => void;
  onReAnalyze?: (job: Job) => Promise<void>;
  onTailorResume?: (id: string) => void;
}

const JobDetailModal: React.FC<JobDetailModalProps> = ({ isOpen, onClose, job, onGenerateKit, initialTab = 'brief', onUpdateJob, onReAnalyze, onTailorResume }) => {
  const [activeTab, setActiveTab] = useState<'brief' | 'strategy'>(initialTab);
  const [isGeneratingKit, setIsGeneratingKit] = useState(false);
  const [isEditingSummary, setIsEditingSummary] = useState(false);
  const [editedSummary, setEditedSummary] = useState('');
  const [isDescriptionExpanded, setIsDescriptionExpanded] = useState(false);
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [editedTitle, setEditedTitle] = useState('');
  const [isEditingCompany, setIsEditingCompany] = useState(false);
  const [editedCompany, setEditedCompany] = useState('');
  const [isEditingLocation, setIsEditingLocation] = useState(false);
  const [editedLocation, setEditedLocation] = useState('');
  const [isEditingPostedDate, setIsEditingPostedDate] = useState(false);
  const [editedPostedDate, setEditedPostedDate] = useState('');
  const [isEditingUrl, setIsEditingUrl] = useState(false);
  const [editedUrl, setEditedUrl] = useState('');
  const notesRef = useRef<HTMLDivElement>(null);
  const [isEditingNotes, setIsEditingNotes] = useState(false); 
  const fileInputRef = useRef<HTMLInputElement>(null);
  const lastJobIdRef = useRef<string>('');
  const [selectedImg, setSelectedImg] = useState<HTMLImageElement | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [showScoreReasoning, setShowScoreReasoning] = useState(false);

  useEffect(() => {
    setActiveTab(initialTab);
  }, [initialTab, isOpen, job]);

  useEffect(() => {
    if (job) {
        if (!isEditingSummary) setEditedSummary(job.summary || '');
        if (!isEditingTitle) setEditedTitle(job.title || '');
        if (!isEditingCompany) setEditedCompany(job.company || '');
        if (!isEditingLocation) setEditedLocation(job.location || '');
        if (!isEditingPostedDate) setEditedPostedDate(job.postedDate || '');
        if (!isEditingUrl) setEditedUrl(job.url === 'Manual Entry' ? '' : (job.url || ''));

        if (notesRef.current) {
            const isDifferentJob = lastJobIdRef.current !== job.id;
            if (isDifferentJob) {
                notesRef.current.innerHTML = job.notes || '';
                lastJobIdRef.current = job.id;
                setSelectedImg(null);
            } 
            else {
                const isActive = document.activeElement === notesRef.current;
                if (!isActive && job.notes !== notesRef.current.innerHTML) {
                    notesRef.current.innerHTML = job.notes || '';
                }
            }
        }
    }
  }, [job, isEditingSummary, isEditingTitle, isEditingCompany, isEditingLocation, isEditingPostedDate, isEditingUrl]);

  useEffect(() => {
      const timer = setTimeout(() => {
          if (isEditingSummary && onUpdateJob && job && editedSummary !== job.summary) {
              onUpdateJob({ ...job, summary: editedSummary });
          }
      }, 1000); 
      return () => clearTimeout(timer);
  }, [editedSummary, isEditingSummary, job, onUpdateJob]);

  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
      setIsDescriptionExpanded(false);
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => { document.body.style.overflow = 'unset'; };
  }, [isOpen]);

  if (!isOpen || !job) return null;

  const analysis = job.analysis;
  const attachments = job.attachments || [];

  const applyUrl = job.url && job.url !== 'Manual Entry' ? (job.url.startsWith('http') ? job.url : `https://${job.url}`) : `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;

  const handleSaveDescription = () => { if (onUpdateJob) { onUpdateJob({ ...job, summary: editedSummary }); setIsEditingSummary(false); } };
  const handleSaveTitle = () => { if (onUpdateJob && editedTitle.trim() !== job.title) onUpdateJob({ ...job, title: editedTitle }); setIsEditingTitle(false); };
  const handleSaveCompany = () => { if (onUpdateJob && editedCompany.trim() !== job.company) onUpdateJob({ ...job, company: editedCompany }); setIsEditingCompany(false); };
  const handleSaveLocation = () => { if (onUpdateJob && editedLocation.trim() !== job.location) onUpdateJob({ ...job, location: editedLocation }); setIsEditingLocation(false); };
  const handleSavePostedDate = () => { if (onUpdateJob && editedPostedDate.trim() !== job.postedDate) onUpdateJob({ ...job, postedDate: editedPostedDate }); setIsEditingPostedDate(false); };
  const handleSaveUrl = () => { if (onUpdateJob && editedUrl.trim() !== job.url) onUpdateJob({ ...job, url: editedUrl.trim() || 'Manual Entry' }); setIsEditingUrl(false); };
  const handleStatusChange = (e: React.ChangeEvent<HTMLSelectElement>) => { if (onUpdateJob) onUpdateJob({ ...job, status: e.target.value as Job['status'] }); };
  const handleReAnalyzeClick = async () => { if (onReAnalyze) { setIsAnalyzing(true); await onReAnalyze(job); setIsAnalyzing(false); } };
  const handleGenerateKitClick = async () => { setIsGeneratingKit(true); await onGenerateKit(job); setIsGeneratingKit(false); };
  const handleNotesUpdate = () => { if (notesRef.current && onUpdateJob) { const newNotes = notesRef.current.innerHTML; if (newNotes !== job.notes) onUpdateJob({ ...job, notes: newNotes }); } };
  const handleNotesBlur = () => { setIsEditingNotes(false); handleNotesUpdate(); };
  const handleNotesPaste = async (e: React.ClipboardEvent) => {
    const items = e.clipboardData.items;
    for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1) {
            e.preventDefault();
            const blob = items[i].getAsFile();
            if (blob) {
                const reader = new FileReader();
                reader.onload = (ev) => {
                    const imgHtml = `<img src="${ev.target?.result}" style="max-width: 100%; border-radius: 8px; margin: 10px 0;" />`;
                    document.execCommand('insertHTML', false, imgHtml);
                    handleNotesUpdate();
                };
                reader.readAsDataURL(blob);
            }
            return;
        }
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 sm:p-6">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-md" onClick={onClose}></div>
      <div className="relative bg-white dark:bg-apple-card-dark w-full max-w-5xl h-[90vh] flex flex-col shadow-2xl rounded-[32px] overflow-hidden animate-in zoom-in-95 duration-300 border border-transparent dark:border-white/10">

        <div className="flex items-start justify-between px-10 py-10 shrink-0">
           <div className="flex-1">
                {isEditingTitle ? (
                    <input value={editedTitle} onChange={(e) => setEditedTitle(e.target.value)} onBlur={handleSaveTitle} onKeyDown={(e) => e.key === 'Enter' && handleSaveTitle()} className="text-4xl font-bold tracking-tight text-apple-text dark:text-white w-full outline-none bg-transparent p-0 border-b-2 border-apple-blue" autoFocus />
                ) : (
                    <h2 onClick={() => setIsEditingTitle(true)} className="text-4xl font-bold tracking-tight text-apple-text dark:text-white leading-tight cursor-pointer hover:text-apple-blue transition-colors">{job.title}</h2>
                )}
                <div className="mt-2 flex items-center gap-3 text-xl text-apple-gray dark:text-gray-400 font-medium">
                    <span onClick={() => setIsEditingCompany(true)} className="hover:text-apple-blue cursor-pointer">{job.company}</span>
                    <span className="opacity-30">•</span>
                    <span>{job.location}</span>
                </div>
           </div>
           <button onClick={onClose} className="w-10 h-10 flex items-center justify-center bg-apple-bg dark:bg-white/5 hover:bg-apple-border dark:hover:bg-white/10 rounded-full transition-colors"><X size={20} /></button>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar px-10 pb-12">
            <div className="flex flex-col md:flex-row gap-16">
                <div className="flex-1 order-2 md:order-1 min-w-0">
                    <div className="flex items-center gap-1 mb-10 bg-apple-bg dark:bg-white/5 p-1 rounded-full w-fit">
                        <button onClick={() => setActiveTab('brief')} className={`px-8 py-2.5 rounded-full text-[13px] font-bold transition-all ${activeTab === 'brief' ? 'bg-white dark:bg-apple-card-dark text-apple-text dark:text-white shadow-sm' : 'text-apple-gray'}`}>Overview</button>
                        <button onClick={() => { setActiveTab('strategy'); if (!analysis?.strategy) handleGenerateKitClick(); }} className={`px-8 py-2.5 rounded-full text-[13px] font-bold transition-all ${activeTab === 'strategy' ? 'bg-white dark:bg-apple-card-dark text-apple-text dark:text-white shadow-sm' : 'text-apple-gray'}`}>Strategy Kit</button>
                    </div>

                    {activeTab === 'brief' ? (
                        <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                            <div className="mb-10 flex flex-wrap gap-2">
                                {analysis?.isHighValue && <span className="px-4 py-1.5 rounded-full text-[12px] font-bold bg-emerald-50 dark:bg-emerald-900/10 text-emerald-600">High Value Portfolio</span>}
                                {analysis?.industry && <span className="px-4 py-1.5 rounded-full text-[12px] font-bold bg-apple-blue/10 text-apple-blue">{analysis.industry} Industry</span>}
                                {job.seniorityScore && <span className="px-4 py-1.5 bg-apple-bg dark:bg-white/5 rounded-full text-[12px] font-bold">{job.seniorityScore} Match</span>}
                            </div>

                            {analysis ? (
                                <div className="mb-10">
                                    <h4 className="text-[11px] font-bold text-apple-gray dark:text-gray-500 uppercase tracking-[0.2em] mb-4">Strategic Verdict</h4>
                                    <p className="text-2xl text-apple-text dark:text-white font-semibold leading-relaxed tracking-tight">{analysis.verdict}</p>
                                </div>
                            ) : (
                                <div className="mb-10 p-8 bg-apple-blue/5 rounded-3xl border border-apple-blue/10 animate-pulse">
                                    <div className="flex items-center gap-3 mb-2"><Loader2 className="text-apple-blue animate-spin" size={20} /><span className="text-sm font-bold text-apple-blue">Running AI Simulation...</span></div>
                                </div>
                            )}

                            <div className="mb-12">
                                <div className="flex items-center justify-between mb-4">
                                    <h4 className="text-[11px] font-bold text-apple-gray dark:text-gray-500 uppercase tracking-[0.2em]">Briefing</h4>
                                    <button onClick={() => setIsEditingSummary(!isEditingSummary)} className="text-[11px] font-bold text-apple-blue uppercase tracking-wider">{isEditingSummary ? 'Save' : 'Edit'}</button>
                                </div>
                                {isEditingSummary ? (
                                    <textarea value={editedSummary} onChange={(e) => setEditedSummary(e.target.value)} className="w-full h-80 p-6 border-2 border-apple-blue rounded-3xl text-sm leading-relaxed outline-none dark:bg-apple-card-dark dark:text-white font-sans" autoFocus />
                                ) : (
                                    <div className="text-gray-600 dark:text-gray-400 text-base leading-[1.8] whitespace-pre-wrap">{job.summary}</div>
                                )}
                            </div>

                            <div className="mb-12">
                                <h4 className="text-[11px] font-bold text-apple-gray dark:text-gray-500 uppercase tracking-[0.2em] mb-4">Production Notes</h4>
                                <div className={`rounded-3xl border-2 transition-all bg-white dark:bg-white/5 ${isEditingNotes ? 'border-apple-blue ring-4 ring-apple-blue/5' : 'border-apple-border dark:border-white/5'}`}>
                                    <div ref={notesRef} contentEditable onFocus={() => setIsEditingNotes(true)} onBlur={handleNotesBlur} onInput={handleNotesUpdate} onPaste={handleNotesPaste} className="min-h-[200px] p-6 text-base outline-none prose dark:prose-invert max-w-none empty:before:content-[attr(data-placeholder)] empty:before:text-gray-300" data-placeholder="Capture thoughts, paste screenshots, or link documents..." />
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                             {isGeneratingKit ? (
                                <div className="space-y-8"><div className="h-10 w-64 bg-apple-bg dark:bg-white/5 rounded-xl animate-pulse" /><div className="h-64 w-full bg-apple-bg dark:bg-white/5 rounded-3xl animate-pulse" /></div>
                            ) : (
                                <div className="prose prose-lg dark:prose-invert prose-p:text-gray-600 dark:prose-p:text-gray-400 prose-headings:text-apple-text dark:prose-headings:text-white max-w-none">
                                    <div className="whitespace-pre-wrap leading-relaxed">{analysis?.strategy || "Strategy formulation failed."}</div>
                                </div>
                            )}
                        </div>
                    )}
                </div>

                <div className="w-full md:w-80 shrink-0 space-y-10 order-1 md:order-2">
                    <div className="p-8 bg-apple-bg dark:bg-white/5 rounded-[32px] space-y-8">
                        <div>
                            <label className="text-[10px] font-bold uppercase tracking-[0.2em] text-apple-gray mb-3 block">Application Status</label>
                            <select value={job.status || 'new'} onChange={handleStatusChange} className="w-full appearance-none px-5 py-4 bg-white dark:bg-apple-card-dark rounded-2xl font-bold text-sm text-apple-text dark:text-white focus:ring-4 focus:ring-apple-blue/5 cursor-pointer outline-none border border-apple-border dark:border-white/5">
                                <option value="saved">Saved</option>
                                <option value="applied">Applied</option>
                                <option value="interview">Interview</option>
                                <option value="offer">Offer</option>
                                <option value="archived">Archived</option>
                            </select>
                        </div>

                        <div>
                            <div className="flex items-center justify-between mb-3">
                                <span className="text-[10px] font-bold uppercase tracking-[0.2em] text-apple-gray">Match Precision</span>
                                <button onClick={handleReAnalyzeClick} className={`text-apple-blue hover:scale-110 transition-transform ${isAnalyzing ? 'animate-spin' : ''}`}><RotateCw size={14} /></button>
                            </div>
                            <div className="flex items-baseline gap-1">
                                <span className="text-6xl font-bold tracking-tighter text-apple-text dark:text-white">{analysis?.score || '--'}</span>
                                <span className="text-xl font-bold text-apple-gray">%</span>
                            </div>
                        </div>

                        <button onClick={() => onTailorResume?.(job.id)} className="w-full py-5 bg-apple-text dark:bg-white text-white dark:text-apple-text text-sm font-bold rounded-2xl hover:scale-[1.03] transition-all shadow-xl flex items-center justify-center gap-2">
                            <Sparkles size={18} /> War Room Entry
                        </button>
                    </div>

                    <div className="space-y-6 px-4">
                        <div className="flex flex-col gap-1">
                             <span className="text-[10px] font-bold uppercase tracking-[0.2em] text-apple-gray">Location Precision</span>
                             <p className="font-bold text-apple-text dark:text-white">{job.location}</p>
                        </div>
                        <div className="flex flex-col gap-1">
                             <span className="text-[10px] font-bold uppercase tracking-[0.2em] text-apple-gray">Posted Date</span>
                             <p className="font-bold text-apple-text dark:text-white">{job.postedDate || 'Recent'}</p>
                        </div>
                        <div className="pt-6 border-t border-apple-border dark:border-white/5">
                            <a href={applyUrl} target="_blank" rel="noreferrer" className="flex items-center justify-center gap-2 w-full py-4 bg-apple-blue text-white text-sm font-bold rounded-2xl hover:bg-apple-blue/90 shadow-xl shadow-apple-blue/20">
                                Official Source <ExternalLink size={16} />
                            </a>
                        </div>
                    </div>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

export default JobDetailModal;

export interface Attachment {
  id: string;
  name: string;
  type: string;
  data: string; // Base64 string
  size: number;
}

export interface Contact {
  name: string;
  role: string;
  connectionType: '1st' | '2nd' | 'Former Colleague' | 'Referral';
  linkedInUrl?: string;
}

export interface Job {
  id: string;
  title: string;
  company: string;
  location: string;
  url?: string;
  summary: string;
  source: string;
  status?: 'new' | 'saved' | 'applied' | 'assessment' | 'interview' | 'offer' | 'archived';
  notes?: string; // Can contain HTML
  attachments?: Attachment[];
  contacts?: Contact[]; // Suggestion 1: Referral Radar
  appliedDate?: string;
  postedDate?: string;
  scoutedAt?: number;
  seniorityScore?: 'Mid' | 'Senior' | 'Lead';
  isRelatedDiscovery?: boolean;
  analysis?: JobAnalysis;
  tailoredCv?: string;
}

export interface JobAnalysis {
  score: number;
  scoreReasoning: string;
  verdict: string;
  strategy: string;
  isHighValue: boolean;
  isCommuteRisk: boolean;
  matchedKeywords: string[];
  tone?: {
    jdTone: string; // e.g., "Formal", "Disruptive", "Institutional"
    keywordsFreq: Record<string, number>;
  };
  workPattern?: string;
  experienceRequired?: string;
  salary?: string;
  industry?: string;
}

export enum ViewState {
  DASHBOARD = 'DASHBOARD',
  KANBAN = 'KANBAN',
  CV_EDITOR = 'CV_EDITOR',
}

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Bold, Italic, Underline, RotateCcw, RotateCw, List, BookOpen, Trash, Sparkles, CheckCircle2, Copy, Book, MessageCircle, HelpCircle, ChevronRight, Wand2, Layout, Maximize2, Minimize2, BarChart3, Fingerprint } from 'lucide-react';
import { saveCV, getCV, saveJobCV } from '../services/firebase';
import { Job } from '../types';
import { USER_PROFILE } from '../constants';

interface CVEditorProps {
    targetJob?: Job | null;
}

const CVEditor: React.FC<CVEditorProps> = ({ targetJob }) => {
  const editorRef = useRef<HTMLDivElement>(null);
  const [lastSaved, setLastSaved] = useState<string>('');
  const [showDoc, setShowDoc] = useState(false);
  const [isZenMode, setIsZenMode] = useState(false);
  const [showATSStructure, setShowATSStructure] = useState(false);
  const [foundKeywords, setFoundKeywords] = useState<Set<string>>(new Set());
  const [activeSidebarTab, setActiveSidebarTab] = useState<'strategy' | 'keywords' | 'tone' | 'snippets' | 'interview'>('strategy');
  const [currentFlashcard, setCurrentFlashcard] = useState(0);

  const keywords = useMemo(() => targetJob?.analysis?.matchedKeywords || [], [targetJob]);

  const scanKeywords = useCallback(() => {
    if (!editorRef.current || keywords.length === 0) return;
    const text = editorRef.current.innerText.toLowerCase();
    const found = new Set<string>();
    keywords.forEach(kw => {
        if (text.toLowerCase().includes(kw.toLowerCase())) found.add(kw);
    });
    setFoundKeywords(found);
  }, [keywords]);

  useEffect(() => {
    const loadContent = async () => {
        let content = "";
        if (targetJob) {
            content = targetJob.tailoredCv || await getCV();
        } else {
            content = await getCV();
        }

        if (editorRef.current) {
            editorRef.current.innerHTML = content || `
                <h1 style="font-size: 2em; font-weight: bold; margin-bottom: 0.5em; color: #1d1d1f;">Senior UX Designer</h1>
                <p><strong>Summary</strong></p>
                <p>Strategic and human-centered Senior UX Designer with 7+ years of experience transforming complex financial and insurance problems into intuitive digital solutions.</p>
            `;
            setLastSaved(targetJob ? 'Job-Specific Workspace' : 'Main CV');
            scanKeywords();
        }
    };
    loadContent();
  }, [targetJob?.id, scanKeywords]);

  const saveContent = useCallback(async () => {
    if (!editorRef.current) return;
    const html = editorRef.current.innerHTML;
    if (targetJob) {
        await saveJobCV(targetJob.id, html);
    } else {
        await saveCV(html);
    }
    const now = new Date();
    setLastSaved(now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
    scanKeywords();
  }, [targetJob, scanKeywords]);

  useEffect(() => {
      const handleInput = () => {
          const timeoutId = setTimeout(() => saveContent(), 1000);
          return () => clearTimeout(timeoutId);
      };
      const el = editorRef.current;
      el?.addEventListener('input', handleInput);
      return () => el?.removeEventListener('input', handleInput);
  }, [saveContent]);

  const execCmd = (command: string, value: string | undefined = undefined) => {
    document.execCommand(command, false, value);
    if (editorRef.current) editorRef.current.focus();
    saveContent();
  };

  const insertSnippet = (content: string) => {
      if (editorRef.current) {
          editorRef.current.focus();
          document.execCommand('insertHTML', false, `<p>${content}</p>`);
          saveContent();
      }
  };

  const keywordProgress = keywords.length > 0 ? (foundKeywords.size / keywords.length) * 100 : 0;

  return (
    <div className={`flex h-[calc(100vh-140px)] gap-6 mx-auto relative px-6 pb-6 transition-all duration-500 ease-out ${isZenMode ? 'w-full max-w-none' : 'max-w-none w-full'}`}>

        {/* WAR ROOM SIDEBAR */}
        {targetJob && !isZenMode && (
            <div className="w-[420px] shrink-0 flex flex-col gap-4 animate-in slide-in-from-left-12 duration-500">
                <div className="flex bg-apple-bg dark:bg-white/5 p-1 rounded-2xl w-full">
                    <button onClick={() => setActiveSidebarTab('strategy')} className={`flex-1 flex items-center justify-center py-2.5 rounded-xl transition-all ${activeSidebarTab === 'strategy' ? 'bg-white dark:bg-apple-card-dark shadow-sm' : 'opacity-40 hover:opacity-100'}`} title="Strategy"><Sparkles size={18} /></button>
                    <button onClick={() => setActiveSidebarTab('keywords')} className={`flex-1 flex items-center justify-center py-2.5 rounded-xl transition-all ${activeSidebarTab === 'keywords' ? 'bg-white dark:bg-apple-card-dark shadow-sm' : 'opacity-40 hover:opacity-100'}`} title="Keywords"><Layout size={18} /></button>
                    <button onClick={() => setActiveSidebarTab('tone')} className={`flex-1 flex items-center justify-center py-2.5 rounded-xl transition-all ${activeSidebarTab === 'tone' ? 'bg-white dark:bg-apple-card-dark shadow-sm' : 'opacity-40 hover:opacity-100'}`} title="Tone Mirror"><Fingerprint size={18} /></button>
                    <button onClick={() => setActiveSidebarTab('snippets')} className={`flex-1 flex items-center justify-center py-2.5 rounded-xl transition-all ${activeSidebarTab === 'snippets' ? 'bg-white dark:bg-apple-card-dark shadow-sm' : 'opacity-40 hover:opacity-100'}`} title="Snippets"><Book size={18} /></button>
                    <button onClick={() => setActiveSidebarTab('interview')} className={`flex-1 flex items-center justify-center py-2.5 rounded-xl transition-all ${activeSidebarTab === 'interview' ? 'bg-white dark:bg-apple-card-dark shadow-sm' : 'opacity-40 hover:opacity-100'}`} title="Interview"><MessageCircle size={18} /></button>
                </div>

                <div className="flex-1 overflow-hidden bg-white dark:bg-apple-card-dark rounded-[32px] border border-apple-border dark:border-apple-border-dark flex flex-col shadow-sm">
                    <div className="p-6 overflow-y-auto custom-scrollbar flex-1">

                        {activeSidebarTab === 'strategy' && (
                            <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
                                <h3 className="text-xl font-bold mb-4">Live Strategy</h3>
                                <div className="prose prose-sm dark:prose-invert text-[13px] leading-relaxed whitespace-pre-wrap opacity-80">
                                    {targetJob.analysis?.strategy || "Generating custom strategy..."}
                                </div>
                            </div>
                        )}

                        {activeSidebarTab === 'tone' && (
                            <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
                                <h3 className="text-xl font-bold mb-2">Tone Mirror</h3>
                                <p className="text-xs text-apple-gray mb-6 leading-relaxed">Ensure your CV matches the company's communication style.</p>

                                <div className="space-y-6">
                                    <div>
                                        <div className="flex justify-between text-[11px] font-bold uppercase mb-2">
                                            <span>Institutional</span>
                                            <span className="text-apple-blue">Disruptive</span>
                                        </div>
                                        <div className="h-2 w-full bg-apple-bg dark:bg-white/5 rounded-full relative">
                                            <div className="absolute top-0 bottom-0 w-1 bg-apple-blue rounded-full shadow-lg transition-all duration-700" style={{ left: '65%' }}></div>
                                            <div className="absolute -top-1 w-3 h-4 bg-apple-text dark:bg-white rounded-sm opacity-20" style={{ left: '75%' }}></div>
                                        </div>
                                        <p className="text-[10px] mt-2 text-apple-gray">Goal: Match the JD's 75% Disruptive tone.</p>
                                    </div>

                                    <div className="p-4 rounded-2xl bg-apple-blue/5 border border-apple-blue/10">
                                        <h4 className="text-xs font-bold text-apple-blue mb-2 flex items-center gap-2"><Sparkles size={12}/> AI Content Suggestion</h4>
                                        <p className="text-[12px] leading-relaxed opacity-80 italic">"Try using more active verbs like 'Spearheaded' or 'Orchestrated' to match the leadership energy of this JD."</p>
                                    </div>
                                </div>
                            </div>
                        )}

                        {activeSidebarTab === 'keywords' && (
                            <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
                                <div className="flex items-center justify-between mb-2">
                                    <h3 className="text-xl font-bold">Keyword Gap</h3>
                                    <span className="text-xs font-bold text-apple-blue">{foundKeywords.size}/{keywords.length} Found</span>
                                </div>
                                <div className="w-full h-1.5 bg-gray-100 dark:bg-white/5 rounded-full mb-6 overflow-hidden">
                                    <div className="h-full bg-apple-blue transition-all duration-1000" style={{ width: `${keywordProgress}%` }}></div>
                                </div>
                                <div className="space-y-2">
                                    {keywords.map(kw => {
                                        const isFound = foundKeywords.has(kw);
                                        return (
                                            <div key={kw} className={`group p-3.5 rounded-2xl border transition-all flex items-center justify-between ${isFound ? 'bg-emerald-50 dark:bg-emerald-900/10 border-emerald-500/10 text-emerald-700' : 'bg-apple-bg dark:bg-white/5 border-transparent opacity-50'}`}>
                                                <span className="text-sm font-semibold">{kw}</span>
                                                {isFound ? <CheckCircle2 size={16} /> : <Wand2 size={14} className="opacity-0 group-hover:opacity-40" />}
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>
                        )}

                        {activeSidebarTab === 'snippets' && (
                            <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
                                <h3 className="text-xl font-bold mb-4">Proven Wins</h3>
                                <div className="space-y-3">
                                    {USER_PROFILE.caseStudies.map((cs, i) => (
                                        <div key={i} onClick={() => insertSnippet(`${cs.title}: ${cs.description}`)} className="p-4 rounded-2xl bg-apple-bg dark:bg-white/5 hover:border-apple-blue border border-transparent cursor-pointer transition-all group">
                                            <p className="text-[10px] font-bold uppercase tracking-wider text-apple-blue mb-1">{cs.title}</p>
                                            <p className="text-sm leading-snug group-hover:text-apple-text">{cs.description}</p>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            </div>
