const MatchGauge = ({ score }: { score: number }) => {
  const radius = 18;
  const circumference = 2 * Math.PI * radius;
  const offset = circumference - (score / 100) * circumference;

  const getColor = (s: number) => {
    if (s >= 85) return '#34C759';
    if (s >= 70) return '#0071e3';
    if (s >= 50) return '#FF9500';
    return '#8E8E93';
  };

  return (
    <div className="relative w-12 h-12 flex items-center justify-center">
      <svg className="w-full h-full transform -rotate-90">
        <circle cx="24" cy="24" r={radius} stroke="currentColor" strokeWidth="2.5" fill="transparent" className="text-gray-100 dark:text-white/5" />
        <circle cx="24" cy="24" r={radius} stroke={getColor(score)} strokeWidth="2.5" fill="transparent" strokeDasharray={circumference} strokeDashoffset={offset} strokeLinecap="round" className="transition-all duration-1000 ease-out" />
      </svg>
      <span className="absolute text-[10px] font-bold dark:text-white">{score}%</span>
    </div>
  );
};

