import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { Job, JobAnalysis } from "../types";
import { SYSTEM_INSTRUCTION } from "../constants";

const getClient = () => {
    const apiKey = process.env.API_KEY;
    if (!apiKey) throw new Error("API Key not found.");
    return new GoogleGenAI({ apiKey });
};

const retryWithBackoff = async <T>(fn: () => Promise<T>, retries = 5, baseDelay = 5000): Promise<T> => {
  try {
    return await fn();
  } catch (error: any) {
    const statusCode = error.status || error.response?.status || error.error?.code;
    const isRateLimit = statusCode === 429 || statusCode === 503;
    if (retries > 0 && isRateLimit) {
      const delay = baseDelay * Math.pow(2, 5 - retries);
      await new Promise(resolve => setTimeout(resolve, delay));
      return retryWithBackoff(fn, retries - 1, baseDelay);
    }
    throw error;
  }
};

const cleanJsonOutput = (text: string) => {
    if (!text) return "{}";
    const jsonMatch = text.match(/```json\n([\s\S]*?)\n```/) || text.match(/```([\s\S]*?)```/);
    return jsonMatch ? jsonMatch[1] : text.replace(/```json/g, '').replace(/```/g, '').trim();
};

export const searchAndParseJobs = async (role: string, location: string): Promise<Job[]> => {
  const ai = getClient();
  const query = `("${role}") "${location}" -Intern -Trainee -Apprentice`;
  const prompt = `
    ### SEARCH STRATEGY
    Find 8-10 high-quality Senior Design roles.
    ### OUTPUT FORMAT
    Return JSON array: [{"job_title": "String", "company": "String", "seniority_score": "Mid|Senior|Lead", "source_url": "URL", "summary": "String", "posted_date": "String", "location": "String"}]
  `;
  const response = await retryWithBackoff<GenerateContentResponse>(() => ai.models.generateContent({ 
    model: "gemini-3-flash-preview", 
    contents: prompt, 
    config: { tools: [{ googleSearch: {} }] } 
  }));

  let rawJobs = [];
  try {
    rawJobs = JSON.parse(cleanJsonOutput(response.text || "[]"));
  } catch(e) { rawJobs = []; }
  return rawJobs.map((j: any) => ({
    id: `job-${Date.now()}-${Math.random()}`,
    title: j.job_title || "Unknown", company: j.company || "Unknown",
    location: j.location || "UK", url: j.source_url, summary: j.summary || "",
    source: "Web", postedDate: j.posted_date, seniorityScore: j.seniority_score,
    scoutedAt: Date.now()
  }));
};

export const analyzeJob = async (job: Job): Promise<JobAnalysis> => {
  const ai = getClient();
  const safeSummary = (job.summary || "").substring(0, 5000);
  const prompt = `
    Analyze this job for a Senior UX Designer.
    Job: ${job.title} at ${job.company}. 
    Summary: ${safeSummary}

    In addition to basic analysis, analyze the BRAND TONE (Voice).
    Is it Institutional, Disruptive, Corporate, or Creative?

    Return valid JSON matching JobAnalysis interface.
  `;

  const response = await retryWithBackoff<GenerateContentResponse>(() => ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: prompt,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          score: { type: Type.NUMBER },
          scoreReasoning: { type: Type.STRING },
          verdict: { type: Type.STRING },
          strategy: { type: Type.STRING },
          isHighValue: { type: Type.BOOLEAN },
          isCommuteRisk: { type: Type.BOOLEAN },
          tone: {
            type: Type.OBJECT,
            properties: {
              jdTone: { type: Type.STRING }
            },
            required: ["jdTone"]
          },
          matchedKeywords: { type: Type.ARRAY, items: { type: Type.STRING } },
          industry: { type: Type.STRING }
        }
      }
    }
  }));

  try {
    return JSON.parse(cleanJsonOutput(response.text || "{}"));
  } catch (e) {
    return { score: 0, scoreReasoning: "Failed", verdict: "Failed", strategy: "", isHighValue: false, isCommuteRisk: false, matchedKeywords: [] };
  }
};

export const generateApplicationKit = async (job: Job, analysis: JobAnalysis): Promise<string> => {
  const ai = getClient();
  const prompt = `Create a deep "Application Strategy Kit" for: ${job.title} at ${job.company}. Tone: ${analysis.tone?.jdTone}. Include Mindset, Trojan Horse, and Interview Prep.`;
  const response = await retryWithBackoff<GenerateContentResponse>(() => ai.models.generateContent({ 
    model: "gemini-3-pro-preview", 
    contents: prompt, 
    config: { systemInstruction: SYSTEM_INSTRUCTION } 
  }));
  return response.text || "";
};

