import React from 'react';
import { Job } from '../types';
import { Briefcase, MapPin, ExternalLink, Trash2, Bookmark, Archive, Zap, ArrowRight, TrendingUp, CheckCircle2, Users, Clock, Flame } from 'lucide-react';

interface JobCardProps {
  job: Job;
  onOpenDetail: (job: Job, tab?: 'brief' | 'strategy' | 'network') => void;
  onToggleStatus: (id: string, currentStatus: Job['status']) => void;
  onDelete: (id: string) => void;
  isKanban?: boolean;
  isSelected?: boolean;
  onSelect?: (id: string) => void;
  isSelectMode?: boolean;
}

const MatchGauge = ({ score }: { score: number }) => {
  const radius = 18;
  const circumference = 2 * Math.PI * radius;
  const offset = circumference - (score / 100) * circumference;

  const getColor = (s: number) => {
    if (s >= 85) return '#34C759';
    if (s >= 70) return '#0071e3';
    if (s >= 50) return '#FF9500';
    return '#8E8E93';
  };

  return (
    <div className="relative w-12 h-12 flex items-center justify-center">
      <svg className="w-full h-full transform -rotate-90">
        <circle cx="24" cy="24" r={radius} stroke="currentColor" strokeWidth="2.5" fill="transparent" className="text-gray-100 dark:text-white/5" />
        <circle cx="24" cy="24" r={radius} stroke={getColor(score)} strokeWidth="2.5" fill="transparent" strokeDasharray={circumference} strokeDashoffset={offset} strokeLinecap="round" className="transition-all duration-1000 ease-out" />
      </svg>
      <span className="absolute text-[10px] font-bold dark:text-white">{score}%</span>
    </div>
  );
};

// Follow-up Cooldown Component
const FollowUpTimer = ({ appliedDate }: { appliedDate?: string }) => {
    if (!appliedDate) return null;
    const applied = new Date(appliedDate);
    const now = new Date();
    const diffTime = Math.abs(now.getTime() - applied.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)); 
    const followUpDay = 7;
    const remaining = followUpDay - diffDays;

    if (remaining <= 0) return <span className="text-[10px] font-bold text-red-500 flex items-center gap-1"><Flame size={10} /> Follow Up Now</span>;
    return <span className="text-[10px] font-bold text-apple-gray flex items-center gap-1"><Clock size={10} /> {remaining}d to follow-up</span>;
};

const JobCard: React.FC<JobCardProps> = ({ job, onOpenDetail, onToggleStatus, onDelete, isKanban, isSelected, onSelect, isSelectMode }) => {
  const analysis = job.analysis;
  const status = job.status || 'new';
  const isSavedOrBetter = ['saved', 'applied', 'assessment', 'interview', 'offer'].includes(status);
  const referralCount = job.contacts?.length || 0;

  // Visual Dominance Logic: High scores take up more space in Dashboard grid
  const isHighValue = (analysis?.score || 0) >= 85;
  const gridSpanClass = !isKanban && isHighValue ? 'md:col-span-2 bg-gradient-to-br from-white to-blue-50/30 dark:from-[#1C1C1E] dark:to-blue-900/10 border-blue-200 dark:border-blue-900/30' : 'bg-white dark:bg-[#1C1C1E]';

  if (isKanban) {
      return (
        <div className="bg-white dark:bg-[#1C1C1E] rounded-xl p-4 cursor-pointer shadow-sm hover:shadow-md transition-all flex flex-col gap-2 border border-transparent hover:border-apple-blue/30 dark:border-white/5" onClick={() => onOpenDetail(job)}>
            <div className="flex justify-between items-start">
                <h4 className="font-bold text-[14px] text-apple-text dark:text-white leading-snug line-clamp-2">{job.title}</h4>
            </div>
            <p className="text-[12px] text-apple-gray dark:text-gray-400 font-medium truncate">{job.company}</p>
            <div className="flex items-center justify-between mt-1">
                 <div className="flex items-center gap-2">
                     <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: job.seniorityScore === 'Senior' || job.seniorityScore === 'Lead' ? '#34C759' : '#FFCC00' }}></div>
                     {status === 'applied' && <FollowUpTimer appliedDate={job.appliedDate} />}
                 </div>
                 <span className="text-[11px] font-bold opacity-60">{analysis?.score || '--'}%</span>
            </div>
        </div>
      );
  }

  return (
    <div 
        onClick={() => isSelectMode ? onSelect?.(job.id) : onOpenDetail(job)} 
        className={`apple-card p-8 group cursor-pointer border relative transition-all duration-300 ${isSelected ? 'ring-2 ring-apple-blue border-apple-blue scale-[1.01]' : 'border-transparent'} ${status === 'archived' ? 'opacity-50 grayscale' : ''} ${gridSpanClass}`}
    >
      <div className="absolute top-6 right-6 flex flex-col gap-2 z-10">
         {!isSelectMode && (
             <div className="opacity-0 group-hover:opacity-100 flex flex-col gap-2 transition-opacity">
                {status !== 'archived' && (
                    <button onClick={(e) => { e.stopPropagation(); onToggleStatus(job.id, status); }} className={`w-10 h-10 flex items-center justify-center rounded-full transition-all shadow-sm ${isSavedOrBetter ? 'bg-apple-blue text-white' : 'bg-white dark:bg-apple-card-dark border border-apple-border dark:border-apple-border-dark text-apple-gray'}`}>
                        <Bookmark size={18} fill={isSavedOrBetter ? "currentColor" : "none"} />
                    </button>
                )}
                <button onClick={(e) => { e.stopPropagation(); onDelete(job.id); }} className="w-10 h-10 flex items-center justify-center rounded-full bg-white dark:bg-apple-card-dark border border-apple-border dark:border-apple-border-dark hover:bg-red-500 hover:text-white text-apple-gray transition-all shadow-sm"><Archive size={18} /></button>
             </div>
         )}
      </div>

      <div className="flex flex-col sm:flex-row gap-8 items-start h-full">
          <div className="shrink-0 pt-1 hidden sm:block">
            {analysis?.score ? <MatchGauge score={analysis.score} /> : <div className="w-12 h-12 rounded-full border-2 border-dashed border-apple-border dark:border-apple-border-dark flex items-center justify-center text-[10px] text-apple-gray font-bold">NEW</div>}
          </div>

          <div className="flex-1 pr-8 flex flex-col h-full">
             <div className="mb-2 flex flex-wrap items-center gap-2">
                 <h3 className={`font-semibold tracking-tight group-hover:text-apple-blue transition-colors ${isHighValue ? 'text-2xl md:text-3xl' : 'text-2xl'}`}>{job.title}</h3>
                 {referralCount > 0 && <span className="bg-apple-blue/10 text-apple-blue text-[9px] font-bold px-2 py-0.5 rounded-sm flex items-center gap-1"><Users size={10}/> {referralCount} CONTACTS</span>}
                 {analysis?.isHighValue && <span className="bg-[#E6F4EA] text-[#137333] text-[9px] font-bold px-2 py-0.5 rounded-sm flex items-center gap-0.5"><Zap size={10} fill="currentColor"/> HIGH VALUE</span>}
             </div>

             <div className="flex items-center gap-3 text-sm font-medium text-apple-gray dark:text-gray-400 mb-4">
                <span className="flex items-center gap-1.5"><Briefcase size={14}/> {job.company}</span>
                <span className="text-apple-border dark:text-white/10">•</span>
                <span className="flex items-center gap-1.5"><MapPin size={14}/> {job.location}</span>
                {status === 'applied' && (
                    <>
                        <span className="text-apple-border dark:text-white/10">•</span>
                        <FollowUpTimer appliedDate={job.appliedDate} />
                    </>
                )}
             </div>

             <p className={`text-gray-600 dark:text-gray-400 line-clamp-2 mb-6 ${isHighValue ? 'text-base' : 'text-sm'}`}>{analysis?.verdict || job.summary}</p>

             <div className="mt-auto">
                 {!isSelectMode && (
                    <div className="flex items-center gap-4">
                        <button onClick={(e) => { e.stopPropagation(); onOpenDetail(job, 'strategy'); }} className="flex items-center gap-1.5 text-sm font-bold text-apple-blue hover:underline">Apply Strategy <ArrowRight size={16} /></button>
                        {referralCount > 0 && <button onClick={(e) => { e.stopPropagation(); onOpenDetail(job, 'network'); }} className="text-[13px] font-bold text-emerald-600 hover:underline">Review Referrals</button>}
                    </div>
                 )}
             </div>
          </div>
      </div>
    </div>
  );
};

export default JobCard;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Job, ViewState } from './types';
import { searchAndParseJobs, analyzeJob, generateApplicationKit, enrichJob } from './services/geminiService';
import { initFirebase, subscribeToJobs, addOrUpdateJob, updateJobStatus, deleteJob, saveAnalysis, addManualJob } from './services/firebase';
import { DEFAULT_FIREBASE_CONFIG } from './constants';
import JobCard from './components/JobCard';
import StatsPanel from './components/StatsPanel';
import KanbanBoard from './components/KanbanBoard';
import CVEditor from './components/CVEditor';
import JobDetailModal from './components/JobDetailModal';
import AddLinkModal from './components/AddLinkModal';
import { Layers, Moon, Sun, LogOut, Settings, X, Archive, Trash2, Plus, Search, ArrowDownUp, Sparkles, Radar, Crosshair, Terminal } from 'lucide-react';

const App: React.FC = () => {
  // Navigation & Data
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.DASHBOARD);
  const [activeTab, setActiveTab] = useState<'new' | 'saved' | 'archived'>('new');
  const [allJobs, setAllJobs] = useState<Job[]>([]);
  const [targetJobId, setTargetJobId] = useState<string | null>(null);

  // Search Configuration
  const [searchRole, setSearchRole] = useState('Senior UX Designer');
  const [searchLocation, setSearchLocation] = useState('United Kingdom');
  const [isSearchSettingsOpen, setIsSearchSettingsOpen] = useState(false);
  const searchSettingsRef = useRef<HTMLDivElement>(null);

  // THE SCOUTING DRONE (Game Design)
  // Replaces simple loading state with immersive telemetry
  const [scoutState, setScoutState] = useState<'idle' | 'initializing' | 'scanning' | 'analyzing' | 'complete'>('idle');
  const [telemetryLogs, setTelemetryLogs] = useState<string[]>([]);

  // Multi-Select
  const [isSelectMode, setIsSelectMode] = useState(false);
  const [selectedJobIds, setSelectedJobIds] = useState<Set<string>>(new Set());

  // Theme State
  const [darkMode, setDarkMode] = useState(() => {
    if (typeof window !== 'undefined') {
        return localStorage.getItem('theme') === 'dark' || 
               (!localStorage.getItem('theme') && window.matchMedia('(prefers-color-scheme: dark)').matches);
    }
    return false;
  });

  // Profile Menu State
  const [isProfileMenuOpen, setIsProfileMenuOpen] = useState(false);
  const profileMenuRef = useRef<HTMLDivElement>(null);

  // Auto-Init Firebase
  const [isDbConnected] = useState(() => initFirebase(DEFAULT_FIREBASE_CONFIG));

  // Filter & Sort
  const [cityFilter, setCityFilter] = useState<string>('All');
  const [industryFilter, setIndustryFilter] = useState<string | null>(null);
  const [sortBy, setSortBy] = useState<'date' | 'score'>('date');

  // Status
  const [analyzingCount, setAnalyzingCount] = useState(0);

  // Modal
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedJob, setSelectedJob] = useState<Job | null>(null);
  const [initialModalTab, setInitialModalTab] = useState<'brief' | 'strategy'>('brief');
  const [isAddLinkOpen, setIsAddLinkOpen] = useState(false);

  // Theme Effect
  useEffect(() => {
      if (darkMode) {
          document.documentElement.classList.add('dark');
          localStorage.setItem('theme', 'dark');
      } else {
          document.documentElement.classList.remove('dark');
          localStorage.setItem('theme', 'light');
      }
  }, [darkMode]);

  // Click Outside Profile/Search Menu
  useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
          if (profileMenuRef.current && !profileMenuRef.current.contains(event.target as Node)) {
              setIsProfileMenuOpen(false);
          }
          if (searchSettingsRef.current && !searchSettingsRef.current.contains(event.target as Node)) {
              setIsSearchSettingsOpen(false);
          }
      };
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (isDbConnected) {
      const unsubscribe = subscribeToJobs((jobs) => {
        setAllJobs(jobs);
      });
      return () => unsubscribe();
    }
  }, [isDbConnected]);

  const addTelemetry = (log: string) => {
      setTelemetryLogs(prev => [...prev.slice(-5), `> ${log}`]);
  };

  const fetchJobs = async () => {
    if (!isDbConnected) return;

    // Start Scouting Drone Sequence
    setScoutState('initializing');
    setTelemetryLogs([]);
    addTelemetry(`System Initialized. User: Vyom Pathroliya`);
    await new Promise(r => setTimeout(r, 600));

    addTelemetry(`Target Protocol: ${searchRole}`);
    addTelemetry(`Geo-Fence: ${searchLocation}`);
    setScoutState('scanning');

    try {
      addTelemetry(`Deploying search agents...`);
      const foundJobs = await searchAndParseJobs(searchRole, searchLocation);
      addTelemetry(`Telemetry returned ${foundJobs.length} vectors.`);

      const jobsToAnalyze: Job[] = [];
      for (const job of foundJobs) {
        const docId = `${job.title}_${job.company}`.toLowerCase().replace(/[^a-z0-9]/g, '_').substring(0, 100);
        const existing = allJobs.find(j => j.id === docId);
        const jobWithTimestamp = { ...job, scoutedAt: Date.now() };
        await addOrUpdateJob(jobWithTimestamp);
        if (!existing || !existing.analysis) {
           jobsToAnalyze.push({ ...jobWithTimestamp, id: docId });
        }
      }

      if (jobsToAnalyze.length > 0) {
          setScoutState('analyzing');
          addTelemetry(`Initiating Deep Scan on ${jobsToAnalyze.length} targets...`);
          await analyzeNewJobs(jobsToAnalyze);
      } else {
          addTelemetry(`No new un-analyzed targets.`);
      }

      addTelemetry(`Mission Complete.`);
      await new Promise(r => setTimeout(r, 800));
      setScoutState('idle');

    } catch (error) { 
        console.error(error); 
        addTelemetry(`ERR: Signal Lost.`);
        setTimeout(() => setScoutState('idle'), 2000);
    }
  };

  const analyzeNewJobs = async (jobs: Job[]) => {
      setAnalyzingCount(prev => prev + jobs.length);
      for (const job of jobs) {
        try {
            addTelemetry(`Analyzing fit: ${job.company}...`);
            const analysis = await analyzeJob(job);
            await saveAnalysis(job.id, analysis);
        } catch (e) {
            console.error(`Analysis failed for job ${job.id}`, e);
        } finally {
            setAnalyzingCount(prev => Math.max(0, prev - 1));
            // Artificial delay to make the telemetry readable (Game Design)
            await new Promise(resolve => setTimeout(resolve, 600)); 
        }
      }
      setAnalyzingCount(0);
  };

  const handleOpenDetail = (job: Job, tab: 'brief' | 'strategy' = 'brief') => {
    setSelectedJob(job);
    setInitialModalTab(tab);
    setModalOpen(true);
  };

  const handleUpdateJob = async (updatedJob: Job) => {
      await addOrUpdateJob(updatedJob);
      if (selectedJob && selectedJob.id === updatedJob.id) {
          setSelectedJob(updatedJob);
      }
  };

  const handleReAnalyzeJob = async (job: Job) => {
      try {
          const analysis = await analyzeJob(job);
          await saveAnalysis(job.id, analysis);
          const updatedJob = { ...job, analysis };
          setSelectedJob(updatedJob);
          setAllJobs(prev => prev.map(j => j.id === job.id ? updatedJob : j));
      } catch (e) {
          console.error("Re-analysis failed", e);
      }
  };

  const handleGenerateKit = async (job: Job) => {
    if (!job.analysis) return;
    const content = await generateApplicationKit(job, job.analysis);
    const updatedAnalysis = { ...job.analysis, strategy: content };
    await saveAnalysis(job.id, updatedAnalysis);
  };

  const toggleJobStatus = (jobId: string, currentStatus: Job['status']) => {
    let newStatus: Job['status'] = 'saved';
    if (currentStatus === 'new') newStatus = 'saved';
    else if (currentStatus === 'saved') newStatus = 'new'; 
    else if (currentStatus === 'archived') newStatus = 'new';
    updateJobStatus(jobId, newStatus!);
  };

  const handleDelete = (jobId: string) => {
    const job = allJobs.find(j => j.id === jobId);
    if (!job) return;
    if (job.status === 'archived') {
        if(confirm("Permanently delete?")) deleteJob(jobId);
    } else {
        updateJobStatus(jobId, 'archived');
    }
  };

  const handleBulkArchive = async () => {
      for (const id of selectedJobIds) {
          await updateJobStatus(id, 'archived');
      }
      setSelectedJobIds(new Set());
      setIsSelectMode(false);
  };

  const handleBulkDelete = async () => {
      if (!confirm(`Delete ${selectedJobIds.size} jobs permanently?`)) return;
      for (const id of selectedJobIds) {
          await deleteJob(id);
      }
      setSelectedJobIds(new Set());
      setIsSelectMode(false);
  };

  const toggleJobSelection = (id: string) => {
      const next = new Set(selectedJobIds);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      setSelectedJobIds(next);
  };

  const handleAddManualJob = async (data: { url?: string, text?: string, title?: string, company?: string }) => {
      try {
          if (currentView !== ViewState.DASHBOARD && currentView !== ViewState.KANBAN) {
              setCurrentView(ViewState.DASHBOARD);
              setActiveTab('saved');
          }
          const placeholder = await addManualJob(data);
          if (!placeholder) return;
          setSelectedJob(placeholder);
          setModalOpen(true);
          setInitialModalTab('brief');
          setAnalyzingCount(prev => prev + 1);
          const enrichedDetails = await enrichJob(data);
          const enrichedJob = { ...placeholder, ...enrichedDetails };
          await addOrUpdateJob(enrichedJob);
          setSelectedJob(prev => (prev && prev.id === placeholder.id ? enrichedJob : prev));
          const analysis = await analyzeJob(enrichedJob);
          await saveAnalysis(enrichedJob.id, analysis);
          const analyzedJob = { ...enrichedJob, analysis };
          setSelectedJob(prev => (prev && prev.id === placeholder.id ? analyzedJob : prev));
      } catch (e) {
          console.error("Error adding manual job", e);
      } finally {
          setAnalyzingCount(prev => Math.max(0, prev - 1));
      }
  };

  const handleTailorResume = (jobId: string) => {
    setTargetJobId(jobId);
    setModalOpen(false);
    setCurrentView(ViewState.CV_EDITOR);
  };

  const jobsInCurrentTab = useMemo(() => {
    return allJobs.filter(j => {
        const status = j.status || 'new';
        if (activeTab === 'new') return status === 'new';
        if (activeTab === 'saved') return ['saved', 'applied', 'assessment', 'interview', 'offer'].includes(status);
        if (activeTab === 'archived') return status === 'archived';
        return false;
    });
  }, [allJobs, activeTab]);

  const filteredJobs = useMemo(() => {
      return jobsInCurrentTab.filter(j => {
        const locMatch = cityFilter === 'All' ? true : (cityFilter === 'Other' ? !['edinburgh', 'glasgow', 'remote', 'london', 'manchester'].some(s => j.location.toLowerCase().includes(s)) : j.location.toLowerCase().includes(cityFilter.toLowerCase()));
        if (!locMatch) return false;
        if (industryFilter) {
            const ind = j.analysis?.industry || 'Tech';
            if (ind !== industryFilter) return false;
        }
        return true;
      }).sort((a, b) => {
          if (sortBy === 'score') return (b.analysis?.score || 0) - (a.analysis?.score || 0);
          return (b.scoutedAt || 0) - (a.scoutedAt || 0);
      });
  }, [jobsInCurrentTab, cityFilter, industryFilter, sortBy]);

  const filterOptions = ['All', 'Edinburgh', 'Glasgow', 'Remote', 'London', 'Manchester', 'Other'];

  const targetJobForEditor = useMemo(() => {
      if (!targetJobId) return null;
      return allJobs.find(j => j.id === targetJobId) || null;
