export default App;

import React from 'react';
import { Job } from '../types';
import { Briefcase, MapPin, Trash2, Bookmark, Archive, Zap, ArrowRight, CheckCircle2, Users, Clock, Flame } from 'lucide-react';

interface JobCardProps {
  job: Job;
  onOpenDetail: (job: Job, tab?: 'brief' | 'strategy') => void;
  onToggleStatus: (id: string, currentStatus: Job['status']) => void;
  onDelete: (id: string) => void;
  isKanban?: boolean;
  isSelected?: boolean;
  onSelect?: (id: string) => void;
  isSelectMode?: boolean;
}

const MatchGauge = ({ score }: { score: number }) => {
  const radius = 18;
  const circumference = 2 * Math.PI * radius;
  const offset = circumference - (score / 100) * circumference;

  const getColor = (s: number) => {
    if (s >= 85) return '#34C759'; // Emerald
    if (s >= 70) return '#0071e3'; // Apple Blue
    if (s >= 50) return '#FF9500'; // Orange
    return '#8E8E93'; // Gray
  };

  return (
    <div className="relative w-12 h-12 flex items-center justify-center">
      <svg className="w-full h-full transform -rotate-90">
        <circle cx="24" cy="24" r={radius} stroke="currentColor" strokeWidth="3" fill="transparent" className="text-gray-100 dark:text-white/5" />
        <circle cx="24" cy="24" r={radius} stroke={getColor(score)} strokeWidth="3" fill="transparent" strokeDasharray={circumference} strokeDashoffset={offset} strokeLinecap="round" className="transition-all duration-1000 ease-out" />
      </svg>
      <span className="absolute text-[10px] font-bold dark:text-white">{score}%</span>
    </div>
  );
};

// FOLLOW-UP COOLDOWN (Game Design)
// Visual countdown to gamify the boring waiting period
const FollowUpTimer = ({ appliedDate }: { appliedDate?: string }) => {
    if (!appliedDate) return null;
    const applied = new Date(appliedDate);
    const now = new Date();
    const diffTime = Math.abs(now.getTime() - applied.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)); 
    const followUpDay = 7;
    const remaining = followUpDay - diffDays;

    if (remaining <= 0) return <span className="text-[10px] font-bold text-red-500 flex items-center gap-1 animate-pulse"><Flame size={12} /> ACTION REQUIRED</span>;
    return <span className="text-[10px] font-bold text-apple-gray flex items-center gap-1"><Clock size={10} /> {remaining}d to follow-up</span>;
};

const JobCard: React.FC<JobCardProps> = ({ job, onOpenDetail, onToggleStatus, onDelete, isKanban, isSelected, onSelect, isSelectMode }) => {
  const analysis = job.analysis;
  const status = job.status || 'new';
  const isSavedOrBetter = ['saved', 'applied', 'assessment', 'interview', 'offer'].includes(status);

  // VISUAL DOMINANCE (Museum Architect)
  // High scores take up more physical space in the dashboard grid to draw the eye
  const isHighValue = (analysis?.score || 0) >= 85;
  const gridSpanClass = !isKanban && isHighValue ? 'md:col-span-2 bg-gradient-to-br from-white to-blue-50/50 dark:from-[#1C1C1E] dark:to-blue-900/10 border-blue-200 dark:border-blue-900/30' : 'bg-white dark:bg-[#1C1C1E]';

  const applyUrl = job.url && job.url !== 'Manual Entry' ? (job.url.startsWith('http') ? job.url : `https://${job.url}`) : `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;

  if (isKanban) {
      return (
        <div 
            className="bg-white dark:bg-[#1C1C1E] rounded-xl p-4 cursor-pointer shadow-sm hover:shadow-md transition-all flex flex-col gap-2 border border-transparent hover:border-apple-blue/30 dark:border-white/5"
            onClick={() => onOpenDetail(job)}
        >
            <div className="flex justify-between items-start">
                <h4 className="font-bold text-[14px] text-apple-text dark:text-white leading-snug line-clamp-2">{job.title}</h4>
            </div>
            <p className="text-[12px] text-apple-gray dark:text-gray-400 font-medium truncate">{job.company}</p>
            <div className="flex items-center justify-between mt-1">
                 <div className="flex items-center gap-2">
                     <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: job.seniorityScore === 'Senior' || job.seniorityScore === 'Lead' ? '#34C759' : '#FFCC00' }}></div>
                     {status === 'applied' && <FollowUpTimer appliedDate={job.appliedDate} />}
                 </div>
                 <span className="text-[11px] font-bold opacity-60">{analysis?.score || '--'}%</span>
            </div>
        </div>
      );
  }

  return (
    <div 
        onClick={() => isSelectMode ? onSelect?.(job.id) : onOpenDetail(job)}
        className={`apple-card p-8 group cursor-pointer border relative transition-all duration-300 ${isSelected ? 'ring-2 ring-apple-blue border-apple-blue scale-[1.01]' : 'border-transparent'} ${status === 'archived' ? 'opacity-50 grayscale' : ''} ${gridSpanClass}`}
    >
      <div className="absolute top-6 right-6 flex flex-col gap-2 z-10">
         {isSelectMode ? (
             <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${isSelected ? 'bg-apple-blue border-apple-blue text-white' : 'border-apple-border dark:border-apple-border-dark bg-white dark:bg-apple-card-dark'}`}>
                {isSelected && <CheckCircle2 size={14} />}
             </div>
         ) : (
             <div className="opacity-0 group-hover:opacity-100 flex flex-col gap-2 transition-opacity">
                {status !== 'archived' && (
                    <button onClick={(e) => { e.stopPropagation(); onToggleStatus(job.id, status); }} className={`w-10 h-10 flex items-center justify-center rounded-full transition-all shadow-sm ${isSavedOrBetter ? 'bg-apple-blue text-white' : 'bg-white dark:bg-apple-card-dark border border-apple-border dark:border-apple-border-dark text-apple-gray'}`}>
                        <Bookmark size={18} fill={isSavedOrBetter ? "currentColor" : "none"} />
                    </button>
                )}
                <button onClick={(e) => { e.stopPropagation(); onDelete(job.id); }} className="w-10 h-10 flex items-center justify-center rounded-full bg-white dark:bg-apple-card-dark border border-apple-border dark:border-apple-border-dark hover:bg-red-500 hover:text-white text-apple-gray transition-all shadow-sm">
                    {status === 'archived' ? <Trash2 size={18} /> : <Archive size={18} />}
                </button>
             </div>
         )}
      </div>

      <div className="flex flex-col sm:flex-row gap-8 items-start h-full">
          <div className="shrink-0 pt-1 hidden sm:block">
            {analysis?.score ? <MatchGauge score={analysis.score} /> : (
                <div className="w-12 h-12 rounded-full border-2 border-dashed border-apple-border dark:border-apple-border-dark flex items-center justify-center text-[10px] text-apple-gray font-bold">NEW</div>
            )}
          </div>

          <div className="flex-1 pr-8 flex flex-col h-full">
             <div className="mb-2 flex flex-wrap items-center gap-2">
                 <h3 className={`font-semibold tracking-tight group-hover:text-apple-blue transition-colors ${isHighValue ? 'text-2xl md:text-3xl' : 'text-2xl'}`}>{job.title}</h3>
                 {job.isRelatedDiscovery && <span className="bg-yellow-400 text-black text-[9px] font-bold px-1.5 py-0.5 rounded-sm">RECOMMENDED</span>}
                 {analysis?.isHighValue && <span className="bg-[#E6F4EA] text-[#137333] text-[9px] font-bold px-1.5 py-0.5 rounded-sm flex items-center gap-0.5"><Zap size={10} fill="currentColor"/> HIGH VALUE</span>}
             </div>

             <div className="flex items-center gap-3 text-sm font-medium text-apple-gray dark:text-gray-400 mb-4">
                <span className="flex items-center gap-1.5"><Briefcase size={14}/> {job.company}</span>
                <span className="text-apple-border dark:text-white/10">•</span>
