                {status === 'applied' && (
                    <>
                        <span className="text-apple-border dark:text-white/10">•</span>
                        <FollowUpTimer appliedDate={job.appliedDate} />
                    </>
                )}
             </div>

             <div className="flex flex-wrap items-center gap-2 mb-4">
                {job.seniorityScore && (
                     <span className="px-3 py-1 bg-apple-bg dark:bg-white/5 rounded-full text-[11px] font-bold flex items-center gap-1.5">
                        <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: job.seniorityScore === 'Senior' || job.seniorityScore === 'Lead' ? '#34C759' : '#FFCC00' }}></div>
                        {job.seniorityScore} Seniority
                     </span>
                )}
             </div>

             <p className={`text-gray-600 dark:text-gray-400 line-clamp-2 mb-6 ${isHighValue ? 'text-base' : 'text-sm'}`}>{analysis?.verdict || job.summary}</p>

             <div className="mt-auto">
                 {!isSelectMode && (
                    <div className="flex items-center gap-4">
                        <button onClick={(e) => { e.stopPropagation(); onOpenDetail(job, 'strategy'); }} className="flex items-center gap-1.5 text-sm font-bold text-apple-blue hover:underline">
                            Build Strategy <ArrowRight size={16} />
                        </button>
                        <a href={applyUrl} target="_blank" rel="noreferrer" onClick={(e) => e.stopPropagation()} className="text-[13px] font-medium text-apple-gray hover:text-apple-text transition-colors">Source Details</a>
                    </div>
                 )}
             </div>
          </div>
      </div>
    </div>
  );
};

