                            <div className="lg:col-span-3 space-y-8 sticky top-[80px] self-start z-10 pr-2">
                                <div><div className="flex items-center justify-between mb-3 px-2"><h3 className="text-[11px] font-bold text-[#86868b] dark:text-[#98989D] uppercase tracking-wider">Locations</h3>{cityFilter !== 'All' && <button onClick={() => setCityFilter('All')} className="text-[10px] font-bold text-[#0071e3] dark:text-[#0A84FF] hover:underline">Reset</button>}</div>
