                                })}</div></div>
                                <div className="w-full h-px bg-[#d2d2d7]/50 dark:bg-[#38383A]"></div>
                                <div className="px-2"><StatsPanel jobs={jobsInCurrentTab} selectedIndustry={industryFilter} onSelectIndustry={setIndustryFilter}/></div>
