                                    </div>
                                    <div className="flex items-center gap-2"><span className="text-[11px] text-[#86868b] font-medium mr-1">Sort by:</span><button onClick={() => setSortBy(sortBy === 'date' ? 'score' : 'date')} className="text-[11px] font-bold text-[#0071e3] hover:underline flex items-center gap-1">{sortBy === 'date' ? 'Date' : 'Match Score'} <ArrowDownUp size={12}/></button></div>
                                </div>
                                {isSelectMode && selectedJobIds.size > 0 && (
                                    <div className="mb-6 p-4 bg-white dark:bg-[#1C1C1E] rounded-2xl border border-[#0071e3] flex items-center justify-between animate-in slide-in-from-top-4 duration-300">
