                                        <div className="flex items-center gap-3">
                                            <button onClick={handleBulkArchive} className="flex items-center gap-2 px-4 py-2 bg-[#f5f5f7] dark:bg-[#2C2C2E] rounded-full text-xs font-bold hover:bg-[#e8e8ed] transition-colors"><Archive size={14}/> Archive</button>
                                            <button onClick={handleBulkDelete} className="flex items-center gap-2 px-4 py-2 bg-[#FF3B30]/10 text-[#FF3B30] rounded-full text-xs font-bold hover:bg-[#FF3B30]/20 transition-colors"><Trash2 size={14}/> Delete Permanent</button>
                                        </div>
                                    </div>
                                )}
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 auto-rows-min">
                                    {filteredJobs.length === 0 ? (
                                        <div className="col-span-full py-20 text-center text-[#86868b]"><p className="text-lg font-medium">No opportunities found.</p></div>
                                    ) : (
                                        filteredJobs.map(job => (
                                            <JobCard 
                                                key={job.id} 
                                                job={job} 
                                                onOpenDetail={handleOpenDetail} 
                                                onToggleStatus={toggleJobStatus} 
                                                onDelete={handleDelete} 
                                                isSelectMode={isSelectMode} 
                                                isSelected={selectedJobIds.has(job.id)} 
                                                onSelect={toggleJobSelection} 
                                            />
                                        ))
                                    )}
                                </div>
                            </div>
                        </div>
                    </>
                )}
                {currentView === ViewState.KANBAN && (<div className="h-[calc(100vh-100px)] animate-fade-in-up flex flex-col w-full"><div className="flex items-center justify-between mb-8 w-full max-w-[1024px] mx-auto px-6"><h1 className="text-[40px] font-semibold text-[#1d1d1f] dark:text-white tracking-tight">Pipeline</h1><button onClick={() => setIsAddLinkOpen(true)} className="h-10 px-5 rounded-full bg-[#1d1d1f] dark:bg-white hover:bg-black dark:hover:bg-[#E5E5EA] text-white dark:text-black text-sm font-medium transition-all flex items-center gap-2 shadow-lg"><Plus size={16} /> Add Job</button></div><div className="flex-1 min-h-0 w-full"><KanbanBoard jobs={allJobs} onGenerateKit={(job) => handleOpenDetail(job, 'strategy')} onToggleStatus={updateJobStatus} onDelete={handleDelete} onOpenDetail={handleOpenDetail} onOpenAddModal={() => setIsAddLinkOpen(true)}/></div></div>)}
                {currentView === ViewState.CV_EDITOR && (<div className="h-[calc(100vh-60px)] animate-fade-in-up flex flex-col items-center"><div className="w-full max-w-[1024px] mb-6 px-6"><h1 className="text-[40px] font-semibold text-[#1d1d1f] dark:text-white tracking-tight">{targetJobForEditor ? 'War Room' : 'Resume'}</h1></div><div className="flex-1 w-full relative"><CVEditor targetJob={targetJobForEditor} allJobs={allJobs} /></div></div>)}
            </div>
        </div>

      <JobDetailModal isOpen={modalOpen} onClose={() => setModalOpen(false)} job={selectedJob} onGenerateKit={handleGenerateKit} initialTab={initialModalTab} onUpdateJob={handleUpdateJob} onReAnalyze={handleReAnalyzeJob} onTailorResume={handleTailorResume}/>
      <AddLinkModal isOpen={isAddLinkOpen} onClose={() => setIsAddLinkOpen(false)} onAdd={handleAddManualJob} existingJobs={allJobs}/>
    </div>
  );
};

export default App;

import React from 'react';
import { Job } from '../types';
import { Briefcase, MapPin, Trash2, Bookmark, Archive, Zap, Users, Clock, Flame, CheckCircle2 } from 'lucide-react';

interface JobCardProps {
  job: Job;
  onOpenDetail: (job: Job, tab?: 'brief' | 'strategy') => void;
  onToggleStatus: (id: string, currentStatus: Job['status']) => void;
  onDelete: (id: string) => void;
  isKanban?: boolean;
  isSelected?: boolean;
  onSelect?: (id: string) => void;
  isSelectMode?: boolean;
}

const FollowUpTimer = ({ appliedDate }: { appliedDate?: string }) => {
    if (!appliedDate) return null;
    const applied = new Date(appliedDate);
    const now = new Date();
    const diffTime = Math.abs(now.getTime() - applied.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)); 
    const followUpDay = 7;
    const remaining = followUpDay - diffDays;

    if (remaining <= 0) return <span className="text-[10px] font-bold text-red-500 flex items-center gap-1 animate-pulse"><Flame size={12} /> ACTION REQUIRED</span>;
    return <span className="text-[10px] font-bold text-apple-gray flex items-center gap-1"><Clock size={10} /> {remaining}d to follow-up</span>;
};

const JobCard: React.FC<JobCardProps> = ({ job, onOpenDetail, onToggleStatus, onDelete, isKanban, isSelected, onSelect, isSelectMode }) => {
  const analysis = job.analysis;
  const status = job.status || 'new';
  const isSavedOrBetter = ['saved', 'applied', 'assessment', 'interview', 'offer'].includes(status);

  const score = analysis?.score || 0;
  let scoreColor = 'bg-gray-100 text-gray-600 dark:bg-white/10 dark:text-gray-300';
  if (score >= 85) scoreColor = 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400';
  else if (score >= 70) scoreColor = 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400';
  else if (score >= 50) scoreColor = 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400';

  if (isKanban) {
      return (
        <div 
            className="bg-white dark:bg-[#1C1C1E] rounded-xl p-4 cursor-pointer shadow-sm hover:shadow-md transition-all flex flex-col gap-2 border border-transparent hover:border-apple-blue/30 dark:border-white/5"
            onClick={() => onOpenDetail(job)}
        >
            <div className="flex justify-between items-start">
                <h4 className="font-bold text-[14px] text-apple-text dark:text-white leading-snug line-clamp-2">{job.title}</h4>
            </div>
            <p className="text-[12px] text-apple-gray dark:text-gray-400 font-medium truncate">{job.company}</p>
            <div className="flex items-center justify-between mt-1">
                 <div className="flex items-center gap-2">
                     <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: job.seniorityScore === 'Senior' || job.seniorityScore === 'Lead' ? '#34C759' : '#FFCC00' }}></div>
                     {status === 'applied' && <FollowUpTimer appliedDate={job.appliedDate} />}
                 </div>
                 <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded-md ${scoreColor}`}>{score}%</span>
            </div>
        </div>
      );
  }

  return (
    <div 
        onClick={() => isSelectMode ? onSelect?.(job.id) : onOpenDetail(job)}
        className={`apple-card p-6 group cursor-pointer border relative transition-all duration-300 ${isSelected ? 'ring-2 ring-apple-blue border-apple-blue scale-[1.01]' : 'border-transparent'} ${status === 'archived' ? 'opacity-50 grayscale' : ''} bg-white dark:bg-[#1C1C1E]`}
    >
      <div className="absolute top-4 right-4 flex flex-col gap-2 z-10">
         {isSelectMode ? (
             <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${isSelected ? 'bg-apple-blue border-apple-blue text-white' : 'border-apple-border dark:border-apple-border-dark bg-white dark:bg-apple-card-dark'}`}>
                {isSelected && <CheckCircle2 size={14} />}
             </div>
         ) : (
             <div className="opacity-0 group-hover:opacity-100 flex flex-col gap-2 transition-opacity">
                {status !== 'archived' && (
                    <button onClick={(e) => { e.stopPropagation(); onToggleStatus(job.id, status); }} className={`w-8 h-8 flex items-center justify-center rounded-full transition-all shadow-sm ${isSavedOrBetter ? 'bg-apple-blue text-white' : 'bg-white dark:bg-apple-card-dark border border-apple-border dark:border-apple-border-dark text-apple-gray'}`}>
                        <Bookmark size={14} fill={isSavedOrBetter ? "currentColor" : "none"} />
                    </button>
                )}
                <button onClick={(e) => { e.stopPropagation(); onDelete(job.id); }} className="w-8 h-8 flex items-center justify-center rounded-full bg-white dark:bg-apple-card-dark border border-apple-border dark:border-apple-border-dark hover:bg-red-500 hover:text-white text-apple-gray transition-all shadow-sm">
                    {status === 'archived' ? <Trash2 size={14} /> : <Archive size={14} />}
                </button>
             </div>
         )}
      </div>

      <div className="flex flex-col h-full">
         <div className="flex items-start justify-between mb-2 pr-8">
             <div className="flex flex-col">
                 <h3 className="text-lg font-semibold tracking-tight group-hover:text-apple-blue transition-colors leading-tight mb-1">{job.title}</h3>
                 <div className="flex items-center gap-2 text-sm font-medium text-apple-gray dark:text-gray-400">
                    <span className="flex items-center gap-1"><Briefcase size={12}/> {job.company}</span>
                    <span className="text-apple-border dark:text-white/10">•</span>
                    <span className="flex items-center gap-1"><MapPin size={12}/> {job.location}</span>
                 </div>
             </div>
         </div>

         <div className="flex flex-wrap items-center gap-2 mb-3 mt-1">
            {analysis?.score > 0 && <span className={`text-[11px] font-bold px-2 py-1 rounded-md ${scoreColor}`}>{analysis.score}% Match</span>}
            {job.seniorityScore && (
                 <span className="px-2 py-1 bg-apple-bg dark:bg-white/5 rounded-md text-[11px] font-bold flex items-center gap-1.5">
                    <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: job.seniorityScore === 'Senior' || job.seniorityScore === 'Lead' ? '#34C759' : '#FFCC00' }}></div>
                    {job.seniorityScore}
                 </span>
            )}
            {analysis?.isHighValue && <span className="bg-[#E6F4EA] text-[#137333] text-[10px] font-bold px-2 py-1 rounded-md flex items-center gap-1"><Zap size={10} fill="currentColor"/> High Value</span>}
            {status === 'applied' && <FollowUpTimer appliedDate={job.appliedDate} />}
         </div>

         <p className="text-sm text-gray-600 dark:text-gray-400 line-clamp-2 leading-relaxed mb-1">{analysis?.verdict || job.summary}</p>
      </div>
    </div>
  );
};

export default JobCard;
